import React, { useState, useEffect } from 'react';
import { Dish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);

  // Load data from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('my-dishes');
    if (saved) {
      try {
        setDishes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load dishes", e);
      }
    }
  }, []);

  // Sync state to localStorage
  useEffect(() => {
    localStorage.setItem('my-dishes', JSON.stringify(dishes));
  }, [dishes]);

  const addDish = (dish: Dish) => {
    setDishes(prev => [dish, ...prev]);
  };

  const removeDish = (id: string) => {
    setDishes(prev => prev.filter(d => d.id !== id));
  };

  const viewRecipe = (id: string) => {
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    switch (currentView) {
      case 'collection':
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
      case 'suggest':
        return <SuggestView onAddDish={addDish} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? <RecipeView dish={dish} onBack={() => setCurrentView('collection')} /> : <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
      default:
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <span className="text-3xl">🍲</span>
          美味秘籍
        </h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            饕餮札记
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            妙手生花
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8">
        {renderView()}
      </main>

      <footer className="p-6 text-center text-gray-500 text-sm border-top border-gray-100 bg-gray-50">
        © {new Date().getFullYear()} 美味秘籍 - 您的智能 AI 厨房助手
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Category, Dish } from '../types';
import DishCard from '../components/DishCard';
import { geminiService } from '../services/geminiService';

interface CollectionViewProps {
  dishes: Dish[];
  onAddDish: (dish: Dish) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
}

const CollectionView: React.FC<CollectionViewProps> = ({ dishes, onAddDish, onDeleteDish, onViewRecipe }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  const categories = ['全部', ...Object.values(Category)];

  const filteredDishes = dishes.filter(dish => {
    const matchesSearch = dish.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const handleAddDish = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDishName.trim()) return;

    setLoading(true);
    try {
      const details = await geminiService.getRecipeDetails(newDishName);
      const newDish: Dish = {
        id: Date.now().toString(),
        name: newDishName,
        ...details,
        createdAt: Date.now()
      };
      onAddDish(newDish);
      setNewDishName('');
      setIsAdding(false);
    } catch (err) {
      alert("添加失败，请稍后重试。");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">私房味蕾库</h2>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"
        >
          <span>➕</span> 添加新菜肴
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <input 
            type="text" 
            placeholder="搜索您的收藏..."
            className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 focus:border-transparent outline-none transition"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>
        <div className="flex overflow-x-auto pb-2 gap-2 scrollbar-hide">
