import { GoogleGenAI, Type } from "@google/genai";
import { Category, Ingredient, SuggestedDish } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string): Promise<{
    category: Category;
    ingredients: Ingredient[];
    instructions: string[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `提供菜肴 "${dishName}" 的详细菜谱信息。请以中文回答。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "分步骤的烹饪说明",
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的简短介绍",
            },
          },
          required: ["category", "ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("解析菜谱失败");
    }
  }

  /**
   * Generates a cover image for the dish.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: `A high-quality, professional food photography of ${dishName}, appetizing and beautifully plated on a clean dining table. Natural lighting, vibrant colors, 16:9 aspect ratio.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image part found in response");
  }

  /**
   * Suggests dishes based on a list of ingredients.
   */
  async suggestDishes(ingredients: string[]): Promise<SuggestedDish[]> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有以下食材：${ingredients.join(", ")}。请根据这些食材推荐 3-5 道适合做的中国菜，并说明推荐理由。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING, description: "菜名" },
              category: { type: Type.STRING, description: "分类" },
              reason: { type: Type.STRING, description: "推荐理由，解释为什么这些食材适合做这道菜" },
            },
            required: ["name", "category", "reason"],
          },
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse suggestions", e);
      throw new Error("生成建议失败");
    }
  }
}

