import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: string[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `提供菜肴 "${dishName}" 的详细菜谱信息。请以中文回答。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的地域分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            dishType: {
              type: Type.STRING,
              description: "菜肴的类型分类 (荤菜, 素菜, 汤羹, 海鲜, 凉菜, 主食, 小吃)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "分步骤的烹饪说明",
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的简短介绍",
            },
          },
          required: ["category", "dishType", "ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("解析菜谱失败");
    }
  }

  /**
   * Modifies an existing recipe based on user instructions.
   */
  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: string[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        当前的菜肴是: "${dish.name}"
        当前的介绍: "${dish.description}"
        当前的配料: ${JSON.stringify(dish.ingredients)}
        当前的步骤: ${JSON.stringify(dish.instructions)}

        用户希望进行的调整是: "${instruction}"

        请根据用户的要求，重写这道菜的配料、步骤和描述。
        例如，如果用户要求"精简食材"，请保留最核心的配料。
        如果是"更辣"，请在配料和步骤中体现。
        请以中文回答。
      `,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
            },
            description: {
              type: Type.STRING,
            },
          },
          required: ["ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse modified recipe", e);
      throw new Error("调整菜谱失败");
    }
  }

  /**
   * Generates a cover image for the dish.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: `A high-quality, professional food photography of ${dishName}, appetizing and beautifully plated on a clean dining table. Natural lighting, vibrant colors, 16:9 aspect ratio.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image part found in response");
  }

  /**
   * Suggests dishes based on a list of ingredients.
   */
  async suggestDishes(ingredients: string[]): Promise<SuggestedDish[]> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有以下食材：${ingredients.join(", ")}。请根据这些食材推荐 3-5 道适合做的中国菜，并说明推荐理由。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING, description: "菜名" },
              category: { type: Type.STRING, description: "地域分类" },
              dishType: { type: Type.STRING, description: "类型分类" },
              reason: { type: Type.STRING, description: "推荐理由，解释为什么 these 食材适合做这道菜" },
            },
            required: ["name", "category", "dishType", "reason"],
          },
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse suggestions", e);
      throw new Error("生成建议失败");
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useEffect } from 'react';
import { Dish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);

  // 加载本地数据
  useEffect(() => {
    const saved = localStorage.getItem('my-dishes');
    if (saved) {
      try {
        setDishes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load dishes", e);
      }
    }
  }, []);

  // 同步到本地存储
  useEffect(() => {
    localStorage.setItem('my-dishes', JSON.stringify(dishes));
  }, [dishes]);

  const addDish = (dish: Dish) => {
    setDishes(prev => [dish, ...prev]);
  };

  const updateDish = (updatedDish: Dish) => {
    setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
  };

  const removeDish = (id: string) => {
    setDishes(prev => prev.filter(d => d.id !== id));
  };

  const viewRecipe = (id: string) => {
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    switch (currentView) {
      case 'collection':
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
      case 'suggest':
        return <SuggestView onAddDish={addDish} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />
        );
      default:
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <span className="text-3xl">🍲</span>
          美味秘籍
        </h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            食材发现
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8">
        {renderView()}
      </main>

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50">
        © {new Date().getFullYear()} 美味秘籍 - 您的智能 AI 厨房助手
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
