export enum Category {
  SICHUAN = '川菜',
  CANTONESE = '粤菜',
  SHANDONG = '鲁菜',
  HUAIYANG = '淮扬菜',
  NOODLES = '面食/主食',
  DESSERT = '甜点/点心',
  HOME_COOKING = '家常菜',
  OTHER = '其他'
}

export enum DishType {
  MEAT = '荤菜',
  VEGGIES = '素菜',
  SOUP = '汤羹',
  SEAFOOD = '海鲜',
  COLD = '凉菜',
  STAPLE = '主食',
  SNACK = '小吃'
}

export interface Ingredient {
  name: string;
  amount: string;
}

export interface InstructionStep {
  text: string;
  timeMinutes: number;
  imageUrl?: string;
}

export interface Dish {
  id: string;
  name: string;
  category: Category;
  dishType?: DishType;
  ingredients: Ingredient[];
  instructions: InstructionStep[];
  description: string;
