import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish, InstructionStep } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `提供菜肴 "${dishName}" 的详细菜谱信息。请务必为每一个步骤估算所需时间（分钟）。请以中文回答。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的地域分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            dishType: {
              type: Type.STRING,
              description: "菜肴的类型分类 (荤菜, 素菜, 汤羹, 海鲜, 凉菜, 主食, 小吃)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING, description: "步骤描述" },
                  timeMinutes: { type: Type.INTEGER, description: "该步骤预计所需时间（分钟）" },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的简短介绍",
            },
          },
          required: ["category", "dishType", "ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("解析菜谱失败");
    }
  }

  /**
   * Modifies an existing recipe based on user instructions.
   */
  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        当前的菜肴是: "${dish.name}"
        当前的介绍: "${dish.description}"
        当前的配料: ${JSON.stringify(dish.ingredients)}
        当前的步骤: ${JSON.stringify(dish.instructions.map(s => ({ text: s.text, time: s.timeMinutes })))}

        用户希望进行的调整是: "${instruction}"

        请根据用户的要求，重写这道菜的配料、步骤（含时间）和描述。请以中文回答。
      `,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  timeMinutes: { type: Type.INTEGER },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: {
              type: Type.STRING,
            },
          },
          required: ["ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse modified recipe", e);
      throw new Error("调整菜谱失败");
    }
  }

  /**
   * Generates a cover image for the dish.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: `A high-quality, professional food photography of ${dishName}, appetizing and beautifully plated on a clean dining table. Natural lighting, vibrant colors, 16:9 aspect ratio.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image part found in response");
  }

  /**
   * Generates an image for a specific cooking step.
   */
  async generateStepImage(stepDescription: string, dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: `Close-up cooking action shot in a kitchen: ${stepDescription}. Making ${dishName}. Professional lighting, clear hands-on demonstration, high resolution, 16:9 aspect ratio.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9"
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No step image part found");
  }

  /**
   * Suggests dishes based on a list of ingredients.
   */
  async suggestDishes(ingredients: string[]): Promise<SuggestedDish[]> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有以下食材：${ingredients.join(", ")}。请根据这些食材推荐 3-5 道适合做的中国菜，并说明推荐理由。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING, description: "菜名" },
              category: { type: Type.STRING, description: "地域分类" },
              dishType: { type: Type.STRING, description: "类型分类" },
              reason: { type: Type.STRING, description: "推荐理由，解释为什么 these 食材适合做这道菜" },
            },
            required: ["name", "category", "dishType", "reason"],
          },
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse suggestions", e);
      throw new Error("生成建议失败");
    }
  }
}

