import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish, InstructionStep } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `请作为专业厨师，提供菜肴 "${dishName}" 的详细菜谱信息。
      要求：
      1. 必须包含准备和烹饪的所有关键步骤。
      2. 每个步骤必须估算所需时间（单位：分钟，请提供整数）。
      3. 语言使用中文。
      4. 返回符合 schema 定义的 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的地域分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            dishType: {
              type: Type.STRING,
              description: "菜肴的类型分类 (荤菜, 素菜, 汤羹, 海鲜, 凉菜, 主食, 小吃)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING, description: "步骤描述" },
                  timeMinutes: { type: Type.INTEGER, description: "预计时间（分钟）" },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的背景或风味简介",
            },
          },
          required: ["category", "dishType", "ingredients", "instructions", "description"],
        },
      },
    });

    try {
      const text = response.text;
      if (!text) throw new Error("Empty response");
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("生成菜谱失败，请重试。");
    }
  }

  /**
   * Modifies an existing recipe.
   */
  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        修改菜肴: "${dish.name}"
        修改指令: "${instruction}"
        当前信息: ${JSON.stringify({
          desc: dish.description,
          ings: dish.ingredients,
          steps: dish.instructions?.map(s => (typeof s === 'string' ? s : s.text))
        })}
        请根据指令重写，保持 JSON 格式。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  timeMinutes: { type: Type.INTEGER },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: { type: Type.STRING },
          },
          required: ["ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      throw new Error("调整菜谱失败");
    }
  }

  /**
   * Generates images with lower resolution/size hints in prompt to save storage.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `High quality food photography of ${dishName}, elegant plating, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Image failed");
  }

  async generateStepImage(stepDescription: string, dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Cooking step: ${stepDescription} for ${dishName}. Kitchen action shot, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Step image failed");
  }

  async suggestDishes(ingredients: string[]): Promise<SuggestedDish[]> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有：${ingredients.join(", ")}。推荐 3-5 道中国菜。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
            },
            required: ["name", "category", "dishType", "reason"],
          },
        },
      },
    });
    return JSON.parse(response.text);
  }
}

export const geminiService = new GeminiService();

import React, { useState, useEffect } from 'react';
import { Dish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);

  // 加载本地数据
  useEffect(() => {
    const saved = localStorage.getItem('my-dishes');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          setDishes(parsed);
        }
      } catch (e) {
        console.error("Failed to load dishes", e);
      }
    }
  }, []);

  // 同步到本地存储，带错误处理
  useEffect(() => {
    if (dishes.length === 0 && !localStorage.getItem('my-dishes')) return;
    try {
      localStorage.setItem('my-dishes', JSON.stringify(dishes));
    } catch (e) {
      console.error("Storage limit exceeded!", e);
      alert("您的菜谱库已满（浏览器存储限制）。请尝试删除一些旧菜肴后再添加。");
    }
  }, [dishes]);

  const addDish = (dish: Dish) => {
    setDishes(prev => [dish, ...prev]);
  };

  const updateDish = (updatedDish: Dish) => {
    setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
  };

  const removeDish = (id: string) => {
    setDishes(prev => prev.filter(d => d.id !== id));
  };

  const viewRecipe = (id: string) => {
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    switch (currentView) {
      case 'collection':
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
      case 'suggest':
        return <SuggestView onAddDish={addDish} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />
        );
      default:
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <span className="text-3xl">🍲</span>
          美味秘籍
        </h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            食材发现
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8">
        {renderView()}
      </main>

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50">
        © {new Date().getFullYear()} 美味秘籍 - 您的智能 AI 厨房助手
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Category, Dish, DishType, InstructionStep } from '../types';
import DishCard from '../components/DishCard';
import { geminiService } from '../services/geminiService';

interface CollectionViewProps {
  dishes: Dish[];
  onAddDish: (dish: Dish) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
}

const CollectionView: React.FC<CollectionViewProps> = ({ dishes, onAddDish, onDeleteDish, onViewRecipe }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const matchesSearch = dish.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleAddDish = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDishName.trim()) return;

    setLoading(true);
    setLoadingStatus('正在构思美味菜谱...');
    try {
      // 1. 获取文字内容
      const details = await geminiService.getRecipeDetails(newDishName);

      // 2. 准备并行生成图片 (封面 + 前3个步骤)
      setLoadingStatus('正在通过 AI 绘制精美图片...');

      // 我们只为前 3 个核心步骤生成图片以节省本地存储空间
      const MAX_STEP_IMAGES = 3;

      const imagePromises: Promise<string | null>[] = [
        geminiService.generateDishImage(newDishName).catch(() => null)
      ];

      for (let i = 0; i < Math.min(details.instructions.length, MAX_STEP_IMAGES); i++) {
        imagePromises.push(
          geminiService.generateStepImage(details.instructions[i].text, newDishName).catch(() => null)
        );
      }

      const images = await Promise.all(imagePromises);
      const coverUrl = images[0] || undefined;

      // 3. 构建最终步骤数据
      const finalSteps: InstructionStep[] = details.instructions.map((step, idx) => ({
        ...step,
        imageUrl: idx < MAX_STEP_IMAGES ? (images[idx + 1] || undefined) : undefined
      }));

      setLoadingStatus('保存到您的私人收藏...');
      const newDish: Dish = {
        id: Date.now().toString(),
        name: newDishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      onAddDish(newDish);
      setNewDishName('');
      setIsAdding(false);
    } catch (err) {
      console.error(err);
      alert(err instanceof Error ? err.message : "添加失败，请检查网络或重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"
        >
          <span>➕</span> 添加新菜肴
        </button>
      </div>

      <div className="space-y-4">
        <div className="relative">
          <input 
            type="text" 
            placeholder="搜索您的收藏..."
            className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 focus:border-transparent outline-none transition"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>

        <div className="space-y-2">
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <span className="text-xs font-bold text-gray-400 whitespace-nowrap uppercase tracking-wider pr-2">菜系:</span>
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1.5 rounded-full text-xs whitespace-nowrap transition ${selectedCategory === cat ? 'bg-orange-500 text-white font-bold' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                {cat}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <span className="text-xs font-bold text-gray-400 whitespace-nowrap uppercase tracking-wider pr-2">类型:</span>
            {dishTypes.map(type => (
              <button
                key={type}
                onClick={() => setSelectedDishType(type)}
                className={`px-3 py-1.5 rounded-full text-xs whitespace-nowrap transition ${selectedDishType === type ? 'bg-green-500 text-white font-bold' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                {type}
              </button>
            ))}
          </div>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleAddDish} className="space-y-4">
              <input 
                autoFocus
                type="text" 
                placeholder="例如：红烧肉、麻辣香锅..."
                className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400"
                value={newDishName}
                onChange={(e) => setNewDishName(e.target.value)}
                disabled={loading}
              />
              <p className="text-sm text-gray-500">
                人工智能将自动为您寻找配料表、估算烹饪时间，并为核心步骤生成示意图。
              </p>
              <div className="flex gap-4 pt-4">
                <button 
                  type="button"
                  onClick={() => setIsAdding(false)}
                  className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition"
                  disabled={loading}
                >
                  取消
                </button>
                <button 
                  type="submit"
                  disabled={loading || !newDishName.trim()}
                  className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 transition shadow-lg shadow-orange-200 disabled:opacity-50 min-w-[140px]"
                >
                  {loading ? (
                    <span className="flex flex-col items-center justify-center gap-1">
                      <span className="flex items-center gap-2">
                        <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        制作中...
                      </span>
                      <span className="text-[10px] opacity-80 font-normal truncate max-w-full px-2">{loadingStatus}</span>
                    </span>
                  ) : '立即添加'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {filteredDishes.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDishes.map(dish => (
            <DishCard 
              key={dish.id} 
              dish={dish} 
              onView={onViewRecipe}
