interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;

    setLoading(true);
    setLoadingStatus('正在重构菜谱细节...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);

      const MAX_STEP_IMAGES = 2; // 修改时只为前2步生成新图以节省空间
      const imagePromises: Promise<string | null>[] = [];
      for (let i = 0; i < Math.min(updatedDetails.instructions.length, MAX_STEP_IMAGES); i++) {
        imagePromises.push(geminiService.generateStepImage(updatedDetails.instructions[i].text, dish.name).catch(() => null));
      }

      const stepImages = await Promise.all(imagePromises);

      const newSteps: InstructionStep[] = updatedDetails.instructions.map((step, idx) => ({
        ...step,
        imageUrl: idx < MAX_STEP_IMAGES ? (stepImages[idx] || undefined) : undefined
      }));

      const updatedDish: Dish = {
        ...dish,
        ...updatedDetails,
        instructions: newSteps
      };
      onUpdateDish(updatedDish);
      setIsModifying(false);
      setInstruction('');
    } catch (err) {
      alert("调整失败，请重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
