        <button 
          onClick={() => setIsModifying(!isModifying)}
          className={`px-4 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-sm ${isModifying ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600 border border-indigo-100 hover:bg-indigo-50'}`}
        >
          <span>✨</span> {isModifying ? '取消调整' : '调整菜谱'}
