import { Dish } from "../types";

const DB_NAME = "DeliciousSecretsDB";
const STORE_NAME = "dishes";
const DB_VERSION = 1;

export class StorageService {
  private db: IDBDatabase | null = null;

  /**
   * 初始化数据库
   */
  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onerror = () => reject("无法打开本地数据库");

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: "id" });
        }
      };
    });
  }

  /**
   * 获取所有菜谱
   */
  async getAllDishes(): Promise<Dish[]> {
    if (!this.db) await this.init();
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([STORE_NAME], "readonly");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject("读取数据失败");
    });
  }

  /**
   * 保存或更新菜谱
   */
  async saveDish(dish: Dish): Promise<void> {
    if (!this.db) await this.init();
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(dish);

      request.onsuccess = () => resolve();
      request.onerror = () => reject("写入数据失败");
    });
  }

  /**
   * 删除菜谱
   */
  async deleteDish(id: string): Promise<void> {
    if (!this.db) await this.init();
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject("删除数据失败");
    });
  }

  /**
   * 迁移旧的 localStorage 数据
   */
  async migrateFromLocalStorage(): Promise<Dish[]> {
    const saved = localStorage.getItem("my-dishes");
    if (!saved) return [];

    try {
      const dishes = JSON.parse(saved);
      if (Array.isArray(dishes)) {
        for (const dish of dishes) {
          await this.saveDish(dish);
        }
        localStorage.removeItem("my-dishes"); // 迁移成功后清除
        return dishes;
      }
    } catch (e) {
      console.error("迁移失败", e);
    }
    return [];
  }
}

export const storageService = new StorageService();

import React, { useState, useEffect } from 'react';
import { Dish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);

  // 初始化并加载数据（包括迁移）
  useEffect(() => {
    const initApp = async () => {
      try {
        await storageService.init();

        // 尝试从 localStorage 迁移数据
        let loadedDishes = await storageService.migrateFromLocalStorage();

        // 如果没有迁移数据，则读取数据库
        if (loadedDishes.length === 0) {
          loadedDishes = await storageService.getAllDishes();
        }

        // 按创建时间倒序排列
        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
      } catch (e) {
        console.error("初始化失败", e);
      } finally {
        setIsInitializing(false);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
    } catch (e) {
      alert("保存失败，请检查浏览器存储权限。");
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
    } catch (e) {
      alert("更新失败");
    }
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
      } catch (e) {
        alert("删除失败");
      }
    }
  };

  const viewRecipe = (id: string) => {
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-20">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-500 mb-4"></div>
          <p className="text-gray-500">正在开启您的美味秘籍...</p>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
      case 'suggest':
        return <SuggestView onAddDish={addDish} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />
        );
      default:
        return <CollectionView dishes={dishes} onAddDish={addDish} onDeleteDish={removeDish} onViewRecipe={viewRecipe} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <span className="text-3xl">🍲</span>
          美味秘籍
        </h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            食材发现
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8">
        {renderView()}
      </main>

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50">
        © {new Date().getFullYear()} 美味秘籍 - 本地数据库驱动
      </footer>
    </div>
  );
};

