import { Dish } from "../types";

const DB_NAME = "DeliciousSecretsDB";
const STORE_NAME = "dishes";
const DB_VERSION = 2; // 提升版本号以触发更新

export class StorageService {
  private db: IDBDatabase | null = null;
  private isInitializing: boolean = false;

  /**
   * 初始化数据库，增加重试机制
   */
  async init(): Promise<void> {
    if (this.db) return;
    if (this.isInitializing) {
      return new Promise((resolve) => {
        const check = setInterval(() => {
          if (this.db) {
            clearInterval(check);
            resolve();
          }
        }, 100);
      });
    }

    this.isInitializing = true;
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onerror = () => {
        this.isInitializing = false;
        reject("无法打开本地数据库，请检查浏览器权限。");
      };

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        this.isInitializing = false;

        // 自动处理连接关闭的情况
        this.db.onversionchange = () => {
          this.db?.close();
          window.location.reload();
        };

        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: "id" });
        }
      };
    });
  }

  /**
   * 获取所有菜谱，带排序
   */
  async getAllDishes(): Promise<Dish[]> {
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      const transaction = this.db.transaction([STORE_NAME], "readonly");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject("读取数据失败");
    });
  }

  /**
   * 保存或更新菜谱，确保原子性
   */
  async saveDish(dish: Dish): Promise<void> {
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      const transaction = this.db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(dish);

      request.onsuccess = () => resolve();
      request.onerror = () => reject("写入数据失败");
    });
  }

  /**
   * 删除菜谱
   */
  async deleteDish(id: string): Promise<void> {
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      const transaction = this.db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject("删除数据失败");
    });
  }

  /**
   * 强力迁移：确保旧数据不丢失
   */
  async migrateFromLocalStorage(): Promise<Dish[]> {
    const saved = localStorage.getItem("my-dishes");
    if (!saved) return [];

    try {
      const dishes = JSON.parse(saved);
      if (Array.isArray(dishes) && dishes.length > 0) {
        for (const dish of dishes) {
          await this.saveDish(dish);
        }
        // 迁移成功后，备份一份到 localStorage 的另一个 key 中，防止意外
        localStorage.setItem("my-dishes-backup", saved);
        localStorage.removeItem("my-dishes");
        return dishes;
      }
    } catch (e) {
      console.error("迁移过程中出错", e);
    }
    return [];
  }

  async exportData(): Promise<string> {
    const dishes = await this.getAllDishes();
    return JSON.stringify(dishes);
  }

  async importData(json: string): Promise<Dish[]> {
    try {
      const dishes = JSON.parse(json);
      if (!Array.isArray(dishes)) throw new Error("无效格式");
      for (const dish of dishes) {
        await this.saveDish(dish);
      }
      return await this.getAllDishes();
    } catch (e) {
      throw new Error("导入失败");
    }
  }
}

export const storageService = new StorageService();

import React, { useState, useEffect } from 'react';
import { Dish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();

        // 1. 尝试迁移
        await storageService.migrateFromLocalStorage();

        // 2. 加载所有数据
        const loadedDishes = await storageService.getAllDishes();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setIsInitializing(false);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
    } catch (e) {
      setSyncStatus('error');
      alert("保存失败，请检查存储空间。");
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
    } catch (e) {
      setSyncStatus('error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setSyncStatus('saved');
      } catch (e) {
        setSyncStatus('error');
      }
    }
  };

  const viewRecipe = (id: string) => {
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40">
          <div className="relative">
            <div className="animate-spin rounded-full h-16 w-16 border-4 border-orange-100 border-t-orange-500"></div>
            <div className="absolute inset-0 flex items-center justify-center text-xl">🍲</div>
          </div>
          <p className="mt-6 text-gray-500 font-medium animate-pulse">正在同步您的私人菜谱库...</p>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        return (
          <CollectionView 
            dishes={dishes} 
            onAddDish={addDish} 
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            onAddDish={addDish} 
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
          />
        );
      default:
        return (
          <CollectionView 
            dishes={dishes} 
            onAddDish={addDish} 
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
          />
        );
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <span className="text-3xl">🍲</span>
          美味秘籍
        </h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            食材发现
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8">
        {renderView()}
      </main>

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
          {syncStatus === 'error' && (
            <span className="flex items-center gap-1 text-red-500">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd"></path></svg>
              同步故障
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} 美味秘籍</div>
      </footer>
    </div>
  );
};

