import React, { useState, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Dish, SuggestedDish, InstructionStep } from '../types';

interface SuggestViewProps {
  onAddDish: (dish: Dish) => void;
}

const STORAGE_KEY = 'delicious-secrets-last-ingredients';

const SuggestView: React.FC<SuggestViewProps> = ({ onAddDish }) => {
  const [inputValue, setInputValue] = useState('');
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<SuggestedDish[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingDish, setSavingDish] = useState<string | null>(null);

  // 挂载时加载上次保留的食材
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          setIngredients(parsed);
        }
      } catch (e) {
        console.error("无法加载历史食材", e);
      }
    }
  }, []);

  // 当食材变化时自动保存
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(ingredients));
  }, [ingredients]);

  const handleAddIngredient = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const removeIngredient = (name: string) => {
    setIngredients(ingredients.filter(i => i !== name));
  };

  const clearAllIngredients = () => {
    if (ingredients.length > 0 && window.confirm("确定要清空当前的食材列表吗？")) {
      setIngredients([]);
      setSuggestions([]);
    }
  };

  const fetchSuggestions = async () => {
    if (ingredients.length === 0) return;
    setLoading(true);
    try {
      const res = await geminiService.suggestDishes(ingredients);
      setSuggestions(res);
    } catch (err) {
      alert("推荐失败，请重试。");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveToCollection = async (suggested: SuggestedDish) => {
    setSavingDish(suggested.name);
    try {
      const details = await geminiService.getRecipeDetails(suggested.name);

      let imageUrl = '';
      try {
        imageUrl = await geminiService.generateDishImage(suggested.name);
      } catch (imgErr) {
        console.warn("Image generation failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: Date.now().toString(),
        name: suggested.name,
        ...details,
        instructions: finalSteps,
        imageUrl,
        createdAt: Date.now()
      };
      onAddDish(newDish);
      alert(`${suggested.name} 已成功加入您的收藏！`);
    } catch (err) {
      alert("保存失败，请稍后重试。");
    } finally {
      setSavingDish(null);
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-in slide-in-from-bottom duration-500">
      <div className="bg-gradient-to-br from-orange-400 to-red-500 rounded-3xl p-8 text-white mb-8 shadow-2xl">
        <h2 className="text-3xl font-bold mb-4">今天做什么？</h2>
        <p className="opacity-90 mb-6">输入您家里现有的食材，我来帮您出主意。系统已为您自动保留上次的食材。</p>

        <form onSubmit={handleAddIngredient} className="relative mb-6">
          <input 
            type="text"
            placeholder="输入食材名称（如：鸡蛋、西红柿、五花肉）"
            className="w-full px-6 py-4 rounded-2xl text-gray-800 outline-none pr-24 text-lg"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
          />
          <button 
            type="submit"
            className="absolute right-2 top-2 bottom-2 px-6 bg-orange-600 hover:bg-orange-700 rounded-xl font-bold transition"
          >
            添加
          </button>
        </form>

        <div className="flex flex-wrap gap-2 items-center">
          {ingredients.map(ing => (
            <span key={ing} className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-full flex items-center gap-2 border border-white/30 text-sm font-medium transition-all hover:bg-white/30">
              {ing}
              <button onClick={() => removeIngredient(ing)} className="hover:text-red-200 transition-colors">✕</button>
            </span>
          ))}
          {ingredients.length > 0 && (
            <button 
              onClick={clearAllIngredients}
              className="text-xs text-orange-100 hover:text-white underline underline-offset-4 ml-2 opacity-80 hover:opacity-100 transition-opacity"
            >
              清空全部
            </button>
          )}
          {ingredients.length === 0 && <span className="text-orange-100 italic">尚未添加食材...</span>}
        </div>
      </div>

      <div className="text-center mb-10">
        <button 
          onClick={fetchSuggestions}
          disabled={ingredients.length === 0 || loading}
          className="bg-orange-600 hover:bg-orange-700 text-white text-xl font-bold px-12 py-4 rounded-2xl shadow-xl shadow-orange-200 disabled:opacity-50 transition transform hover:scale-105 active:scale-95"
        >
          {loading ? '正在为您灵光一闪...' : '💡 给我一些建议'}
        </button>
      </div>

      {suggestions.length > 0 && (
        <div className="space-y-6">
          <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-6">推荐菜品</h3>
          {suggestions.map((s, idx) => (
            <div key={idx} className="bg-white border border-gray-100 rounded-3xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <h4 className="text-2xl font-bold text-gray-800">{s.name}</h4>
                  <span className="px-2 py-0.5 bg-gray-100 text-gray-500 text-xs rounded uppercase">{s.category}</span>
                </div>
                <p className="text-gray-600 italic">"{s.reason}"</p>
              </div>
              <button 
                onClick={() => handleSaveToCollection(s)}
                disabled={savingDish === s.name}
                className="whitespace-nowrap bg-orange-50 text-orange-600 font-bold px-6 py-3 rounded-2xl hover:bg-orange-500 hover:text-white transition disabled:opacity-50 flex items-center gap-2"
              >
                {savingDish === s.name ? (
                  <>
                    <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    正在保存...
                  </>
                ) : (
                  <>⭐ 收藏到我的菜谱</>
                )}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SuggestView;

import React, { useState, useRef, useEffect } from 'react';
import { Dish, InstructionStep } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  // 菜名编辑状态
  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  // 聊天对话状态
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: 'user' | 'ai', content: string}[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory, isChatOpen]);

  // 当外部数据变化时同步 tempName
  useEffect(() => {
    setTempName(dish.name);
  }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) {
      onUpdateDish({ ...dish, name: trimmed });
    } else {
      setTempName(dish.name);
    }
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;

    setLoading(true);
    setLoadingStatus('正在重构菜谱细节...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);

      const updatedDish: Dish = {
        ...dish,
        ...updatedDetails,
        // 保留原有的步骤图片（如果步骤文本没变）
        instructions: updatedDetails.instructions.map((newStep, idx) => {
          const oldStep = dish.instructions[idx];
          return {
            ...newStep,
            imageUrl: oldStep && oldStep.text === newStep.text ? oldStep.imageUrl : undefined
          };
        })
      };
      onUpdateDish(updatedDish);
      setIsModifying(false);
      setInstruction('');
    } catch (err) {
      alert("调整失败，请重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const generateStepImage = async (index: number) => {
    const step = dish.instructions[index];
    setLoading(true);
    setLoadingStatus(`正在绘制步骤 ${index + 1} 的配图...`);
    try {
      const imageUrl = await geminiService.generateStepImage(step.text, dish.name);
      const newInstructions = [...dish.instructions];
      newInstructions[index] = { ...step, imageUrl };
      onUpdateDish({ ...dish, instructions: newInstructions });
    } catch (err) {
      alert("生成图片失败，请稍后重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage;
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatMessage('');
    setLoading(true);

    try {
      // 模拟简单的 AI 对话，实际可扩充 GeminiService 专门的对话接口
      const response = await geminiService.modifyRecipe(dish, `针对以下咨询给出建议，不要修改菜谱结构，只需在描述中回答：${userMsg}`);
      setChatHistory(prev => [...prev, { role: 'ai', content: response.description }]);
    } catch (err) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '抱歉，我现在有点忙，请稍后再问。' }]);
    } finally {
      setLoading(false);
    }
  };

  const instructions = Array.isArray(dish.instructions) ? dish.instructions : [];
  const totalTime = instructions.reduce((acc, step) => {
    if (typeof step === 'string') return acc + 5;
    return acc + (step.timeMinutes || 0);
  }, 0);

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in duration-500 pb-20 relative">
      <div className="flex justify-between items-center mb-6">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 text-gray-500 hover:text-orange-500 font-medium transition"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
          </svg>
          返回收藏夹
        </button>

        <div className="flex gap-2">
          <button 
            onClick={() => setIsModifying(!isModifying)}
            className={`px-4 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-sm text-sm ${isModifying ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600 border border-indigo-100 hover:bg-indigo-50'}`}
          >
            <span>✨</span> {isModifying ? '取消调整' : '调整菜谱'}
          </button>
        </div>
      </div>

      {isModifying && (
        <div className="mb-8 bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
          <h4 className="text-indigo-900 font-bold mb-3 flex items-center gap-2 text-sm">
            你想如何调整这道菜？
          </h4>
          <div className="flex flex-wrap gap-2 mb-4 text-xs">
            {["精简食材", "少油少盐", "让口味更辣", "换成素食", "适合儿童"].map((suggest) => (
              <button
                key={suggest}
                onClick={() => handleModify(suggest)}
                className="px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 font-bold rounded-full hover:bg-indigo-600 hover:text-white transition-colors"
              >
                {suggest}
              </button>
            ))}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="输入您的修改想法..."
              className="flex-1 px-4 py-3 rounded-xl border border-indigo-200 outline-none focus:ring-2 focus:ring-indigo-400 text-sm"
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              disabled={loading}
            />
            <button 
              onClick={() => handleModify()}
              disabled={loading || !instruction.trim()}
              className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition disabled:opacity-50 min-w-[80px] text-sm"
            >
              {loading ? '...' : '确认'}
            </button>
          </div>
        </div>
      )}

      {/* 菜谱主体 */}
      <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-100">
        <div className="aspect-video w-full bg-orange-100 relative flex items-center justify-center overflow-hidden">
           {dish.imageUrl ? (
             <img 
               src={dish.imageUrl} 
               alt={dish.name} 
               className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 hover:scale-110"
             />
           ) : (
             <span className="text-8xl filter drop-shadow-lg select-none">🍲</span>
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"></div>
           <div className="absolute bottom-6 left-8 text-white pr-8 right-8">
             <div className="flex flex-wrap gap-2 mb-2">
               <span className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-bold shadow-lg uppercase">
                 {dish.category}
               </span>
               <span className="px-3 py-1 bg-gray-800/80 rounded-full text-[10px] font-bold shadow-lg flex items-center gap-1">
                 🕒 约 {totalTime} 分钟
               </span>
             </div>

             {isEditingName ? (
               <input 
                 autoFocus
                 type="text"
                 className="bg-white/20 border-b-2 border-white text-4xl font-black outline-none w-full px-2 py-1 rounded transition-all focus:bg-white/30"
                 value={tempName}
                 onChange={(e) => setTempName(e.target.value)}
                 onBlur={handleSaveName}
                 onKeyDown={(e) => {
                   if (e.key === 'Enter') handleSaveName();
                   if (e.key === 'Escape') { setIsEditingName(false); setTempName(dish.name); }
                 }}
               />
             ) : (
               <h2 
                 className="text-4xl font-black drop-shadow-md cursor-pointer hover:underline decoration-white/30 underline-offset-8 flex items-center gap-3 group"
                 onClick={() => setIsEditingName(true)}
                 title="点击修改菜名"
               >
                 {dish.name}
                 <span className="text-xl opacity-0 group-hover:opacity-60 transition-opacity">✎</span>
               </h2>
             )}
           </div>
        </div>

        <div className="p-8">
          <div className="mb-10">
            <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-4">菜肴简介</h3>
            <p className="text-gray-600 leading-relaxed text-lg italic">
              “{dish.description || '暂无简介'}”
            </p>
          </div>

          <div className="mb-10">
            <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-4">所需食材</h3>
            <div className="grid grid-cols-2 gap-4">
              {dish.ingredients?.map((ing, i) => (
                <div key={i} className="flex justify-between items-center p-3 bg-gray-50 rounded-xl border border-gray-100">
                  <span className="font-medium text-gray-700 text-sm">{ing.name}</span>
                  <span className="text-orange-600 text-xs font-bold">{ing.amount}</span>
                </div>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-8">烹饪步骤</h3>
            <div className="space-y-12">
              {instructions.map((step, i) => (
                <div key={i} className="group">
                  <div className="flex gap-4 mb-4">
                    <div className="flex-shrink-0 w-8 h-8 rounded-full bg-orange-500 text-white flex items-center justify-center font-bold shadow-md shadow-orange-100">
                      {i + 1}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start gap-4">
                        <p className="text-gray-700 leading-relaxed text-lg flex-1">
                          {typeof step === 'string' ? step : step.text}
                        </p>
                        {typeof step === 'object' && step.timeMinutes > 0 && (
                          <span className="px-2 py-1 bg-orange-50 text-orange-600 text-[10px] font-bold rounded flex items-center gap-1 whitespace-nowrap">
                            ⏱️ {step.timeMinutes}min
                          </span>
                        )}
                      </div>

                      {!step.imageUrl && (
                        <button 
                          onClick={() => generateStepImage(i)}
                          disabled={loading}
                          className="mt-3 text-xs text-orange-400 hover:text-orange-600 flex items-center gap-1 font-bold disabled:opacity-50"
                        >
                          📸 点击生成步骤配图
                        </button>
                      )}
                    </div>
                  </div>
                  {step.imageUrl && (
                    <div className="ml-12 rounded-2xl overflow-hidden border border-gray-100 shadow-sm transition-all hover:shadow-md max-w-lg">
                      <img 
                        src={step.imageUrl} 
                        alt={`步骤 ${i+1}`} 
                        className="w-full h-auto object-cover"
                        loading="lazy"
                      />
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* 浮动加载提示 */}
      {loadingStatus && (
        <div className="fixed bottom-24 right-8 z-50 bg-white/90 backdrop-blur-md px-4 py-3 rounded-2xl border border-orange-100 shadow-xl flex items-center gap-3 animate-in slide-in-from-bottom duration-300">
           <div className="animate-spin h-4 w-4 border-2 border-orange-500 border-t-transparent rounded-full"></div>
           <span className="text-orange-600 text-sm font-bold">{loadingStatus}</span>
        </div>
      )}

      {/* AI 厨师助理聊天 */}
      <div className={`fixed bottom-8 right-8 z-50 flex flex-col items-end transition-all ${isChatOpen ? 'w-80 h-96' : 'w-16 h-16'}`}>
        {isChatOpen && (
          <div className="bg-white w-full flex-1 mb-4 rounded-3xl shadow-2xl border border-gray-100 flex flex-col overflow-hidden animate-in zoom-in duration-200">
             <div className="bg-orange-500 p-4 text-white font-bold flex justify-between items-center">
               <span className="flex items-center gap-2">👨‍🍳 厨师助理</span>
               <button onClick={() => setIsChatOpen(false)} className="hover:rotate-90 transition">✕</button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-hide">
                <div className="bg-gray-100 p-3 rounded-2xl rounded-tl-none text-xs text-gray-700">
                  你好！我是你的智能厨师助理。你可以问我关于“{dish.name}”的烹饪技巧，或者让我帮你修改菜谱。
                </div>
                {chatHistory.map((chat, i) => (
                  <div key={i} className={`flex ${chat.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-3 rounded-2xl text-xs ${chat.role === 'user' ? 'bg-orange-500 text-white rounded-tr-none' : 'bg-gray-100 text-gray-700 rounded-tl-none'}`}>
                      {chat.content}
                    </div>
                  </div>
                ))}
                <div ref={chatEndRef} />
             </div>
             <form onSubmit={handleChat} className="p-3 border-t border-gray-100 flex gap-2">
                <input 
                  type="text" 
                  value={chatMessage}
                  onChange={(e) => setChatMessage(e.target.value)}
                  placeholder="问问厨师..."
                  className="flex-1 bg-gray-50 px-3 py-2 rounded-xl outline-none text-xs focus:ring-1 focus:ring-orange-400"
                  disabled={loading}
                />
                <button type="submit" disabled={loading || !chatMessage.trim()} className="bg-orange-500 text-white p-2 rounded-xl disabled:opacity-50">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                </button>
             </form>
          </div>
        )}
        <button 
          onClick={() => setIsChatOpen(!isChatOpen)}
          className={`w-14 h-14 rounded-full shadow-lg flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 ${isChatOpen ? 'bg-gray-800 text-white' : 'bg-orange-500 text-white'}`}
        >
          {isChatOpen ? '✕' : '💬'}
        </button>
      </div>
    </div>
  );
};

export default RecipeView;

export enum Category {
  SICHUAN = '川菜',
  CANTONESE = '粤菜',
  SHANDONG = '鲁菜',
  HUAIYANG = '淮扬菜',
  INTERNATIONAL = '外国菜肴',
  NOODLES = '面食/主食',
  DESSERT = '甜点/点心',
  HOME_COOKING = '家常菜',
  OTHER = '其他'
}

export enum DishType {
  MEAT = '荤菜',
  VEGGIES = '素菜',
  SOUP = '汤羹',
  SEAFOOD = '海鲜',
  COLD = '凉菜',
  STAPLE = '主食',
  SNACK = '小吃'
}

export interface Ingredient {
  name: string;
  amount: string;
}

export interface InstructionStep {
  text: string;
  timeMinutes: number;
  imageUrl?: string;
}

export interface Dish {
  id: string;
  name: string;
  category: Category;
  dishType?: DishType;
  ingredients: Ingredient[];
  instructions: InstructionStep[];
  description: string;
  imageUrl?: string;
  createdAt: number;
}

export interface SuggestedDish {
  name: string;
  category: Category;
  dishType: DishType;
  reason: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish, InstructionStep } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `请作为专业厨师，提供菜肴 "${dishName}" 的详细菜谱信息。
      要求：
      1. 必须包含准备和烹饪的所有关键步骤。
      2. 每个步骤必须估算所需时间（单位：分钟，请提供整数）。
      3. 语言使用中文。
      4. 返回符合 schema 定义的 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的地域分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 外国菜肴, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            dishType: {
              type: Type.STRING,
              description: "菜肴的类型分类 (荤菜, 素菜, 汤羹, 海鲜, 凉菜, 主食, 小吃)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING, description: "步骤描述" },
                  timeMinutes: { type: Type.INTEGER, description: "预计时间（分钟）" },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的背景或风味简介",
            },
          },
          required: ["category", "dishType", "ingredients", "instructions", "description"],
        },
      },
    });

    try {
      const text = response.text;
      if (!text) throw new Error("Empty response");
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("生成菜谱失败，请重试。");
    }
  }

  /**
   * Modifies an existing recipe.
   */
  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        修改菜肴: "${dish.name}"
        修改指令: "${instruction}"
        当前信息: ${JSON.stringify({
          desc: dish.description,
          ings: dish.ingredients,
          steps: dish.instructions?.map(s => (typeof s === 'string' ? s : s.text))
        })}
        请根据指令重写，保持 JSON 格式。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  timeMinutes: { type: Type.INTEGER },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: { type: Type.STRING },
          },
          required: ["ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      throw new Error("调整菜谱失败");
    }
  }

  /**
   * Generates images with lower resolution/size hints in prompt to save storage.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `High quality food photography of ${dishName}, elegant plating, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Image failed");
  }

  async generateStepImage(stepDescription: string, dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Cooking step: ${stepDescription} for ${dishName}. Kitchen action shot, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Step image failed");
  }

  async suggestDishes(ingredients: string[]): Promise<SuggestedDish[]> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有：${ingredients.join(", ")}。推荐 3-5 道中国菜。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
            },
            required: ["name", "category", "dishType", "reason"],
          },
        },
      },
    });
    return JSON.parse(response.text);
  }

  async getDiscoveryRecommendations(): Promise<SuggestedDish[]> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: "请作为美食导游，推荐 6 道有趣或流行的菜肴。包括一些中国传统名菜和一些具有代表性的外国菜肴（如意面、寿司、牛排等）。请提供菜名、分类、类型以及推荐理由。",
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
            },
            required: ["name", "category", "dishType", "reason"],
          },
        },
      },
    });
    try {
      return JSON.parse(response.text);
    } catch (e) {
      return [];
    }
  }
}

