import React, { useState, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Dish, SuggestedDish, InstructionStep } from '../types';

interface DiscoveryViewProps {
  onAddDish: (dish: Dish) => void;
  onViewRecipe: (id: string) => void;
}

const DiscoveryView: React.FC<DiscoveryViewProps> = ({ onAddDish, onViewRecipe }) => {
  const [recommendations, setRecommendations] = useState<SuggestedDish[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingDish, setSavingDish] = useState<string | null>(null);

  const fetchDiscovery = async () => {
    setLoading(true);
    try {
      const res = await geminiService.getDiscoveryRecommendations();
      setRecommendations(res);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDiscovery();
  }, []);

  const handleSaveToCollection = async (suggested: SuggestedDish) => {
    setSavingDish(suggested.name);
    try {
      const details = await geminiService.getRecipeDetails(suggested.name);

      let imageUrl = '';
      try {
        imageUrl = await geminiService.generateDishImage(suggested.name);
      } catch (imgErr) {
        console.warn("Image generation failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: Date.now().toString(),
        name: suggested.name,
        ...details,
        instructions: finalSteps,
        imageUrl,
        createdAt: Date.now()
      };
      onAddDish(newDish);
      alert(`${suggested.name} 已成功加入您的收藏！`);
    } catch (err) {
      alert("保存失败，请稍后重试。");
    } finally {
      setSavingDish(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-end border-b border-orange-100 pb-4">
        <div>
          <h2 className="text-3xl font-black text-gray-800">发现灵感</h2>
          <p className="text-gray-500 mt-2 italic">看看今天 AI 为您推荐了哪些美味？</p>
        </div>
        <button 
          onClick={fetchDiscovery}
          disabled={loading}
          className="flex items-center gap-2 text-orange-600 hover:text-orange-700 font-bold transition-all disabled:opacity-50"
        >
          <svg className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
          换一批
        </button>
      </div>

      {loading && recommendations.length === 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1,2,3,4,5,6].map(i => (
            <div key={i} className="bg-gray-50 rounded-3xl h-64 animate-pulse border border-gray-100"></div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {recommendations.map((item, idx) => (
            <div key={idx} className="bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-xl transition-all p-6 flex flex-col justify-between group">
              <div>
                <div className="flex gap-2 mb-4">
                  <span className="px-2 py-0.5 bg-orange-100 text-orange-700 text-[10px] font-bold rounded uppercase">
                    {item.category}
                  </span>
                  <span className="px-2 py-0.5 bg-green-100 text-green-700 text-[10px] font-bold rounded uppercase">
                    {item.dishType}
                  </span>
                </div>
                <h3 className="text-2xl font-black text-gray-800 mb-3">{item.name}</h3>
                <p className="text-gray-500 text-sm leading-relaxed mb-6">
                  {item.reason}
                </p>
              </div>
              <button 
                onClick={() => handleSaveToCollection(item)}
                disabled={savingDish === item.name}
                className="w-full py-3 bg-orange-500 text-white font-bold rounded-2xl hover:bg-orange-600 transition shadow-lg shadow-orange-100 flex items-center justify-center gap-2 disabled:opacity-50"
              >
                {savingDish === item.name ? (
                  <>
                    <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    正在同步...
                  </>
                ) : (
                  <>✨ 立即收藏</>
                )}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

