import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, InstructionStep } from '../types';
import DishCard from '../components/DishCard';
import { geminiService } from '../services/geminiService';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  recentlyViewedDishes: Dish[];
  onAddDish: (dish: Dish) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
}

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  recentlyViewedDishes,
  onAddDish, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const matchesSearch = dish.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleAddDish = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDishName.trim()) return;

    setLoading(true);
    setLoadingStatus('正在构思美味菜谱...');
    try {
      const details = await geminiService.getRecipeDetails(newDishName);
      setLoadingStatus('正在通过 AI 绘制封面...');
      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(newDishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      setLoadingStatus('保存到您的私人数据库...');
      const newDish: Dish = {
        id: Date.now().toString(),
        name: newDishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      onAddDish(newDish);
      setNewDishName('');
      setIsAdding(false);
    } catch (err) {
      console.error(err);
      alert(err instanceof Error ? err.message : "添加失败，请检查网络或重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出失败");
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
        alert("导入成功！已同步您的菜谱库。");
      } catch (err) {
        alert(err instanceof Error ? err.message : "导入失败");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-6 bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               </div>
               <div className="space-y-2 max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div 
                     key={dish.id} 
                     onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }}
                     className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group"
                   >
                     <div className="w-12 h-12 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? (
                          <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>
                        )}
                     </div>
                     <div className="flex-1 min-w-0">
                       <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                       <p className="text-[10px] text-gray-400">{dish.category}</p>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button 
            onClick={() => setIsRecentOpen(!isRecentOpen)}
            className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}
          >
            {isRecentOpen ? (
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
            ) : (
               <span className="relative">
                 🕒
                 <span className="absolute -top-1 -right-1 w-5 h-5 bg-orange-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-bold">
                   {recentlyViewedDishes.length}
                 </span>
               </span>
            )}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2">
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200 shadow-sm">
             <button 
               onClick={handleExport}
               title="导出备份"
               className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"
             >
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
             </button>
             <button 
               onClick={() => fileInputRef.current?.click()}
               title="导入备份"
               className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"
             >
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg>
             </button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"
          >
            <span>➕</span> 添加新菜肴
          </button>
        </div>
      </div>

      <div className="space-y-4">
        <div className="relative">
          <input 
            type="text" 
            placeholder="在库中搜索..."
            className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 focus:border-transparent outline-none transition"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>

        <div className="space-y-2">
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <span className="text-xs font-bold text-gray-400 whitespace-nowrap uppercase tracking-wider pr-2">菜系:</span>
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1.5 rounded-full text-xs whitespace-nowrap transition ${selectedCategory === cat ? 'bg-orange-500 text-white font-bold' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                {cat}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <span className="text-xs font-bold text-gray-400 whitespace-nowrap uppercase tracking-wider pr-2">类型:</span>
            {dishTypes.map(type => (
              <button
                key={type}
                onClick={() => setSelectedDishType(type)}
                className={`px-3 py-1.5 rounded-full text-xs whitespace-nowrap transition ${selectedDishType === type ? 'bg-green-500 text-white font-bold' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                {type}
              </button>
            ))}
          </div>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleAddDish} className="space-y-4">
              <input 
                autoFocus
                type="text" 
                placeholder="例如：红烧肉、麻辣香锅..."
                className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400"
                value={newDishName}
                onChange={(e) => setNewDishName(e.target.value)}
                disabled={loading}
              />
              <p className="text-sm text-gray-500">
                AI 将为您精准制定配方。您的数据保存在本地数据库中，可随时导出备份。
              </p>
              <div className="flex gap-4 pt-4">
                <button 
                  type="button"
                  onClick={() => setIsAdding(false)}
                  className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition"
                  disabled={loading}
                >
                  取消
                </button>
                <button 
                  type="submit"
                  disabled={loading || !newDishName.trim()}
                  className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 transition shadow-lg shadow-orange-200 disabled:opacity-50 min-w-[140px]"
                >
                  {loading ? '生成中...' : '立即添加'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {filteredDishes.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDishes.map(dish => (
            <DishCard 
              key={dish.id} 
              dish={dish} 
              onView={onViewRecipe}
              onDelete={onDeleteDish}
            />
          ))}
        </div>
      ) : (
        <div className="text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
          <p className="text-gray-400 text-lg">
            {searchTerm || selectedCategory !== '全部' || selectedDishType !== '全部' ? '没有找到匹配的菜肴' : '您的菜谱库还是空的。'}
          </p>
        </div>
      )}
    </div>
  );
};

export default CollectionView;

import React, { useState, useRef, useEffect } from 'react';
import { Dish, InstructionStep, DishType, Category } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  // 菜名编辑状态
  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  // 分类与类型编辑状态
  const [isEditingType, setIsEditingType] = useState(false);
  const [isEditingCategory, setIsEditingCategory] = useState(false);

  // 聊天对话状态
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: 'user' | 'ai', content: string}[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory, isChatOpen]);

  // 当外部数据变化时同步 tempName
  useEffect(() => {
    setTempName(dish.name);
  }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) {
      onUpdateDish({ ...dish, name: trimmed });
    } else {
      setTempName(dish.name);
    }
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;

    setLoading(true);
    setLoadingStatus('正在重构菜谱细节...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);

      const updatedDish: Dish = {
        ...dish,
        ...updatedDetails,
        // 保留原有的步骤图片（如果步骤文本没变）
        instructions: updatedDetails.instructions.map((newStep, idx) => {
          const oldStep = dish.instructions[idx];
          return {
            ...newStep,
            imageUrl: oldStep && oldStep.text === newStep.text ? oldStep.imageUrl : undefined
          };
        })
      };
      onUpdateDish(updatedDish);
      setIsModifying(false);
      setInstruction('');
    } catch (err) {
      alert("调整失败，请重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const generateStepImage = async (index: number) => {
    const step = dish.instructions[index];
    setLoading(true);
    setLoadingStatus(`正在绘制步骤 ${index + 1} 的配图...`);
    try {
      const imageUrl = await geminiService.generateStepImage(step.text, dish.name);
      const newInstructions = [...dish.instructions];
      newInstructions[index] = { ...step, imageUrl };
      onUpdateDish({ ...dish, instructions: newInstructions });
    } catch (err) {
      alert("生成图片失败，请稍后重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage;
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setChatMessage('');
    setLoading(true);

    try {
      // 使用专门的问答接口获取回答
      const answer = await geminiService.askChef(dish, userMsg, chatHistory);
      setChatHistory(prev => [...prev, { role: 'ai', content: answer }]);
    } catch (err) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '抱歉，厨师后台有点忙，能请你再问一次吗？' }]);
    } finally {
      setLoading(false);
    }
  };

  const instructions = Array.isArray(dish.instructions) ? dish.instructions : [];
  const totalTime = instructions.reduce((acc, step) => {
    if (typeof step === 'string') return acc + 5;
    return acc + (step.timeMinutes || 0);
  }, 0);

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in duration-500 pb-20 relative">
      <div className="flex justify-between items-center mb-6">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 text-gray-500 hover:text-orange-500 font-medium transition"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
          </svg>
          返回收藏夹
        </button>

        <div className="flex gap-2">
          <button 
            onClick={() => setIsModifying(!isModifying)}
            className={`px-4 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-sm text-sm ${isModifying ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600 border border-indigo-100 hover:bg-indigo-50'}`}
          >
            <span>✨</span> {isModifying ? '取消调整' : '调整菜谱'}
          </button>
        </div>
      </div>

      {isModifying && (
        <div className="mb-8 bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
          <h4 className="text-indigo-900 font-bold mb-3 flex items-center gap-2 text-sm">
            你想如何调整这道菜？
          </h4>
          <div className="flex flex-wrap gap-2 mb-4 text-xs">
            {["精简食材", "少油少盐", "让口味更辣", "换成素食", "适合儿童"].map((suggest) => (
              <button
                key={suggest}
                onClick={() => handleModify(suggest)}
                className="px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 font-bold rounded-full hover:bg-indigo-600 hover:text-white transition-colors"
              >
                {suggest}
              </button>
            ))}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="输入您的修改想法..."
              className="flex-1 px-4 py-3 rounded-xl border border-indigo-200 outline-none focus:ring-2 focus:ring-indigo-400 text-sm"
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              disabled={loading}
            />
            <button 
              onClick={() => handleModify()}
              disabled={loading || !instruction.trim()}
              className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition disabled:opacity-50 min-w-[80px] text-sm"
            >
              {loading ? '...' : '确认'}
            </button>
          </div>
        </div>
      )}

      {/* 菜谱主体 */}
      <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-100">
        <div className="aspect-video w-full bg-orange-100 relative flex items-center justify-center overflow-hidden">
           {dish.imageUrl ? (
             <img 
               src={dish.imageUrl} 
               alt={dish.name} 
               className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 hover:scale-110"
             />
           ) : (
             <span className="text-8xl filter drop-shadow-lg select-none">🍲</span>
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"></div>
           <div className="absolute bottom-6 left-8 text-white pr-8 right-8">
             <div className="flex flex-wrap gap-2 mb-2">
               {/* 可编辑 Category */}
               {isEditingCategory ? (
                 <select 
                   autoFocus
                   className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-bold shadow-lg uppercase outline-none cursor-pointer"
                   value={dish.category}
                   onBlur={() => setIsEditingCategory(false)}
                   onChange={(e) => {
                     onUpdateDish({ ...dish, category: e.target.value as Category });
                     setIsEditingCategory(false);
                   }}
                 >
                   {Object.values(Category).map(cat => (
                     <option key={cat} value={cat}>{cat}</option>
                   ))}
                 </select>
               ) : (
                 <span 
                   onClick={() => setIsEditingCategory(true)}
                   className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-bold shadow-lg uppercase cursor-pointer hover:bg-orange-600 transition-colors"
                   title="点击修改菜系"
                 >
                   {dish.category}
                 </span>
               )}

               {/* 可编辑 DishType */}
               {isEditingType ? (
                 <select 
                   autoFocus
                   className="px-3 py-1 bg-emerald-600 rounded-full text-[10px] font-bold shadow-lg uppercase outline-none cursor-pointer"
                   value={dish.dishType || ''}
                   onBlur={() => setIsEditingType(false)}
                   onChange={(e) => {
                     onUpdateDish({ ...dish, dishType: e.target.value as DishType });
                     setIsEditingType(false);
                   }}
                 >
                   <option value="" disabled>选择类型</option>
                   {Object.values(DishType).map(type => (
                     <option key={type} value={type}>{type}</option>
                   ))}
                 </select>
               ) : (
                 <span 
                   onClick={() => setIsEditingType(true)}
                   className="px-3 py-1 bg-emerald-600 rounded-full text-[10px] font-bold shadow-lg uppercase flex items-center gap-1 cursor-pointer hover:bg-emerald-700 transition-colors"
                   title="点击修改菜品类型"
                 >
                   {dish.dishType || '未知类型'}
                   <span className="opacity-60">✎</span>
                 </span>
               )}

               <span className="px-3 py-1 bg-gray-800/80 rounded-full text-[10px] font-bold shadow-lg flex items-center gap-1">
                 🕒 约 {totalTime} 分钟
               </span>
             </div>

             {isEditingName ? (
               <input 
                 autoFocus
                 type="text"
                 className="bg-white/20 border-b-2 border-white text-4xl font-black outline-none w-full px-2 py-1 rounded transition-all focus:bg-white/30"
                 value={tempName}
                 onChange={(e) => setTempName(e.target.value)}
                 onBlur={handleSaveName}
                 onKeyDown={(e) => {
                   if (e.key === 'Enter') handleSaveName();
                   if (e.key === 'Escape') { setIsEditingName(false); setTempName(dish.name); }
                 }}
               />
             ) : (
               <h2 
                 className="text-4xl font-black drop-shadow-md cursor-pointer hover:underline decoration-white/30 underline-offset-8 flex items-center gap-3 group"
                 onClick={() => setIsEditingName(true)}
                 title="点击修改菜名"
               >
                 {dish.name}
                 <span className="text-xl opacity-0 group-hover:opacity-60 transition-opacity">✎</span>
               </h2>
             )}
           </div>
        </div>

        <div className="p-8">
          <div className="mb-10">
            <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-4">菜肴简介</h3>
            <p className="text-gray-600 leading-relaxed text-lg italic">
              “{dish.description || '暂无简介'}”
            </p>
          </div>

          <div className="mb-10">
            <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-4">所需食材</h3>
            <div className="grid grid-cols-2 gap-4">
              {dish.ingredients?.map((ing, i) => (
                <div key={i} className="flex justify-between items-center p-3 bg-gray-50 rounded-xl border border-gray-100">
                  <span className="font-medium text-gray-700 text-sm">{ing.name}</span>
                  <span className="text-orange-600 text-xs font-bold">{ing.amount}</span>
                </div>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-8">烹饪步骤</h3>
            <div className="space-y-12">
              {instructions.map((step, i) => (
                <div key={i} className="group">
                  <div className="flex gap-4 mb-4">
                    <div className="flex-shrink-0 w-8 h-8 rounded-full bg-orange-500 text-white flex items-center justify-center font-bold shadow-md shadow-orange-100">
                      {i + 1}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start gap-4">
                        <p className="text-gray-700 leading-relaxed text-lg flex-1">
                          {typeof step === 'string' ? step : step.text}
                        </p>
                        {typeof step === 'object' && step.timeMinutes > 0 && (
                          <span className="px-2 py-1 bg-orange-50 text-orange-600 text-[10px] font-bold rounded flex items-center gap-1 whitespace-nowrap">
                            ⏱️ {step.timeMinutes}min
                          </span>
                        )}
                      </div>

                      {!step.imageUrl && (
                        <button 
                          onClick={() => generateStepImage(i)}
                          disabled={loading}
                          className="mt-3 text-xs text-orange-400 hover:text-orange-600 flex items-center gap-1 font-bold disabled:opacity-50"
                        >
                          📸 点击生成步骤配图
                        </button>
                      )}
                    </div>
                  </div>
                  {step.imageUrl && (
                    <div className="ml-12 rounded-2xl overflow-hidden border border-gray-100 shadow-sm transition-all hover:shadow-md max-w-lg">
                      <img 
                        src={step.imageUrl} 
                        alt={`步骤 ${i+1}`} 
                        className="w-full h-auto object-cover"
                        loading="lazy"
                      />
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* 浮动加载提示 */}
      {loadingStatus && (
        <div className="fixed bottom-24 right-8 z-50 bg-white/90 backdrop-blur-md px-4 py-3 rounded-2xl border border-orange-100 shadow-xl flex items-center gap-3 animate-in slide-in-from-bottom duration-300">
           <div className="animate-spin h-4 w-4 border-2 border-orange-500 border-t-transparent rounded-full"></div>
           <span className="text-orange-600 text-sm font-bold">{loadingStatus}</span>
        </div>
      )}

      {/* AI 厨师助理对话框 */}
      <div className={`fixed bottom-8 right-8 z-50 flex flex-col items-end transition-all ${isChatOpen ? 'w-[90vw] md:w-80 h-[70vh] md:h-96' : 'w-16 h-16'}`}>
        {isChatOpen && (
