import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish, InstructionStep, UserPreferences } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * 获取口味偏好的 prompt 描述
   */
  private getPreferencesPrompt(prefs?: UserPreferences): string {
    if (!prefs || !prefs.flavors || prefs.flavors.length === 0) return "";
    return `用户口味偏好：${prefs.flavors.join('、')}。请在制定菜谱或推荐时优先考虑这些口味需求（例如，如果喜欢辣，则适当增加辣椒比例；如果喜欢清淡，则减少油脂和重口调料）。`;
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string, prefs?: UserPreferences): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `请作为专业厨师，提供菜肴 "${dishName}" 的详细菜谱信息。
      要求：
      1. 必须包含准备和烹饪的所有关键步骤。
      2. 每个步骤必须估算所需时间（单位：分钟，请提供整数）。
      3. 语言使用中文。
      4. ${prefsPrompt}
      5. 返回符合 schema 定义的 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的地域分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 全球, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            dishType: {
              type: Type.STRING,
              description: "菜肴的类型分类 (荤菜, 素菜, 汤羹, 海鲜, 凉菜, 主食, 小吃)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING, description: "步骤描述" },
                  timeMinutes: { type: Type.INTEGER, description: "预计时间（分钟）" },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的背景或风味简介",
            },
          },
          required: ["category", "dishType", "ingredients", "instructions", "description"],
        },
      },
    });

    try {
      const text = response.text;
      if (!text) throw new Error("Empty response");
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("生成菜谱失败，请重试。");
    }
  }

  /**
   * 与 AI 厨师互动问答
   */
  async askChef(dish: Dish, question: string, history: {role: 'user' | 'ai', content: string}[]): Promise<string> {
    const chatHistory = history.map(h => `${h.role === 'user' ? '用户' : '厨师'}: ${h.content}`).join('\n');
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `你是一个专业的私家厨师助理。当前正在查看的菜谱是："${dish.name}"。
      菜谱简介：${dish.description}
      食材：${dish.ingredients.map(i => i.name).join(', ')}

      历史对话：
      ${chatHistory}

      用户新问题：${question}

      请直接以厨师的口吻回答问题，给出专业的建议、替代方案或技巧。回答要简洁、亲切且有用。`,
    });
    return response.text || "抱歉，我刚刚走神了，能再说一遍吗？";
  }

  /**
   * Modifies an existing recipe.
   */
  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        修改菜肴: "${dish.name}"
        修改指令: "${instruction}"
        当前信息: ${JSON.stringify({
          desc: dish.description,
          ings: dish.ingredients,
          steps: dish.instructions?.map(s => (typeof s === 'string' ? s : s.text))
        })}
        请根据指令重写，保持 JSON 格式。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  timeMinutes: { type: Type.INTEGER },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: { type: Type.STRING },
          },
          required: ["ingredients", "instructions", "description"],
        },
      },
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      throw new Error("调整菜谱失败");
    }
  }

  /**
   * Generates images.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `High quality food photography of ${dishName}, elegant plating, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Image failed");
  }

  async generateStepImage(stepDescription: string, dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Cooking step: ${stepDescription} for ${dishName}. Kitchen action shot, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Step image failed");
  }

  async suggestDishes(ingredients: string[], prefs?: UserPreferences): Promise<SuggestedDish[]> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有这些食材：${ingredients.join(", ")}。
      请推荐 3-5 道菜。
      规则：
      1. 可以推荐完全符合食材的菜。
      2. 也可以推荐缺少 1-2 样常见食材的菜（如缺少某种肉类或特定配菜），但必须在 missingIngredients 中列出缺少的关键食材。
      3. ${prefsPrompt}
      4. 分类请从 [川菜, 粤菜, 鲁菜, 淮扬菜, 全球, 面食/主食, 甜点/点心, 家常菜, 其他] 中选择。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
              missingIngredients: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                description: "如果用户缺少的关键食材（1-2样），请列在这里。如果不缺，返回空数组。",
              },
            },
            required: ["name", "category", "dishType", "reason", "missingIngredients"],
          },
        },
      },
    });
    return JSON.parse(response.text);
  }

  async getDiscoveryRecommendations(prefs?: UserPreferences): Promise<SuggestedDish[]> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `请作为美食导游，推荐 6 道有趣或流行的菜肴。包括一些中国传统名菜和一些具有代表性的全球菜肴（如意面、寿司、牛排等）。${prefsPrompt} 请提供菜名、分类、类型以及推荐理由。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
            },
            required: ["name", "category", "dishType", "reason"],
          },
        },
      },
    });
    try {
      return JSON.parse(response.text);
    } catch (e) {
      return [];
    }
  }
}

