  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleAddDish = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDishName.trim()) return;

    setLoading(true);
    setLoadingStatus('正在构思美味菜谱...');
    try {
      const details = await geminiService.getRecipeDetails(newDishName, preferences);
      setLoadingStatus('正在通过 AI 绘制封面...');
      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(newDishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      setLoadingStatus('保存到您的私人数据库...');
      const newDish: Dish = {
        id: Date.now().toString(),
        name: newDishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      onAddDish(newDish);
      setNewDishName('');
      setIsAdding(false);
    } catch (err) {
      console.error(err);
      alert(err instanceof Error ? err.message : "添加失败，请检查网络或重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出失败");
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
        alert("导入成功！已同步您的菜谱库。");
      } catch (err) {
        alert(err instanceof Error ? err.message : "导入失败");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-6 bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               </div>
               <div className="space-y-2 max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div 
                     key={dish.id} 
                     onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }}
                     className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group"
                   >
                     <div className="w-12 h-12 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? (
                          <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>
                        )}
                     </div>
                     <div className="flex-1 min-w-0">
                       <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                       <p className="text-[10px] text-gray-400">{dish.category}</p>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button 
            onClick={() => setIsRecentOpen(!isRecentOpen)}
            className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}
          >
            {isRecentOpen ? (
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
            ) : (
               <span className="relative">
                 🕒
                 <span className="absolute -top-1 -right-1 w-5 h-5 bg-orange-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-bold">
                   {recentlyViewedDishes.length}
                 </span>
               </span>
            )}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsPrefsOpen(!isPrefsOpen)}
            className={`px-4 py-2 rounded-full font-bold transition flex items-center gap-2 border ${isPrefsOpen ? 'bg-indigo-500 text-white border-indigo-200 shadow-lg' : 'bg-white text-indigo-600 border-indigo-100 hover:bg-indigo-50'}`}
          >
            <span>⚙️</span> 偏好设置
          </button>
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200 shadow-sm">
             <button 
               onClick={handleExport}
               title="导出备份"
               className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"
             >
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
             </button>
             <button 
               onClick={() => fileInputRef.current?.click()}
               title="导入备份"
               className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"
             >
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg>
             </button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"
          >
            <span>➕</span> 添加新菜肴
          </button>
        </div>
      </div>

      {isPrefsOpen && (
        <div className="bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
           <h3 className="text-sm font-black text-indigo-900 mb-4 flex items-center gap-2">
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg>
             口味偏好（AI 将在生成新菜谱和推荐时优先考虑）
           </h3>
           <div className="flex flex-wrap gap-2">
             {FLAVORS.map(flavor => (
               <button
                 key={flavor}
                 onClick={() => toggleFlavor(flavor)}
                 className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${preferences.flavors.includes(flavor) ? 'bg-indigo-600 text-white border-indigo-400 shadow-md transform scale-105' : 'bg-white text-indigo-400 border-indigo-100 hover:border-indigo-300'}`}
               >
                 {flavor}
                 {preferences.flavors.includes(flavor) && <span className="ml-1.5">✓</span>}
               </button>
             ))}
           </div>
           {preferences.flavors.length > 0 && (
             <p className="text-[10px] text-indigo-400 mt-4 italic font-medium">
               当前选中: {preferences.flavors.join('、')}。灵感推荐将变得更加符合您的心意。
             </p>
           )}
        </div>
      )}

      <div className="space-y-4">
        <div className="flex flex-col gap-2">
          <div className="relative">
            <input 
              type="text" 
              placeholder={searchByIngredients ? "输入食材名进行搜索..." : "输入菜名进行搜索..."}
              className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 focus:border-transparent outline-none transition shadow-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>
          <div className="flex items-center gap-2 px-1">
            <label className="flex items-center gap-2 cursor-pointer group">
              <input 
                type="checkbox" 
                className="hidden peer"
                checked={searchByIngredients}
                onChange={() => setSearchByIngredients(!searchByIngredients)}
              />
              <div className="w-4 h-4 rounded border-2 border-gray-300 peer-checked:bg-orange-500 peer-checked:border-orange-500 transition-all flex items-center justify-center">
                <svg className="w-3 h-3 text-white opacity-0 peer-checked:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
                </svg>
              </div>
              <span className="text-xs font-bold text-gray-500 group-hover:text-orange-500 transition-colors">
                🥕 同时搜索食材
              </span>
            </label>
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <span className="text-xs font-bold text-gray-400 whitespace-nowrap uppercase tracking-wider pr-2">菜系:</span>
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1.5 rounded-full text-xs whitespace-nowrap transition ${selectedCategory === cat ? 'bg-orange-500 text-white font-bold' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                {cat}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <span className="text-xs font-bold text-gray-400 whitespace-nowrap uppercase tracking-wider pr-2">类型:</span>
            {dishTypes.map(type => (
              <button
                key={type}
                onClick={() => setSelectedDishType(type)}
                className={`px-3 py-1.5 rounded-full text-xs whitespace-nowrap transition ${selectedDishType === type ? 'bg-green-500 text-white font-bold' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
              >
                {type}
              </button>
            ))}
          </div>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleAddDish} className="space-y-4">
              <input 
                autoFocus
                type="text" 
                placeholder="例如：红烧肉、麻辣香锅..."
                className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400"
                value={newDishName}
                onChange={(e) => setNewDishName(e.target.value)}
                disabled={loading}
              />
              <p className="text-sm text-gray-500">
                AI 将根据您的偏好（如：{preferences.flavors.join('、') || '默认口味'}）为您精准制定配方。
              </p>
              <div className="flex gap-4 pt-4">
                <button 
                  type="button"
                  onClick={() => setIsAdding(false)}
                  className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition"
                  disabled={loading}
                >
                  取消
                </button>
                <button 
                  type="submit"
                  disabled={loading || !newDishName.trim()}
                  className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 transition shadow-lg shadow-orange-200 disabled:opacity-50 min-w-[140px]"
                >
                  {loading ? '生成中...' : '立即添加'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {filteredDishes.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDishes.map(dish => (
            <DishCard 
              key={dish.id} 
              dish={dish} 
              onView={onViewRecipe}
              onDelete={onDeleteDish}
            />
          ))}
        </div>
      ) : (
        <div className="text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
          <p className="text-gray-400 text-lg">
            {searchTerm || selectedCategory !== '全部' || selectedDishType !== '全部' ? '没有找到匹配的菜肴' : '您的菜谱库还是空的。'}
          </p>
          {searchTerm && searchByIngredients && (
            <p className="text-xs text-gray-400 mt-2">尝试更换关键词或关闭“按食材搜索”</p>
          )}
        </div>
      )}
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Dish, SuggestedDish, InstructionStep, UserPreferences } from '../types';

interface SuggestViewProps {
  onAddDish: (dish: Dish) => void;
  preferences: UserPreferences;
}

const STORAGE_KEY = 'delicious-secrets-last-ingredients';

const SuggestView: React.FC<SuggestViewProps> = ({ onAddDish, preferences }) => {
  const [inputValue, setInputValue] = useState('');
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<SuggestedDish[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingDish, setSavingDish] = useState<string | null>(null);

  // 挂载时加载上次保留的食材
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          setIngredients(parsed);
        }
      } catch (e) {
        console.error("无法加载历史食材", e);
      }
    }
  }, []);

  // 当食材变化时自动保存
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(ingredients));
  }, [ingredients]);

  const handleAddIngredient = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const removeIngredient = (name: string) => {
    setIngredients(ingredients.filter(i => i !== name));
  };

  const clearAllIngredients = () => {
    if (ingredients.length > 0 && window.confirm("确定要清空当前的食材列表吗？")) {
      setIngredients([]);
      setSuggestions([]);
    }
  };

  const fetchSuggestions = async () => {
    if (ingredients.length === 0) return;
    setLoading(true);
    try {
      const res = await geminiService.suggestDishes(ingredients, preferences);
      setSuggestions(res);
    } catch (err) {
      alert("推荐失败，请重试。");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveToCollection = async (suggested: SuggestedDish) => {
    setSavingDish(suggested.name);
    try {
      const details = await geminiService.getRecipeDetails(suggested.name, preferences);

      let imageUrl = '';
      try {
        imageUrl = await geminiService.generateDishImage(suggested.name);
      } catch (imgErr) {
        console.warn("Image generation failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: Date.now().toString(),
        name: suggested.name,
        ...details,
        instructions: finalSteps,
        imageUrl,
        createdAt: Date.now()
      };
      onAddDish(newDish);
      alert(`${suggested.name} 已成功加入您的收藏！`);
    } catch (err) {
      alert("保存失败，请稍后重试。");
    } finally {
      setSavingDish(null);
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-in slide-in-from-bottom duration-500">
      <div className="bg-gradient-to-br from-orange-400 to-red-500 rounded-3xl p-8 text-white mb-8 shadow-2xl">
        <h2 className="text-3xl font-bold mb-4">今天做什么？</h2>
        <p className="opacity-90 mb-6">输入您家里现有的食材，我来帮您出主意。
          {preferences.flavors.length > 0 && <span className="block mt-1 text-xs bg-black/10 p-2 rounded-lg">我已记录您的口味偏好：{preferences.flavors.join('、')}，将为您量身推荐。</span>}
        </p>

        <form onSubmit={handleAddIngredient} className="relative mb-6">
          <input 
            type="text"
            placeholder="输入食材名称（如：鸡蛋、西红柿、五花肉）"
            className="w-full px-6 py-4 rounded-2xl text-gray-800 outline-none pr-24 text-lg"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
          />
          <button 
            type="submit"
            className="absolute right-2 top-2 bottom-2 px-6 bg-orange-600 hover:bg-orange-700 rounded-xl font-bold transition"
          >
            添加
          </button>
        </form>

        <div className="flex flex-wrap gap-2 items-center">
          {ingredients.map(ing => (
            <span key={ing} className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-full flex items-center gap-2 border border-white/30 text-sm font-medium transition-all hover:bg-white/30">
              {ing}
              <button onClick={() => removeIngredient(ing)} className="hover:text-red-200 transition-colors">✕</button>
            </span>
          ))}
          {ingredients.length > 0 && (
            <button 
              onClick={clearAllIngredients}
              className="text-xs text-orange-100 hover:text-white underline underline-offset-4 ml-2 opacity-80 hover:opacity-100 transition-opacity"
            >
              清空全部
            </button>
          )}
          {ingredients.length === 0 && <span className="text-orange-100 italic">尚未添加食材...</span>}
        </div>
      </div>

      <div className="text-center mb-10">
        <button 
          onClick={fetchSuggestions}
          disabled={ingredients.length === 0 || loading}
          className="bg-orange-600 hover:bg-orange-700 text-white text-xl font-bold px-12 py-4 rounded-2xl shadow-xl shadow-orange-200 disabled:opacity-50 transition transform hover:scale-105 active:scale-95"
        >
          {loading ? '正在为您灵光一闪...' : '💡 给我一些建议'}
        </button>
      </div>

      {suggestions.length > 0 && (
        <div className="space-y-6">
          <h3 className="text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-6">推荐菜品</h3>
          {suggestions.map((s, idx) => (
            <div key={idx} className="bg-white border border-gray-100 rounded-3xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div className="flex-1">
                <div className="flex flex-wrap items-center gap-2 mb-2">
                  <h4 className="text-2xl font-bold text-gray-800">{s.name}</h4>
                  <span className="px-2 py-0.5 bg-gray-100 text-gray-500 text-[10px] rounded uppercase font-bold">{s.category}</span>
                  {s.missingIngredients && s.missingIngredients.length > 0 && (
                    <span className="px-2 py-0.5 bg-amber-50 text-amber-600 text-[10px] rounded border border-amber-100 font-bold">
                      缺少: {s.missingIngredients.join('、')}
                    </span>
                  )}
                </div>
                <p className="text-gray-600 italic">"{s.reason}"</p>
              </div>
              <button 
                onClick={() => handleSaveToCollection(s)}
                disabled={savingDish === s.name}
                className="whitespace-nowrap bg-orange-50 text-orange-600 font-bold px-6 py-3 rounded-2xl hover:bg-orange-500 hover:text-white transition disabled:opacity-50 flex items-center gap-2"
              >
                {savingDish === s.name ? (
                  <>
