};

export default CollectionView;

import React from 'react';
import { Dish } from '../types';

interface DishCardProps {
  dish: Dish;
  onView: (id: string) => void;
  onDelete: (id: string) => void;
}

const COMMON_INGREDIENTS = [
  '盐', '油', '醋', '糖', '酱油', '生抽', '老抽', '料酒', '葱', '姜', '蒜', '水', 
  '淀粉', '味精', '鸡精', '胡椒粉', '八角', '桂皮', '花椒', '芝麻油', '蚝油'
];

const DishCard: React.FC<DishCardProps> = ({ dish, onView, onDelete }) => {
  // 过滤出主要食材标签
  const mainIngredientTags = dish.ingredients
    ? dish.ingredients
        .filter(ing => !COMMON_INGREDIENTS.some(common => ing.name.includes(common)))
        .slice(0, 5)
    : [];

  const calculateTotalTime = () => {
    if (!Array.isArray(dish.instructions)) return 0;
    return dish.instructions.reduce((acc, step) => {
      if (typeof step === 'object' && step !== null && 'timeMinutes' in step) {
        return acc + (Number(step.timeMinutes) || 0);
      }
      if (typeof step === 'string') return acc + 3;
      return acc;
    }, 0);
  };

  const totalTime = calculateTotalTime();

  return (
    <div 
      onClick={() => onView(dish.id)}
      className="bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-500 p-5 flex flex-col justify-between group overflow-visible relative cursor-pointer"
    >
      {/* 侧边装饰条 */}
      <div className="absolute top-0 left-0 w-1 group-hover:w-2 h-full bg-orange-500 opacity-70 group-hover:opacity-100 transition-all duration-500 rounded-l-3xl"></div>

      <div className="pl-2">
        <div className="flex justify-between items-start mb-3">
          <div className="flex flex-wrap gap-1.5">
            <span className="px-2.5 py-1 bg-orange-50 text-orange-600 text-[10px] font-black rounded-lg uppercase tracking-wider border border-orange-100">
              {dish.category}
            </span>
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); onDelete(dish.id); }}
            className="text-gray-300 hover:text-red-500 transition-colors p-1"
            title="删除菜谱"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
          </button>
        </div>

        <h3 className="text-xl font-black text-gray-800 truncate pr-2 group-hover:text-orange-600 transition-colors mb-2">
          {dish.name}
        </h3>

        <p className="text-gray-500 text-sm line-clamp-2 leading-relaxed h-10 overflow-hidden mb-4">
          {dish.description}
        </p>

        {/* 悬停弹出的简要信息窗口 */}
        <div className="absolute left-1/2 -translate-x-1/2 -top-24 w-64 bg-gray-900/95 backdrop-blur-md text-white p-4 rounded-2xl shadow-2xl opacity-0 translate-y-4 pointer-events-none group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300 z-50">
          <div className="flex justify-between items-center mb-3 border-b border-white/10 pb-2">
            <span className="text-[10px] font-black uppercase tracking-tighter text-orange-400">简要预览</span>
            <span className="text-[10px] font-bold flex items-center gap-1">
              ⏱ {totalTime} 分钟
            </span>
          </div>
          <div className="space-y-2">
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">关键食材</p>
            <div className="flex flex-wrap gap-1">
              {mainIngredientTags.map((ing, idx) => (
                <span key={idx} className="text-[10px] bg-white/10 px-2 py-0.5 rounded border border-white/5">
                  {ing.name}
                </span>
              ))}
              {mainIngredientTags.length === 0 && <span className="text-[10px] italic opacity-50">经典家常</span>}
            </div>
          </div>
          {/* 箭头 */}
          <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-4 h-4 bg-gray-900 rotate-45"></div>
        </div>
      </div>

      <div className="mt-auto pt-2 flex items-center justify-between text-[10px] font-bold text-gray-400">
        <span>制作步骤: {dish.instructions?.length || 0} 步</span>
        <span className="text-orange-500 opacity-0 group-hover:opacity-100 transition-opacity">点击进入制作秘籍 →</span>
      </div>
    </div>
  );
};

