import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish, InstructionStep, UserPreferences } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    // Initialize with the API key from environment variables.
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  /**
   * 获取口味偏好的 prompt 描述
   */
  private getPreferencesPrompt(prefs?: UserPreferences): string {
    if (!prefs || !prefs.flavors || prefs.flavors.length === 0) return "";
    return `用户口味偏好：${prefs.flavors.join('、')}。请在制定菜谱或推荐时优先考虑这些口味需求（例如，如果喜欢辣，则适当增加辣椒比例；如果喜欢清淡，则减少油脂和重口调料）。`;
  }

  /**
   * 全局专业厨师对话 (使用 Pro 模型)
   */
  async proChat(message: string, history: {role: 'user' | 'ai', content: string}[], currentDish?: Dish, prefs?: UserPreferences): Promise<string> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const contextPrompt = currentDish ? 
      `用户当前正在查看菜谱："${currentDish.name}"。该菜谱简介：${currentDish.description}。食材包含：${currentDish.ingredients.map(i => i.name).join(', ')}。` : 
      "用户当前在主页浏览，没有查看特定菜谱。";

    const response = await this.ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: [
        ...history.map(h => ({ 
          role: h.role === 'user' ? 'user' : 'model', 
          parts: [{ text: h.content }] 
        })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `你是一个全能的美食专家和资深大厨助手。你可以回答关于烹饪技巧、食材替换、营养建议、饮食文化等任何问题。
        你的语气专业、幽默且极具启发性。
        ${prefsPrompt}
        ${contextPrompt}
        如果用户询问与当前查看菜谱相关的问题，请结合其上下文回答。如果用户问一般性问题，请展示你广博的烹饪知识。请直接回答，不要带有过多的废话。`,
      }
    });
    // Correctly using .text property from response
    return response.text || "抱歉，我刚刚在实验室研发新口味，没听清，能请您再说一遍吗？";
  }

  /**
   * Generates a full recipe for a given dish name.
   */
  async getRecipeDetails(dishName: string, prefs?: UserPreferences): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
    tips: string[];
  }> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `请作为专业厨师，提供菜肴 "${dishName}" 的详细菜谱信息。
      要求：
      1. 必须包含准备和烹饪的所有关键步骤。
      2. 每个步骤必须估算所需时间（单位：分钟，请提供整数）。
      3. 提供 3-5 条关于这道菜的专业烹饪贴士（tips），涵盖火候控制、食材预处理或风味提升。
      4. 语言使用中文。
      5. ${prefsPrompt}
      6. 返回符合 schema 定义的 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: {
              type: Type.STRING,
              description: "菜肴的地域分类 (川菜, 粤菜, 鲁菜, 淮扬菜, 全球, 面食/主食, 甜点/点心, 家常菜, 其他)",
            },
            dishType: {
              type: Type.STRING,
              description: "菜肴的类型分类 (荤菜, 素菜, 汤羹, 海鲜, 凉菜, 主食, 小吃)",
            },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING, description: "步骤描述" },
                  timeMinutes: { type: Type.INTEGER, description: "预计时间（分钟）" },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: {
              type: Type.STRING,
              description: "对这道菜的背景或风味简介",
            },
            tips: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "烹饪小贴士 or 专家建议",
            },
          },
          required: ["category", "dishType", "ingredients", "instructions", "description", "tips"],
        },
      },
    });

    try {
      const text = response.text;
      if (!text) throw new Error("Empty response");
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse recipe details", e);
      throw new Error("生成菜谱失败，请重试。");
    }
  }

  /**
   * Modifies an existing recipe.
   */
  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
    tips: string[];
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `
        修改菜肴: "${dish.name}"
        修改指令: "${instruction}"
        当前信息: ${JSON.stringify({
          desc: dish.description,
          ings: dish.ingredients,
          steps: dish.instructions?.map(s => (typeof s === 'string' ? s : s.text)),
          tips: dish.tips
        })}
        请根据指令重写，保持 JSON 格式，包括更新烹饪贴士（tips）。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  amount: { type: Type.STRING },
                },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  timeMinutes: { type: Type.INTEGER },
                },
                required: ["text", "timeMinutes"],
              },
            },
            description: { type: Type.STRING },
            tips: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
            },
          },
          required: ["ingredients", "instructions", "description", "tips"],
        },
      },
    });

    try {
      return JSON.parse(response.text || "{}");
    } catch (e) {
      throw new Error("调整菜谱失败");
    }
  }

  /**
   * Generates a cover image for a dish.
   */
  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `High quality food photography of ${dishName}, elegant plating, professional lighting, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Image failed");
  }

  /**
   * Generates an image for a specific cooking step.
   */
  async generateStepImage(stepDescription: string, dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Cooking step: ${stepDescription} for ${dishName}. Kitchen action shot, clear instructions visual, 16:9.` }],
      },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    // Added throw to fix the error: A function whose declared type is neither 'undefined', 'void', nor 'any' must return a value.
    throw new Error("Failed to generate step image");
  }

  /**
   * Suggests dishes based on available ingredients.
   */
  async suggestDishes(ingredients: string[], prefs?: UserPreferences): Promise<SuggestedDish[]> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有以下食材：${ingredients.join('、')}。
      请推荐 3-5 道适合做的菜。
      要求：
      1. 尽量利用已有食材。
      2. 标注缺少的关键食材。
      3. ${prefsPrompt}
      4. 返回 JSON 格式。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING, description: "推荐理由" },
              missingIngredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            },
            required: ["name", "category", "dishType", "reason"],
          }
        }
      }
    });
    try {
      return JSON.parse(response.text || "[]");
    } catch (e) {
      return [];
    }
  }

  /**
   * Gets discovery recommendations.
   */
  async getDiscoveryRecommendations(prefs?: UserPreferences): Promise<SuggestedDish[]> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `请随机推荐 6 道目前流行或经典的中华美食或全球美食。
      ${prefsPrompt}
      要求：
      1. 种类多样。
      2. 返回 JSON 格式。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING, description: "推荐理由" },
            },
            required: ["name", "category", "dishType", "reason"],
          }
        }
      }
    });
    try {
      return JSON.parse(response.text || "[]");
    } catch (e) {
      return [];
    }
  }
}

