  preferences: UserPreferences;
}

const STORAGE_KEY = 'delicious-secrets-last-ingredients';
const STAPLES_KEY = 'delicious-secrets-staples';

const DEFAULT_STAPLES = [
  '盐', '糖', '胡椒粉', '生抽', '老抽', '醋', '料酒', '蚝油', 
  '油', '淀粉', '葱', '姜', '蒜', '花椒', '八角', '辣椒粉'
];

