  const [suggestions, setSuggestions] = useState<SuggestedDish[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingDish, setSavingDish] = useState<string | null>(null);

  useEffect(() => {
    // Load ingredients
    const savedIngs = localStorage.getItem(STORAGE_KEY);
    if (savedIngs) {
      try {
        const parsed = JSON.parse(savedIngs);
        if (Array.isArray(parsed)) setIngredients(parsed);
      } catch (e) {}
    }
    // Load staples
    const savedStaples = localStorage.getItem(STAPLES_KEY);
    if (savedStaples) {
      try {
        const parsed = JSON.parse(savedStaples);
        if (Array.isArray(parsed)) setStaples(parsed);
      } catch (e) {}
    } else {
      // Default all staples to "on" for a better first experience
      setStaples(DEFAULT_STAPLES);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(ingredients));
  }, [ingredients]);

  useEffect(() => {
    localStorage.setItem(STAPLES_KEY, JSON.stringify(staples));
  }, [staples]);

  const toggleStaple = (item: string) => {
    setStaples(prev => 
      prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]
    );
  };

  const handleAddIngredient = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const fetchSuggestions = async () => {
    if (ingredients.length === 0) return;
    setLoading(true);
    try {
      const res = await geminiService.suggestDishes(ingredients, staples, preferences);
      setSuggestions(res);
    } catch (err) {
      alert("推荐失败，请重试。");
    } finally {
      setLoading(false);
    }
  };

