        id: Date.now().toString(),
        name: suggested.name,
        ...details,
        instructions: details.instructions.map(s => ({ ...s, imageUrl: undefined })),
        imageUrl,
        createdAt: Date.now()
      };
      onAddDish(newDish);
    } catch (err) {
      alert("保存失败");
    } finally {
      setSavingDish(null);
    }
  };

