          <svg className="w-40 h-40" fill="currentColor" viewBox="0 0 24 24"><path d="M11 9H9V2H7V9H5V2H3V9C3 11.12 4.66 12.84 6.75 12.97V22H9.25V12.97C11.34 12.84 13 11.12 13 9V2H11V9ZM16 6V14H18.5V22H21V2C18.24 2 16 4.24 16 6Z"/></svg>
        </div>

        <h2 className="text-3xl font-black mb-4">今天做什么？</h2>
        <p className="opacity-90 mb-8 text-sm md:text-base">告诉我你手头的关键食材，AI 将为您量身定制大餐。</p>

        <form onSubmit={handleAddIngredient} className="relative mb-8">
          <input 
            type="text"
            placeholder="输入主要食材（如：鸡蛋、牛肉）"
            className="w-full px-6 py-5 rounded-2xl text-gray-800 outline-none pr-24 text-lg shadow-inner"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
          />
          <button 
            type="submit"
            className="absolute right-2 top-2 bottom-2 px-6 bg-orange-600 hover:bg-orange-700 rounded-xl font-bold transition-all shadow-md active:scale-95"
          >
