        <div className="flex flex-wrap gap-2 items-center min-h-[40px]">
          {ingredients.map(ing => (
            <span key={ing} className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-full flex items-center gap-2 border border-white/30 text-xs font-bold transition-all hover:bg-white/40 group">
