                placeholder="添加自定义常备食材..."
                className="flex-1 bg-gray-50 border border-gray-100 px-4 py-2 rounded-xl text-[11px] outline-none focus:ring-1 focus:ring-indigo-300"
                value={newStapleInput}
                onChange={(e) => setNewStapleInput(e.target.value)}
              />
              <button 
                type="submit"
                disabled={!newStapleInput.trim()}
                className="bg-indigo-500 text-white px-4 py-2 rounded-xl text-[11px] font-bold disabled:opacity-50 hover:bg-indigo-600 transition"
              >
                添加
              </button>
            </form>

            <div className="mt-6 flex gap-4 border-t border-gray-50 pt-4">
               <button onClick={() => setStaples([...DEFAULT_STAPLES, ...customStaples])} className="text-[10px] text-indigo-500 font-bold hover:underline">全选常备</button>
               <button onClick={() => setStaples([])} className="text-[10px] text-gray-400 font-bold hover:underline">全不选</button>
            </div>
          </div>
        )}
      </div>

      <div className="text-center mb-12">
        <button 
          onClick={fetchSuggestions}
          disabled={ingredients.length === 0 || loading}
          className="bg-orange-600 hover:bg-orange-700 text-white text-xl font-black px-12 py-5 rounded-2xl shadow-xl shadow-orange-200 disabled:opacity-50 transition transform hover:scale-105 active:scale-95 group"
        >
          {loading ? (
             <span className="flex items-center gap-3">
               <svg className="animate-spin h-5 w-5 text-white" viewBox="0 0 24 24">
                 <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                 <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
               </svg>
               构思中...
             </span>
          ) : '💡 看看能做什么？'}
        </button>
      </div>

      {suggestions.length > 0 && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="flex items-center gap-3 mb-6">
            <h3 className="text-xl font-black text-gray-800">推荐方案</h3>
            <div className="h-px flex-1 bg-gray-100"></div>
          </div>

          {suggestions.map((s, idx) => (
            <div key={idx} className="bg-white border border-gray-100 rounded-[2rem] p-8 shadow-sm hover:shadow-xl transition-all flex flex-col md:flex-row justify-between items-start md:items-center gap-6 group">
              <div className="flex-1">
                <div className="flex flex-wrap items-center gap-2 mb-3">
                  <h4 className="text-2xl font-black text-gray-800 group-hover:text-orange-600 transition-colors">{s.name}</h4>
                  <span className="px-3 py-1 bg-orange-50 text-orange-600 text-[10px] rounded-lg font-black uppercase tracking-tighter">{s.category}</span>
                </div>
                <p className="text-gray-500 italic text-sm mb-4">"{s.reason}"</p>
                {s.missingIngredients && s.missingIngredients.length > 0 && (
                  <div className="flex flex-wrap gap-2 items-center">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">需购买:</span>
                    {s.missingIngredients.map(mi => (
                      <span key={mi} className="px-2 py-0.5 bg-red-50 text-red-500 text-[10px] font-bold rounded-md border border-red-100">
                        {mi}
                      </span>
                    ))}
                  </div>
                )}
              </div>
              <button 
                onClick={() => handleSaveToCollection(s)}
                disabled={savingDish === s.name}
                className="whitespace-nowrap bg-gray-50 text-orange-600 font-black px-8 py-4 rounded-2xl hover:bg-orange-500 hover:text-white transition-all disabled:opacity-50 flex items-center gap-2 shadow-sm"
              >
                {savingDish === s.name ? '正在收藏...' : '⭐ 立即收藏'}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SuggestView;

export enum Category {
  SICHUAN = '川菜',
  CANTONESE = '粤菜',
  SHANDONG = '鲁菜',
  HUAIYANG = '淮扬菜',
  INTERNATIONAL = '全球',
  NOODLES = '面食/主食',
  DESSERT = '甜点/点心',
  HOME_COOKING = '家常菜',
  OTHER = '其他'
}

export enum DishType {
  MEAT = '荤菜',
  VEGGIES = '素菜',
  SOUP = '汤羹',
  SEAFOOD = '海鲜',
  COLD = '凉菜',
  STAPLE = '主食',
  SNACK = '小吃'
}

export interface Ingredient {
  name: string;
  amount: string;
}

export interface InstructionStep {
  text: string;
  timeMinutes: number;
  imageUrl?: string;
}

export interface Nutrition {
  calories: number;
  protein: number;
  fat: number;
  carbs: number;
}

export interface Dish {
  id: string;
  name: string;
  category: Category;
  dishType?: DishType;
  ingredients: Ingredient[];
  instructions: InstructionStep[];
  description: string;
  tips?: string[];
  nutrition?: Nutrition; // 新增：营养信息
  imageUrl?: string;
  createdAt: number;
}

export interface SuggestedDish {
  name: string;
  category: Category;
  dishType: DishType;
  reason: string;
  missingIngredients?: string[];
}

export interface UserPreferences {
  flavors: string[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { Category, DishType, Ingredient, SuggestedDish, Dish, InstructionStep, UserPreferences, Nutrition } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  private getPreferencesPrompt(prefs?: UserPreferences): string {
    if (!prefs || !prefs.flavors || prefs.flavors.length === 0) return "";
    return `用户口味偏好：${prefs.flavors.join('、')}。请在制定菜谱或推荐时优先考虑这些口味需求。`;
  }

  async proChat(message: string, history: {role: 'user' | 'ai', content: string}[], currentDish?: Dish, prefs?: UserPreferences): Promise<string> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const contextPrompt = currentDish ? 
      `用户当前正在查看菜谱："${currentDish.name}"。该菜谱简介：${currentDish.description}。食材包含：${currentDish.ingredients.map(i => i.name).join(', ')}。` : 
      "用户当前在主页浏览。";

    const response = await this.ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: [
        ...history.map(h => ({ 
          role: h.role === 'user' ? 'user' : 'model', 
          parts: [{ text: h.content }] 
        })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `你是一个美食专家。${prefsPrompt} ${contextPrompt} 直接回答问题。`,
      }
    });
    return response.text || "抱歉，请再说一遍。";
  }

  async getRecipeDetails(dishName: string, prefs?: UserPreferences): Promise<{
    category: Category;
    dishType: DishType;
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
    tips: string[];
    nutrition: Nutrition;
  }> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `提供 "${dishName}" 的详细菜谱。同时基于食材和常规分量，估算该菜肴的总营养价值（卡路里、蛋白质、脂肪、碳水）。${prefsPrompt} 返回 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: { type: Type.STRING },
            dishType: { type: Type.STRING },
            ingredients: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: { name: { type: Type.STRING }, amount: { type: Type.STRING } },
                required: ["name", "amount"],
              },
            },
            instructions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: { text: { type: Type.STRING }, timeMinutes: { type: Type.INTEGER } },
                required: ["text", "timeMinutes"],
              },
            },
            description: { type: Type.STRING },
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            nutrition: {
              type: Type.OBJECT,
              properties: {
                calories: { type: Type.INTEGER, description: "单位：kcal" },
                protein: { type: Type.INTEGER, description: "单位：g" },
                fat: { type: Type.INTEGER, description: "单位：g" },
                carbs: { type: Type.INTEGER, description: "单位：g" },
              },
              required: ["calories", "protein", "fat", "carbs"]
            }
          },
          required: ["category", "dishType", "ingredients", "instructions", "description", "tips", "nutrition"],
        },
      },
    });
    return JSON.parse(response.text || "{}");
  }

  async modifyRecipe(dish: Dish, instruction: string): Promise<{
    ingredients: Ingredient[];
    instructions: { text: string; timeMinutes: number }[];
    description: string;
    tips: string[];
    nutrition: Nutrition;
  }> {
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `修改菜谱: "${dish.name}"，要求: "${instruction}"。请重新估算修改后的营养价值。返回 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { name: { type: Type.STRING }, amount: { type: Type.STRING } }, required: ["name", "amount"] } },
            instructions: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { text: { type: Type.STRING }, timeMinutes: { type: Type.INTEGER } }, required: ["text", "timeMinutes"] } },
            description: { type: Type.STRING },
            tips: { type: Type.ARRAY, items: { type: Type.STRING } },
            nutrition: {
              type: Type.OBJECT,
              properties: {
                calories: { type: Type.INTEGER },
                protein: { type: Type.INTEGER },
                fat: { type: Type.INTEGER },
                carbs: { type: Type.INTEGER },
              },
              required: ["calories", "protein", "fat", "carbs"]
            }
          },
          required: ["ingredients", "instructions", "description", "tips", "nutrition"],
        },
      },
    });
    return JSON.parse(response.text || "{}");
  }

  async generateDishImage(dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `High quality food photography of ${dishName}, 16:9.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Image failed");
  }

  async generateStepImage(stepDescription: string, dishName: string): Promise<string> {
    const response = await this.ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Cooking step: ${stepDescription} for ${dishName}, 16:9.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } },
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    throw new Error("Step image failed");
  }

  async suggestDishes(ingredients: string[], staples: string[], prefs?: UserPreferences): Promise<SuggestedDish[]> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const staplesPrompt = staples.length > 0 
      ? `用户家里已有这些常备调料/基础食材：${staples.join('、')}。
         注意：在返回的 missingIngredients 中，请绝对不要包含这些常备调料，默认用户已经拥有它们。` 
      : "";

    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `我有以下主要食材：${ingredients.join('、')}。
      ${staplesPrompt}
      请推荐 3-5 道适合做的菜。
      要求：
      1. 尽量利用已有食材。
      2. missingIngredients 仅包含用户目前完全没有且必须去购买的关键食材。
      3. ${prefsPrompt}
      4. 返回 JSON 格式。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
              missingIngredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            },
            required: ["name", "category", "dishType", "reason"],
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }

  async getDiscoveryRecommendations(prefs?: UserPreferences): Promise<SuggestedDish[]> {
    const prefsPrompt = this.getPreferencesPrompt(prefs);
    const response = await this.ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `推荐 6 道流行美食。${prefsPrompt} 返回 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              category: { type: Type.STRING },
              dishType: { type: Type.STRING },
              reason: { type: Type.STRING },
            },
            required: ["name", "category", "dishType", "reason"],
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  }
}

export const geminiService = new GeminiService();

import React, { useState, useRef, useEffect } from 'react';
import { Dish, InstructionStep, DishType, Category, Nutrition } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  const [isEditingType, setIsEditingType] = useState(false);
  const [isEditingCategory, setIsEditingCategory] = useState(false);

  useEffect(() => {
    setTempName(dish.name);
  }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) {
      onUpdateDish({ ...dish, name: trimmed });
    } else {
      setTempName(dish.name);
    }
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;

    setLoading(true);
    setLoadingStatus('正在重构菜谱细节与营养分析...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);

      const updatedDish: Dish = {
        ...dish,
        ...updatedDetails,
        instructions: updatedDetails.instructions.map((newStep, idx) => {
          const oldStep = dish.instructions[idx];
          return {
            ...newStep,
            imageUrl: oldStep && oldStep.text === newStep.text ? oldStep.imageUrl : undefined
          };
        })
      };
      onUpdateDish(updatedDish);
      setIsModifying(false);
      setInstruction('');
    } catch (err) {
      alert("调整失败，请重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const generateStepImage = async (index: number) => {
    const step = dish.instructions[index];
    setLoading(true);
    setLoadingStatus(`正在绘制步骤 ${index + 1} 的配图...`);
    try {
      const imageUrl = await geminiService.generateStepImage(step.text, dish.name);
      const newInstructions = [...dish.instructions];
      newInstructions[index] = { ...step, imageUrl };
      onUpdateDish({ ...dish, instructions: newInstructions });
    } catch (err) {
      alert("生成图片失败，请稍后重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const instructions = Array.isArray(dish.instructions) ? dish.instructions : [];
  const totalTime = instructions.reduce((acc, step) => {
    if (typeof step === 'string') return acc + 5;
    return acc + (step.timeMinutes || 0);
  }, 0);

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in duration-500 pb-20 relative">
      <div className="flex justify-between items-center mb-6">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 text-gray-500 hover:text-orange-500 font-medium transition"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
          </svg>
          返回收藏夹
        </button>

        <div className="flex gap-2">
          <button 
            onClick={() => setIsModifying(!isModifying)}
            className={`px-4 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-sm text-sm ${isModifying ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600 border border-indigo-100 hover:bg-indigo-50'}`}
          >
            <span>✨</span> {isModifying ? '取消调整' : '调整菜谱'}
          </button>
        </div>
      </div>

      {isModifying && (
        <div className="mb-8 bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
          <h4 className="text-indigo-900 font-bold mb-3 flex items-center gap-2 text-sm">
            你想如何调整这道菜？
          </h4>
          <div className="flex flex-wrap gap-2 mb-4 text-xs">
            {["精简食材", "低卡健康", "少油少盐", "让口味更辣", "增加蛋白质"].map((suggest) => (
              <button
                key={suggest}
                onClick={() => handleModify(suggest)}
                className="px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 font-bold rounded-full hover:bg-indigo-600 hover:text-white transition-colors"
              >
                {suggest}
              </button>
            ))}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="输入您的修改想法..."
              className="flex-1 px-4 py-3 rounded-xl border border-indigo-200 outline-none focus:ring-2 focus:ring-indigo-400 text-sm"
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              disabled={loading}
            />
            <button 
              onClick={() => handleModify()}
              disabled={loading || !instruction.trim()}
              className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition disabled:opacity-50 min-w-[80px] text-sm"
            >
              {loading ? '...' : '确认'}
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-100">
        <div className="aspect-video w-full bg-orange-100 relative flex items-center justify-center overflow-hidden">
           {dish.imageUrl ? (
             <img 
               src={dish.imageUrl} 
               alt={dish.name} 
               className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 hover:scale-110"
             />
           ) : (
             <span className="text-8xl filter drop-shadow-lg select-none">🍲</span>
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"></div>
           <div className="absolute bottom-6 left-8 text-white pr-8 right-8">
             <div className="flex flex-wrap gap-2 mb-2">
               {isEditingCategory ? (
                 <select 
                   autoFocus
                   className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-bold shadow-lg uppercase outline-none cursor-pointer"
                   value={dish.category}
                   onBlur={() => setIsEditingCategory(false)}
                   onChange={(e) => {
                     onUpdateDish({ ...dish, category: e.target.value as Category });
                     setIsEditingCategory(false);
                   }}
                 >
                   {Object.values(Category).map(cat => (
                     <option key={cat} value={cat}>{cat}</option>
                   ))}
                 </select>
               ) : (
                 <span 
                   onClick={() => setIsEditingCategory(true)}
                   className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-bold shadow-lg uppercase cursor-pointer hover:bg-orange-600 transition-colors"
                 >
                   {dish.category}
                 </span>
               )}

               {isEditingType ? (
                 <select 
                   autoFocus
                   className="px-3 py-1 bg-emerald-600 rounded-full text-[10px] font-bold shadow-lg uppercase outline-none cursor-pointer"
                   value={dish.dishType || ''}
                   onBlur={() => setIsEditingType(false)}
                   onChange={(e) => {
                     onUpdateDish({ ...dish, dishType: e.target.value as DishType });
                     setIsEditingType(false);
                   }}
                 >
                   <option value="" disabled>选择类型</option>
                   {Object.values(DishType).map(type => (
                     <option key={type} value={type}>{type}</option>
                   ))}
                 </select>
               ) : (
                 <span 
                   onClick={() => setIsEditingType(true)}
                   className="px-3 py-1 bg-emerald-600 rounded-full text-[10px] font-bold shadow-lg uppercase flex items-center gap-1 cursor-pointer hover:bg-emerald-700 transition-colors"
                 >
                   {dish.dishType || '未知类型'}
                   <span className="opacity-60">✎</span>
                 </span>
               )}

               <span className="px-3 py-1 bg-gray-800/80 rounded-full text-[10px] font-bold shadow-lg flex items-center gap-1">
                 🕒 约 {totalTime} 分钟
               </span>
             </div>

             {isEditingName ? (
               <input 
                 autoFocus
                 type="text"
                 className="bg-white/20 border-b-2 border-white text-4xl font-black outline-none w-full px-2 py-1 rounded transition-all focus:bg-white/30"
                 value={tempName}
                 onChange={(e) => setTempName(e.target.value)}
                 onBlur={handleSaveName}
                 onKeyDown={(e) => {
                   if (e.key === 'Enter') handleSaveName();
                   if (e.key === 'Escape') { setIsEditingName(false); setTempName(dish.name); }
                 }}
               />
             ) : (
               <h2 
                 className="text-4xl font-black drop-shadow-md cursor-pointer hover:underline decoration-white/30 underline-offset-8 flex items-center gap-3 group"
                 onClick={() => setIsEditingName(true)}
               >
                 {dish.name}
                 <span className="text-xl opacity-0 group-hover:opacity-60 transition-opacity">✎</span>
               </h2>
             )}
           </div>
        </div>

        <div className="p-8">
