import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  // Toast System State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setIsInitializing(false);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败，请检查存储空间。", 'error');
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
    } catch (e) {
      setSyncStatus('error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", 'success');
      } catch (e) {
        setSyncStatus('error');
      }
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40">
          <div className="relative">
            <div className="animate-spin rounded-full h-20 w-20 border-[6px] border-orange-100 border-t-orange-500"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <p className="mt-8 text-gray-500 font-black tracking-widest uppercase text-xs animate-pulse">正在同步您的私人菜谱库</p>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            recentlyViewedDishes={recentlyViewedDishes}
            onAddDish={addDish} 
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            recentlyViewedDishes={[]}
            onAddDish={addDish} 
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
      default:
        return (
          <CollectionView 
            dishes={dishes} 
            recentlyViewedDishes={[]}
            onAddDish={addDish} 
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
    }
  };

  const selectedDishForChat = currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined;

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-in slide-in-from-top duration-300">
           <div className={`px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 border ${toast.type === 'success' ? 'bg-green-600 border-green-500' : 'bg-red-600 border-red-500'} text-white`}>
              <span className="text-lg">{toast.type === 'success' ? '✅' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
              <div className="absolute bottom-0 left-0 h-1 bg-white/30 rounded-full animate-[toastProgress_3s_linear_forwards]"></div>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
          {syncStatus === 'error' && (
            <span className="flex items-center gap-1 text-red-500">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd"></path></svg>
              同步故障
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={selectedDishForChat} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Dish, UserPreferences } from '../types';

interface GlobalChatBotProps {
  currentDish?: Dish;
  preferences: UserPreferences;
}

const GlobalChatBot: React.FC<GlobalChatBotProps> = ({ currentDish, preferences }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [message, setMessage] = useState('');
  const [history, setHistory] = useState<{ role: 'user' | 'ai', content: string }[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasUnread, setHasUnread] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [history, isOpen]);

  // Handle auto-clearing unread when opening
  useEffect(() => {
    if (isOpen && hasUnread) {
      setHasUnread(false);
    }
  }, [isOpen, hasUnread]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!message.trim() || loading) return;

    const userMessage = message.trim();
    setHistory(prev => [...prev, { role: 'user', content: userMessage }]);
    setMessage('');
    setLoading(true);

    try {
      const response = await geminiService.proChat(userMessage, history, currentDish, preferences);
      setHistory(prev => [...prev, { role: 'ai', content: response }]);

      // If window is closed when response arrives, show red dot
      if (!isOpen) {
        setHasUnread(true);
      }
    } catch (err) {
      setHistory(prev => [...prev, { role: 'ai', content: '哎呀，后厨有点忙乱，请稍等一下再问我吧。' }]);
      if (!isOpen) setHasUnread(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`fixed bottom-8 right-8 z-[100] flex flex-col items-end transition-all ${isOpen ? 'w-[90vw] md:w-80 h-[70vh] md:h-[500px]' : 'w-14 h-14'}`}>
      {isOpen && (
        <div className="bg-white/95 backdrop-blur-md w-full flex-1 mb-4 rounded-3xl shadow-2xl border border-gray-100 flex flex-col overflow-hidden animate-in zoom-in duration-200 origin-bottom-right">
          <div className="bg-orange-500 p-4 text-white font-bold flex justify-between items-center shadow-lg">
            <div className="flex items-center gap-2">
              <span className="text-xl">👨‍🍳</span>
              <div className="flex flex-col">
                <span className="text-sm leading-tight">Pro 厨师助手</span>
                {currentDish && <span className="text-[10px] font-medium opacity-80">对话中：{currentDish.name}</span>}
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:rotate-90 transition p-1">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-hide bg-gray-50/50">
            {history.length === 0 && (
              <div className="bg-white p-3 rounded-2xl rounded-tl-none text-xs text-gray-700 shadow-sm border border-gray-100 leading-relaxed">
                你好！我是你的智能 Pro 厨师助手。
                您可以问我：
                <ul className="mt-2 space-y-1 list-disc list-inside text-orange-600 font-medium">
                  <li>“这道菜里的洋葱可以换成什么？”</li>
                  <li>“如何把牛排煎得更嫩？”</li>
                  <li>“给我推荐一个适合健身的午餐。”</li>
                </ul>
              </div>
            )}

            {history.map((chat, i) => (
              <div key={i} className={`flex ${chat.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-2xl text-xs leading-relaxed shadow-sm ${
                  chat.role === 'user' 
                    ? 'bg-orange-500 text-white rounded-tr-none' 
                    : 'bg-white text-gray-700 rounded-tl-none border border-gray-100'
                }`}>
                  {chat.content}
                </div>
              </div>
            ))}

            {loading && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl rounded-tl-none shadow-sm border border-gray-100 flex gap-1 items-center">
                  <span className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce delay-100"></span>
                  <span className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce delay-200"></span>
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <form onSubmit={handleSubmit} className="p-3 bg-white border-t border-gray-100 flex gap-2">
            <input
              autoFocus
              type="text"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              placeholder="向大厨提问..."
              className="flex-1 bg-gray-50 px-4 py-3 rounded-xl outline-none text-xs focus:ring-1 focus:ring-orange-400 transition-all"
              disabled={loading}
            />
            <button
              type="submit"
              disabled={loading || !message.trim()}
              className="bg-orange-500 text-white p-3 rounded-xl disabled:opacity-50 hover:bg-orange-600 shadow-md transition-all active:scale-95"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" />
              </svg>
            </button>
          </form>
        </div>
      )}

      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-2 ${
          isOpen ? 'bg-gray-800 text-white border-gray-700' : 'bg-orange-500 text-white border-white'
        }`}
      >
        {isOpen ? (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          <span className="relative">
            💬
            {hasUnread && (
              <span className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>
            )}
          </span>
        )}
      </button>
    </div>
  );
};

export default GlobalChatBot;

import React, { useState, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Dish, SuggestedDish, InstructionStep, UserPreferences } from '../types';

interface DiscoveryViewProps {
  onAddDish: (dish: Dish) => void;
  onViewRecipe: (id: string) => void;
  preferences: UserPreferences;
}

const DiscoveryView: React.FC<DiscoveryViewProps> = ({ onAddDish, onViewRecipe, preferences }) => {
  const [recommendations, setRecommendations] = useState<SuggestedDish[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingDish, setSavingDish] = useState<string | null>(null);

  const fetchDiscovery = async () => {
    setLoading(true);
    try {
      const res = await geminiService.getDiscoveryRecommendations(preferences);
      setRecommendations(res);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDiscovery();
  }, []);

  const handleSaveToCollection = async (suggested: SuggestedDish) => {
    setSavingDish(suggested.name);
    try {
      const details = await geminiService.getRecipeDetails(suggested.name, preferences);

      let imageUrl = '';
      try {
        imageUrl = await geminiService.generateDishImage(suggested.name);
      } catch (imgErr) {
        console.warn("Image generation failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: Date.now().toString(),
        name: suggested.name,
        ...details,
        instructions: finalSteps,
        imageUrl,
        createdAt: Date.now()
      };
      onAddDish(newDish);
    } catch (err) {
      // Toast error is handled in App.tsx via onAddDish wrapper normally, 
      // but if we call onAddDish it handles success toast.
    } finally {
      setSavingDish(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-end border-b border-orange-100 pb-4">
        <div>
          <h2 className="text-3xl font-black text-gray-800">发现灵感</h2>
          <p className="text-gray-500 mt-2 italic">
            看看今天 AI 为您推荐了哪些美味？
            {preferences.flavors.length > 0 && <span className="text-indigo-500 text-xs font-bold ml-2">已开启口味偏好推荐模式 ✨</span>}
          </p>
        </div>
        <button 
          onClick={fetchDiscovery}
          disabled={loading}
          className="flex items-center gap-2 text-orange-600 hover:text-orange-700 font-bold transition-all disabled:opacity-50"
        >
          <svg className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
          换一批
        </button>
      </div>

      {loading && recommendations.length === 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1,2,3,4,5,6].map(i => (
            <div key={i} className="bg-white rounded-3xl h-64 border border-gray-100 p-6 flex flex-col justify-between">
               <div className="space-y-4">
                  <div className="flex gap-2">
                    <div className="w-12 h-4 skeleton rounded"></div>
                    <div className="w-12 h-4 skeleton rounded"></div>
                  </div>
                  <div className="w-3/4 h-8 skeleton rounded"></div>
                  <div className="w-full h-16 skeleton rounded"></div>
               </div>
               <div className="w-full h-12 skeleton rounded-2xl"></div>
            </div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {recommendations.map((item, idx) => (
            <div key={idx} className="bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-xl transition-all p-6 flex flex-col justify-between group">
              <div>
                <div className="flex gap-2 mb-4">
                  <span className="px-2 py-0.5 bg-orange-100 text-orange-700 text-[10px] font-bold rounded uppercase">
                    {item.category}
                  </span>
                  <span className="px-2 py-0.5 bg-green-100 text-green-700 text-[10px] font-bold rounded uppercase">
                    {item.dishType}
                  </span>
                </div>
                <h3 className="text-2xl font-black text-gray-800 mb-3 group-hover:text-orange-600 transition-colors">{item.name}</h3>
                <p className="text-gray-500 text-sm leading-relaxed mb-6">
                  {item.reason}
                </p>
              </div>
              <button 
                onClick={() => handleSaveToCollection(item)}
                disabled={savingDish === item.name}
                className="w-full py-3 bg-orange-500 text-white font-bold rounded-2xl hover:bg-orange-600 transition shadow-lg shadow-orange-100 flex items-center justify-center gap-2 disabled:opacity-50"
              >
                {savingDish === item.name ? (
                  <>
                    <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    正在构思...
                  </>
                ) : (
                  <>✨ 立即收藏</>
                )}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

