import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<{id: string, name: string, status: string}[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  // Toast System State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setIsInitializing(false);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败，请检查存储空间。", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    // 立即添加占位状态
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '正在构思菜谱...' }]);

    try {
      // 1. 获取详情
      const details = await geminiService.getRecipeDetails(dishName, preferences);

      // 2. 更新状态
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '正在生成封面...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      // 3. 准备最终对象
      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      // 4. 保存并从待处理列表移除
      await addDish(newDish);
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    } catch (err) {
      console.error(err);
      showToast(`生成 ${dishName} 失败，请稍后重试。`, 'error');
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", "success");
    } catch (e) {
      setSyncStatus('error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", 'success');
      } catch (e) {
        setSyncStatus('error');
      }
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40">
          <div className="relative">
            <div className="animate-spin rounded-full h-20 w-20 border-[6px] border-orange-100 border-t-orange-500"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <p className="mt-8 text-gray-500 font-black tracking-widest uppercase text-xs animate-pulse">正在同步您的私人菜谱库</p>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
      default:
        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
    }
  };

  const selectedDishForChat = currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined;

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-in slide-in-from-top duration-300">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
              <div className={`absolute bottom-0 left-0 h-1 rounded-full animate-[toastProgress_3s_linear_forwards] ${toast.type === 'success' ? 'bg-emerald-200' : 'bg-white/30'}`}></div>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={selectedDishForChat} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, UserPreferences } from '../types';
import DishCard from '../components/DishCard';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  pendingDishes: {id: string, name: string, status: string}[];
  recentlyViewedDishes: Dish[];
  onGenerateInBackground: (name: string) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
  preferences: UserPreferences;
  onUpdatePreferences: (prefs: UserPreferences) => void;
}

const FLAVORS = ['辣', '甜', '咸', '淡', '酸', '苦', '麻', '鲜', '脆', '香'];

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  pendingDishes,
  recentlyViewedDishes,
  onGenerateInBackground, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate,
  preferences,
  onUpdatePreferences
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchByIngredients, setSearchByIngredients] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDishName.trim()) return;
    onGenerateInBackground(newDishName);
    setNewDishName('');
    setIsAdding(false);
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出失败");
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
      } catch (err) {
        alert(err instanceof Error ? err.message : "导入失败");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-6 bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    🕒 最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500 font-bold">✕</button>
               </div>
               <div className="space-y-2 max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div 
                     key={dish.id} 
                     onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }}
                     className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group"
                   >
                     <div className="w-10 h-10 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? (
                          <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>
                        )}
                     </div>
                     <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button 
            onClick={() => setIsRecentOpen(!isRecentOpen)}
            className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}
          >
            {isRecentOpen ? '✕' : '🕒'}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsPrefsOpen(!isPrefsOpen)}
            className={`w-10 h-10 rounded-full font-bold transition flex items-center justify-center border shadow-sm ${isPrefsOpen ? 'bg-indigo-500 text-white border-indigo-200 shadow-lg' : 'bg-white text-indigo-600 border-indigo-100 hover:bg-indigo-50'}`}
          >
            ⚙️
          </button>
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200">
             <button onClick={handleExport} className="p-2 hover:bg-white rounded-full transition text-gray-600">📤</button>
             <button onClick={() => fileInputRef.current?.click()} className="p-2 hover:bg-white rounded-full transition text-gray-600">📥</button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"
          >
            <span>➕</span> 添加新菜肴
          </button>
        </div>
      </div>

      {isPrefsOpen && (
        <div className="bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
           <h3 className="text-sm font-black text-indigo-900 mb-4 flex items-center gap-2">
             口味偏好（AI 将在生成新菜谱时参考）
           </h3>
           <div className="flex flex-wrap gap-2">
             {FLAVORS.map(flavor => (
               <button
                 key={flavor}
                 onClick={() => toggleFlavor(flavor)}
                 className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${preferences.flavors.includes(flavor) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-indigo-400 border-indigo-100'}`}
               >
                 {flavor}
               </button>
             ))}
           </div>
        </div>
      )}

      <div className="space-y-4">
        <div className="relative">
          <input 
            type="text" 
            placeholder={searchByIngredients ? "输入食材名进行搜索..." : "输入菜名进行搜索..."}
            className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 outline-none transition"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <div className="absolute left-3 top-3.5 text-gray-400">🔍</div>
        </div>
        <div className="flex items-center gap-4 px-1">
          <label className="flex items-center gap-2 cursor-pointer">
            <input 
              type="checkbox" 
              checked={searchByIngredients}
              onChange={() => setSearchByIngredients(!searchByIngredients)}
              className="rounded text-orange-500 focus:ring-orange-400"
            />
            <span className="text-xs font-bold text-gray-500">🥕 同时搜索食材</span>
          </label>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input 
                autoFocus
                type="text" 
                placeholder="例如：红烧肉、麻辣香锅..."
                className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400"
                value={newDishName}
                onChange={(e) => setNewDishName(e.target.value)}
              />
              <p className="text-sm text-gray-500">点击添加后，AI 将在后台为您准备，您可以继续添加其他菜肴。</p>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsAdding(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition">取消</button>
                <button type="submit" disabled={!newDishName.trim()} className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 shadow-lg disabled:opacity-50">立即添加</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* 展示待生成的占位卡片 */}
        {pendingDishes.map(pending => (
          <div key={pending.id} className="bg-white border-2 border-dashed border-orange-200 rounded-3xl p-6 flex flex-col justify-between h-[200px] animate-pulse-soft">
             <div>
               <div className="flex justify-between items-start mb-4">
                 <div className="w-16 h-6 skeleton rounded-lg"></div>
                 <div className="w-6 h-6 rounded-full border-2 border-orange-500 border-t-transparent animate-spin"></div>
               </div>
               <h3 className="text-xl font-black text-gray-400 mb-2 truncate">{pending.name}</h3>
               <p className="text-orange-500 text-xs font-bold italic">{pending.status}</p>
             </div>
             <div className="w-full h-10 skeleton rounded-2xl opacity-50"></div>
          </div>
        ))}

        {filteredDishes.map(dish => (
          <DishCard 
            key={dish.id} 
            dish={dish} 
            onView={onViewRecipe}
            onDelete={onDeleteDish}
          />
        ))}

        {filteredDishes.length === 0 && pendingDishes.length === 0 && (
          <div className="col-span-full text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            <p className="text-gray-400 text-lg">您的菜谱库还是空的。</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<{id: string, name: string, status: string}[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  // Toast System State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setIsInitializing(false);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败，请检查存储空间。", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '正在构思菜谱...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '正在生成封面...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    } catch (err) {
      console.error(err);
      showToast(`生成 ${dishName} 失败，请稍后重试。`, 'error');
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", "success");
    } catch (e) {
      setSyncStatus('error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", 'success');
      } catch (e) {
        setSyncStatus('error');
      }
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40">
          <div className="relative">
            <div className="animate-spin rounded-full h-20 w-20 border-[6px] border-orange-100 border-t-orange-500"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <p className="mt-8 text-gray-500 font-black tracking-widest uppercase text-xs animate-pulse">正在同步您的私人菜谱库</p>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
      default:
        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
          />
        );
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24">
        {renderView()}
      </main>

      {/* Global Toast - Optimized for better aesthetics */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-toast-in">
           <div className={`px-8 py-4 rounded-3xl shadow-2xl flex items-center gap-4 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-lg ${toast.type === 'success' ? 'bg-emerald-100' : 'bg-white/20'}`}>
                {toast.type === 'success' ? '✨' : '❌'}
              </div>
              <span className="font-bold text-sm tracking-tight whitespace-nowrap">{toast.message}</span>
              <div className={`absolute bottom-1 left-4 right-4 h-0.5 rounded-full overflow-hidden ${toast.type === 'success' ? 'bg-emerald-100' : 'bg-white/20'}`}>
                <div className={`h-full animate-[toastProgress_3s_linear_forwards] ${toast.type === 'success' ? 'bg-emerald-400' : 'bg-white'}`}></div>
              </div>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, UserPreferences } from '../types';
import DishCard from '../components/DishCard';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  pendingDishes: {id: string, name: string, status: string}[];
  recentlyViewedDishes: Dish[];
  onGenerateInBackground: (name: string) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
  preferences: UserPreferences;
  onUpdatePreferences: (prefs: UserPreferences) => void;
}

const FLAVORS = ['辣', '甜', '咸', '淡', '酸', '苦', '麻', '鲜', '脆', '香'];

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  pendingDishes,
  recentlyViewedDishes,
  onGenerateInBackground, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate,
  preferences,
  onUpdatePreferences
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchByIngredients, setSearchByIngredients] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDishName.trim()) return;
    onGenerateInBackground(newDishName);
    setNewDishName('');
    setIsAdding(false);
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出失败");
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
      } catch (err) {
        alert(err instanceof Error ? err.message : "导入失败");
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-6 bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2 text-gray-400">
                 <h3 className="text-xs font-black uppercase tracking-widest flex items-center gap-2">
                    🕒 最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="hover:text-orange-500 font-bold transition-colors">✕</button>
               </div>
               <div className="space-y-2 max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div 
                     key={dish.id} 
                     onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }}
                     className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group"
                   >
                     <div className="w-10 h-10 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? (
                          <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>
                        )}
                     </div>
                     <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button 
            onClick={() => setIsRecentOpen(!isRecentOpen)}
            className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}
          >
            {isRecentOpen ? '✕' : '🕒'}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsPrefsOpen(!isPrefsOpen)}
            className={`w-10 h-10 rounded-full font-bold transition flex items-center justify-center border shadow-sm ${isPrefsOpen ? 'bg-indigo-500 text-white border-indigo-200 shadow-lg' : 'bg-white text-indigo-600 border-indigo-100 hover:bg-indigo-50'}`}
          >
            ⚙️
          </button>
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200">
             <button onClick={handleExport} className="p-2 hover:bg-white rounded-full transition text-gray-600">📤</button>
             <button onClick={() => fileInputRef.current?.click()} className="p-2 hover:bg-white rounded-full transition text-gray-600">📥</button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"
          >
            <span>➕</span> 添加新菜肴
          </button>
        </div>
      </div>

      {isPrefsOpen && (
        <div className="bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
           <h3 className="text-sm font-black text-indigo-900 mb-4">口味偏好（AI 参考）</h3>
           <div className="flex flex-wrap gap-2">
             {FLAVORS.map(flavor => (
               <button
                 key={flavor}
                 onClick={() => toggleFlavor(flavor)}
                 className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${preferences.flavors.includes(flavor) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-indigo-400 border-indigo-100'}`}
               >
                 {flavor}
               </button>
             ))}
           </div>
        </div>
      )}

      <div className="space-y-4">
        <div className="relative">
          <input 
            type="text" 
            placeholder={searchByIngredients ? "输入食材名进行搜索..." : "输入菜名进行搜索..."}
            className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 outline-none transition"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <div className="absolute left-3 top-3.5 text-gray-400">🔍</div>
        </div>
        <div className="flex items-center gap-4 px-1">
          <label className="flex items-center gap-2 cursor-pointer">
            <input 
              type="checkbox" 
              checked={searchByIngredients}
              onChange={() => setSearchByIngredients(!searchByIngredients)}
              className="rounded text-orange-500 focus:ring-orange-400"
            />
            <span className="text-xs font-bold text-gray-500">🥕 同时搜索食材</span>
          </label>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800 text-center">告诉我你想吃的菜</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input 
                autoFocus
                type="text" 
                placeholder="例如：红烧肉、麻辣香锅..."
                className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400 transition-all"
                value={newDishName}
                onChange={(e) => setNewDishName(e.target.value)}
              />
              <p className="text-xs text-gray-400 text-center leading-relaxed px-4">提交后，AI 将在后台为您准备配方。<br/>您可以立即输入下一道菜。</p>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsAdding(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition">取消</button>
                <button type="submit" disabled={!newDishName.trim()} className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 shadow-lg disabled:opacity-50 transition-all active:scale-95">确认添加</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* 展示待生成的卡片 - 增强视觉细节 */}
        {pendingDishes.map(pending => (
          <div key={pending.id} className="bg-white border-2 border-dashed border-orange-100 rounded-[2rem] p-6 flex flex-col justify-between h-[210px] animate-pulse-soft">
             <div>
               <div className="flex justify-between items-start mb-4">
                 <div className="w-16 h-6 skeleton rounded-lg"></div>
                 <div className="w-5 h-5 rounded-full border-2 border-orange-500 border-t-transparent animate-spin"></div>
               </div>
               <h3 className="text-lg font-black text-gray-400 mb-2 truncate">{pending.name}</h3>
               <div className="flex items-center gap-2">
                 <div className="w-2 h-2 rounded-full bg-orange-500 animate-ping"></div>
                 <p className="text-orange-500 text-[10px] font-black italic uppercase tracking-wider">{pending.status}</p>
               </div>
             </div>
             <div className="w-full h-11 skeleton rounded-2xl opacity-40"></div>
          </div>
        ))}

        {filteredDishes.map(dish => (
          <DishCard 
            key={dish.id} 
            dish={dish} 
            onView={onViewRecipe}
            onDelete={onDeleteDish}
          />
        ))}

        {filteredDishes.length === 0 && pendingDishes.length === 0 && (
          <div className="col-span-full text-center py-32 bg-gray-50/50 rounded-[3rem] border-4 border-dotted border-gray-100">
            <div className="text-4xl mb-4">📖</div>
            <p className="text-gray-400 font-medium">您的菜谱库正在等待开启...</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  // Toast System State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3500);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败，请检查存储空间。", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("更新失败", 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已从收藏夹中移除", 'success');
      } catch (e) {
        setSyncStatus('error');
        showToast("删除失败", 'error');
      }
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
              <div className={`absolute bottom-0 left-0 h-1 rounded-full animate-[toastProgress_3.5s_linear_forwards] ${toast.type === 'success' ? 'bg-emerald-300' : 'bg-white/30'}`}></div>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, UserPreferences } from '../types';
import DishCard from '../components/DishCard';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  pendingDishes: {id: string, name: string, status: string}[];
  recentlyViewedDishes: Dish[];
  onGenerateInBackground: (name: string) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
  preferences: UserPreferences;
  onUpdatePreferences: (prefs: UserPreferences) => void;
  onShowToast: (msg: string, type?: 'success' | 'error') => void;
}

const FLAVORS = ['辣', '甜', '咸', '淡', '酸', '苦', '麻', '鲜', '脆', '香'];

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  pendingDishes,
  recentlyViewedDishes,
  onGenerateInBackground, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate,
  preferences,
  onUpdatePreferences,
  onShowToast
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchByIngredients, setSearchByIngredients] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const name = newDishName.trim();
    if (!name) return;

    // 立即反馈：关闭弹窗，清空输入，开始后台生成
    onGenerateInBackground(name);
    setNewDishName('');
    setIsAdding(false);
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      onShowToast("菜谱备份已导出", 'success');
    } catch (e) {
      onShowToast("导出失败", 'error');
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
        onShowToast("导入成功！已同步您的菜谱库。", 'success');
      } catch (err) {
        onShowToast(err instanceof Error ? err.message : "导入失败", 'error');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-6 bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               </div>
               <div className="space-y-2 max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div key={dish.id} onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }} className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group">
                     <div className="w-12 h-12 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" /> : <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>}
                     </div>
                     <div className="flex-1 min-w-0">
                       <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                       <p className="text-[10px] text-gray-400">{dish.category}</p>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button onClick={() => setIsRecentOpen(!isRecentOpen)} className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}>
            {isRecentOpen ? <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg> : <span className="relative">🕒</span>}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2">
          <button onClick={() => setIsPrefsOpen(!isPrefsOpen)} className={`w-10 h-10 rounded-full font-bold transition flex items-center justify-center border shadow-sm ${isPrefsOpen ? 'bg-indigo-500 text-white border-indigo-200 shadow-lg' : 'bg-white text-indigo-600 border-indigo-100 hover:bg-indigo-50'}`} title="偏好设置"><span>⚙️</span></button>
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200 shadow-sm">
             <button onClick={handleExport} title="导出备份" className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg></button>
             <button onClick={() => fileInputRef.current?.click()} title="导入备份" className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg></button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button onClick={() => setIsAdding(true)} className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"><span>➕</span> 添加新菜肴</button>
        </div>
      </div>

      {isPrefsOpen && (
        <div className="bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
           <h3 className="text-sm font-black text-indigo-900 mb-4 flex items-center gap-2">口味偏好（AI 将在生成新菜谱和推荐时优先考虑）</h3>
           <div className="flex flex-wrap gap-2">
             {FLAVORS.map(flavor => (
               <button key={flavor} onClick={() => toggleFlavor(flavor)} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${preferences.flavors.includes(flavor) ? 'bg-indigo-600 text-white border-indigo-400 shadow-md transform scale-105' : 'bg-white text-indigo-400 border-indigo-100 hover:border-indigo-300'}`}>
                 {flavor}{preferences.flavors.includes(flavor) && <span className="ml-1.5">✓</span>}
               </button>
             ))}
           </div>
        </div>
      )}

      <div className="space-y-4">
        <div className="relative">
          <input type="text" placeholder={searchByIngredients ? "输入食材名进行搜索..." : "输入菜名进行搜索..."} className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 focus:border-transparent outline-none transition shadow-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        <div className="flex items-center gap-4 px-1">
          <label className="flex items-center gap-2 cursor-pointer group">
            <input type="checkbox" className="hidden peer" checked={searchByIngredients} onChange={() => setSearchByIngredients(!searchByIngredients)} />
            <div className="w-4 h-4 rounded border-2 border-gray-300 peer-checked:bg-orange-500 peer-checked:border-orange-500 transition-all flex items-center justify-center"><svg className="w-3 h-3 text-white opacity-0 peer-checked:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg></div>
            <span className="text-xs font-bold text-gray-500 group-hover:text-orange-500 transition-colors">🥕 同时搜索食材</span>
          </label>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input autoFocus type="text" placeholder="例如：红烧肉、麻辣香锅..." className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400" value={newDishName} onChange={(e) => setNewDishName(e.target.value)} />
              <p className="text-sm text-gray-500">点击添加后，AI 将在后台为您制定配方。您可以继续添加其他菜肴。</p>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsAdding(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition">取消</button>
                <button type="submit" disabled={!newDishName.trim()} className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 transition shadow-lg shadow-orange-200 disabled:opacity-50 min-w-[140px]">立即添加</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* 展示待生成的卡片 */}
        {pendingDishes.map(pending => (
          <div key={pending.id} className="bg-white border-2 border-dashed border-orange-100 rounded-3xl p-6 flex flex-col justify-between h-[210px] animate-pulse-soft">
             <div>
               <div className="flex justify-between items-start mb-4">
                 <div className="w-16 h-6 skeleton rounded-lg"></div>
                 <div className="w-5 h-5 rounded-full border-2 border-orange-400 border-t-transparent animate-spin"></div>
               </div>
               <h3 className="text-xl font-black text-gray-300 mb-2 truncate">{pending.name}</h3>
               <p className="text-orange-400 text-xs font-bold italic">{pending.status}</p>
             </div>
             <div className="w-full h-11 skeleton rounded-2xl opacity-40"></div>
          </div>
        ))}

        {filteredDishes.length > 0 ? (
          filteredDishes.map(dish => <DishCard key={dish.id} dish={dish} onView={onViewRecipe} onDelete={onDeleteDish} />)
        ) : pendingDishes.length === 0 ? (
          <div className="col-span-full text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            <p className="text-gray-400 text-lg">您的菜谱库还是空的</p>
          </div>
        ) : null}
      </div>
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  // Toast System State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    if (toast) {
      // 缩短反馈时间到 2 秒，让交互更快速
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败，请检查存储空间。", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("更新失败", 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", 'success');
      } catch (e) {
        setSyncStatus('error');
        showToast("删除失败", 'error');
      }
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24">
        {renderView()}
      </main>

      {/* Global Toast - Removed loading bar and shortened duration */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, UserPreferences } from '../types';
import DishCard from '../components/DishCard';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  pendingDishes: {id: string, name: string, status: string}[];
  recentlyViewedDishes: Dish[];
  onGenerateInBackground: (name: string) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
  preferences: UserPreferences;
  onUpdatePreferences: (prefs: UserPreferences) => void;
  onShowToast: (msg: string, type?: 'success' | 'error') => void;
}

const FLAVORS = ['辣', '甜', '咸', '淡', '酸', '苦', '麻', '鲜', '脆', '香'];

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  pendingDishes,
  recentlyViewedDishes,
  onGenerateInBackground, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate,
  preferences,
  onUpdatePreferences,
  onShowToast
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchByIngredients, setSearchByIngredients] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const name = newDishName.trim();
    if (!name) return;

    onGenerateInBackground(name);
    setNewDishName('');
    setIsAdding(false);
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      onShowToast("菜谱备份已导出", 'success');
    } catch (e) {
      onShowToast("导出失败", 'error');
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
        onShowToast("导入成功！已同步您的菜谱库。", 'success');
      } catch (err) {
        onShowToast(err instanceof Error ? err.message : "导入失败", 'error');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-6 bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               </div>
               <div className="space-y-2 max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div key={dish.id} onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }} className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group">
                     <div className="w-12 h-12 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" /> : <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>}
                     </div>
                     <div className="flex-1 min-w-0">
                       <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                       <p className="text-[10px] text-gray-400">{dish.category}</p>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button onClick={() => setIsRecentOpen(!isRecentOpen)} className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}>
            {isRecentOpen ? <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg> : <span className="relative">🕒</span>}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2">
          <button onClick={() => setIsPrefsOpen(!isPrefsOpen)} className={`w-10 h-10 rounded-full font-bold transition flex items-center justify-center border shadow-sm ${isPrefsOpen ? 'bg-indigo-500 text-white border-indigo-200 shadow-lg' : 'bg-white text-indigo-600 border-indigo-100 hover:bg-indigo-50'}`} title="偏好设置"><span>⚙️</span></button>
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200 shadow-sm">
             <button onClick={handleExport} title="导出备份" className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg></button>
             <button onClick={() => fileInputRef.current?.click()} title="导入备份" className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg></button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button onClick={() => setIsAdding(true)} className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-lg shadow-orange-100"><span>➕</span> 添加新菜肴</button>
        </div>
      </div>

      {isPrefsOpen && (
        <div className="bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
           <h3 className="text-sm font-black text-indigo-900 mb-4 flex items-center gap-2">口味偏好</h3>
           <div className="flex flex-wrap gap-2">
             {FLAVORS.map(flavor => (
               <button key={flavor} onClick={() => toggleFlavor(flavor)} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${preferences.flavors.includes(flavor) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-indigo-400 border-indigo-100'}`}>
                 {flavor}
               </button>
             ))}
           </div>
        </div>
      )}

      <div className="space-y-4">
        {/* 搜索栏 */}
        <div className="relative">
          <input type="text" placeholder={searchByIngredients ? "输入食材名进行搜索..." : "输入菜名进行搜索..."} className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 outline-none transition shadow-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* 筛选标签栏 */}
        <div className="space-y-3">
          <div className="flex overflow-x-auto scrollbar-hide gap-2 pb-1">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`flex-shrink-0 px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-400' : 'bg-white text-gray-500 border-gray-100 hover:border-orange-200'}`}
              >
                {cat}
              </button>
            ))}
          </div>
          <div className="flex overflow-x-auto scrollbar-hide gap-2 pb-1">
            {dishTypes.map(type => (
              <button
                key={type}
                onClick={() => setSelectedDishType(type)}
                className={`flex-shrink-0 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all border ${selectedDishType === type ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-white text-gray-400 border-gray-100 hover:border-emerald-200'}`}
              >
                {type}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-4 px-1">
          <label className="flex items-center gap-2 cursor-pointer group">
            <input type="checkbox" className="hidden peer" checked={searchByIngredients} onChange={() => setSearchByIngredients(!searchByIngredients)} />
            <div className="w-4 h-4 rounded border-2 border-gray-300 peer-checked:bg-orange-500 peer-checked:border-orange-500 transition-all flex items-center justify-center"><svg className="w-3 h-3 text-white opacity-0 peer-checked:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg></div>
            <span className="text-xs font-bold text-gray-500 group-hover:text-orange-500 transition-colors">🥕 同时搜索食材</span>
          </label>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input autoFocus type="text" placeholder="例如：红烧肉、麻辣香锅..." className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400" value={newDishName} onChange={(e) => setNewDishName(e.target.value)} />
              <p className="text-sm text-gray-500">点击添加后，AI 将在后台为您制定配方。</p>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsAdding(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition">取消</button>
                <button type="submit" disabled={!newDishName.trim()} className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 transition shadow-lg disabled:opacity-50">立即添加</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {pendingDishes.map(pending => (
          <div key={pending.id} className="bg-white border-2 border-dashed border-orange-100 rounded-3xl p-6 flex flex-col justify-between h-[210px] animate-pulse-soft">
             <div>
               <div className="flex justify-between items-start mb-4">
                 <div className="w-16 h-6 skeleton rounded-lg"></div>
                 <div className="w-5 h-5 rounded-full border-2 border-orange-400 border-t-transparent animate-spin"></div>
               </div>
               <h3 className="text-xl font-black text-gray-300 mb-2 truncate">{pending.name}</h3>
               <p className="text-orange-400 text-xs font-bold italic">{pending.status}</p>
             </div>
             <div className="w-full h-11 skeleton rounded-2xl opacity-40"></div>
          </div>
        ))}

        {filteredDishes.length > 0 ? (
          filteredDishes.map(dish => <DishCard key={dish.id} dish={dish} onView={onViewRecipe} onDelete={onDeleteDish} />)
        ) : pendingDishes.length === 0 ? (
          <div className="col-span-full text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            <p className="text-gray-400 text-lg">暂无匹配的菜谱</p>
          </div>
        ) : null}
      </div>
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  // 发现页推荐缓存
  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);

  // Toast System State
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  // 初始化应用数据
  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败，请检查存储空间。", 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;

    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("更新失败", 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", 'success');
      } catch (e) {
        setSyncStatus('error');
        showToast("删除失败", 'error');
      }
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return (
          <DiscoveryView 
            onAddDish={addDish} 
            onViewRecipe={viewRecipe} 
            preferences={preferences} 
            cache={discoveryCache}
            onUpdateCache={setDiscoveryCache}
          />
        );
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Dish } from '../types';

interface DishCardProps {
  dish: Dish;
  onView: (id: string) => void;
  onDelete: (id: string) => void;
  onRefreshImage?: (id: string) => void;
}

const COMMON_INGREDIENTS = [
  '盐', '油', '醋', '糖', '酱油', '生抽', '老抽', '料酒', '葱', '姜', '蒜', '水', 
  '淀粉', '味精', '鸡精', '胡椒粉', '八角', '桂皮', '花椒', '芝麻油', '蚝油'
];

const DishCard: React.FC<DishCardProps> = ({ dish, onView, onDelete, onRefreshImage }) => {
  const [isRefreshing, setIsRefreshing] = useState(false);

  const handleRefresh = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!onRefreshImage || isRefreshing) return;
    setIsRefreshing(true);
    await onRefreshImage(dish.id);
    setIsRefreshing(false);
  };

  const mainIngredientTags = dish.ingredients
    ? dish.ingredients
        .filter(ing => !COMMON_INGREDIENTS.some(common => ing.name.includes(common)))
        .slice(0, 3)
    : [];

  const calculateTotalTime = () => {
    if (!Array.isArray(dish.instructions)) return 0;
    return dish.instructions.reduce((acc, step) => {
      if (typeof step === 'object' && step !== null && 'timeMinutes' in step) {
        return acc + (Number(step.timeMinutes) || 0);
      }
      if (typeof step === 'string') {
        return acc + 3;
      }
      return acc;
    }, 0);
  };

  const totalTime = calculateTotalTime();

  return (
    <div className="bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-500 flex flex-col group overflow-hidden relative">
      <div className="absolute top-0 left-0 w-1 group-hover:w-2 h-full bg-orange-500 opacity-70 group-hover:opacity-100 transition-all duration-500 z-10"></div>

      {/* 封面展示区 */}
      {dish.imageUrl && (
        <div className="relative h-40 overflow-hidden">
          <img 
            src={dish.imageUrl} 
            alt={dish.name} 
            className="w-full h-full object-cover group-hover:scale-110 transition duration-700"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent"></div>

          {/* 刷新小图标 */}
          <button 
            onClick={handleRefresh}
            className={`absolute top-3 right-3 p-2 rounded-full bg-white/20 backdrop-blur-md border border-white/30 text-white hover:bg-white/40 transition-all z-20 ${isRefreshing ? 'animate-spin' : ''}`}
            title="重新生成封面照"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            </svg>
          </button>
        </div>
      )}

      <div className="p-5 pl-7 flex-1 flex flex-col">
        <div className="flex justify-between items-start mb-3">
          <div className="flex flex-wrap gap-1.5">
            <span className="px-2.5 py-1 bg-orange-50 text-orange-600 text-[10px] font-black rounded-lg uppercase tracking-wider border border-orange-100">
              {dish.category}
            </span>
            {dish.dishType && (
              <span className="px-2.5 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black rounded-lg uppercase tracking-wider border border-emerald-100">
                {dish.dishType}
              </span>
            )}
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); onDelete(dish.id); }}
            className="text-gray-300 hover:text-red-500 transition-colors p-1"
            title="删除菜谱"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
          </button>
        </div>

        <div className="flex justify-between items-end mb-2">
          <h3 className="text-xl font-black text-gray-800 truncate pr-2 group-hover:text-orange-600 transition-colors">{dish.name}</h3>
          {totalTime > 0 && (
            <span className="flex-shrink-0 text-[11px] font-bold text-gray-400 bg-gray-50 px-2 py-1 rounded-lg border border-gray-100 flex items-center gap-1">
              <span className="text-orange-400 opacity-70">⏱</span> {totalTime}min
            </span>
          )}
        </div>

        <div className="flex flex-wrap gap-1.5 mb-4">
          {mainIngredientTags.map((ing, idx) => (
            <span key={idx} className="text-[10px] px-2 py-1 bg-blue-50/50 text-blue-500 rounded-md border border-blue-100 font-medium">
              {ing.name}
            </span>
          ))}
          {mainIngredientTags.length === 0 && (
             <span className="text-[10px] px-2 py-1 bg-gray-50 text-gray-400 rounded-md italic">经典风味</span>
          )}
        </div>

        <p className="text-gray-500 text-sm line-clamp-2 mb-5 leading-relaxed h-10 overflow-hidden">
          {dish.description}
        </p>

        <button 
          onClick={() => onView(dish.id)}
          className="mt-auto w-full py-3 bg-gray-50 text-orange-600 font-black rounded-2xl border border-orange-100 hover:bg-orange-500 hover:text-white hover:shadow-lg hover:shadow-orange-200 transition-all duration-300 transform active:scale-[0.98]"
        >
          查看制作秘籍
        </button>
      </div>
    </div>
  );
};

