import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });
  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // 导入预览状态
  const [sharedDishes, setSharedDishes] = useState<Dish[] | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');

        // 检测 URL 分享数据
        const params = new URLSearchParams(window.location.search);
        const shareData = params.get('share_data');
        if (shareData) {
          try {
            const decoded = JSON.parse(atob(decodeURIComponent(shareData)));
            if (Array.isArray(decoded)) {
              setSharedDishes(decoded);
            }
          } catch (e) {
            console.error("解析分享数据失败", e);
          }
        }
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => {
        const exists = prev.find(d => d.id === dish.id);
        if (exists) return prev.map(d => d.id === dish.id ? dish : d);
        return [dish, ...prev];
      });
      setSyncStatus('saved');
      showToast(`已成功保存 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "保存失败，请检查浏览器存储设置。";
      showToast(errorMsg, 'error');
    }
  };

  const handleImportShared = async () => {
    if (!sharedDishes) return;
    try {
      setSyncStatus('syncing');
      for (const dish of sharedDishes) {
        await storageService.saveDish({ ...dish, createdAt: Date.now() });
      }
      const loaded = await storageService.getAllDishes();
      setDishes(loaded.sort((a, b) => b.createdAt - a.createdAt));
      setSharedDishes(null);
      // 清除 URL 参数
      window.history.replaceState({}, document.title, window.location.pathname);
      showToast(`成功导入 ${sharedDishes.length} 道菜谱！`, 'success');
      setSyncStatus('saved');
    } catch (e) {
      showToast("导入失败", "error");
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;
    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);
    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));
      let coverUrl: string | undefined = undefined;
      try { coverUrl = await geminiService.generateDishImage(dishName); } catch (imgErr) {}
      const finalSteps: InstructionStep[] = details.instructions.map(step => ({ ...step, imageUrl: undefined }));
      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };
      await addDish(newDish);
    } catch (err) {
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("更新失败", 'error');
    }
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", 'success');
      } catch (e) {
        setSyncStatus('error');
        showToast("删除失败", 'error');
      }
    }
  };

  const renderView = () => {
    if (isInitializing) return (
      <div className="flex flex-col items-center justify-center py-40">
        <div className="loader-ring"></div>
        <p className="mt-12 text-orange-500 font-bold">正在加载您的私人菜谱库...</p>
      </div>
    );

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds.map(id => dishes.find(d => d.id === id)).filter((d): d is Dish => !!d);
        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onManualAdd={addDish}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={(newD) => setDishes(newD.sort((a,b) => b.createdAt-a.createdAt))}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={(p) => { setPreferences(p); storageService.saveUserPreferences(p); }}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} cache={discoveryCache} onUpdateCache={setDiscoveryCache} />;
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? <RecipeView dish={dish} onBack={() => setCurrentView('collection')} onUpdateDish={updateDish} /> : null;
      default: return null;
    }
  };

  const viewRecipe = (id: string) => {
    setRecentlyViewedIds(storageService.recordView(id));
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-10 flex flex-col md:flex-row gap-4 justify-between items-center">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span> WhatToEat
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button onClick={() => setCurrentView('collection')} className={`px-4 py-2 rounded-full text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : ''}`}>我的菜谱</button>
          <button onClick={() => setCurrentView('discovery')} className={`px-4 py-2 rounded-full text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : ''}`}>发现灵感</button>
          <button onClick={() => setCurrentView('suggest')} className={`px-4 py-2 rounded-full text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : ''}`}>今天做什么？</button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24 relative">
        {sharedDishes && (
          <div className="mb-6 bg-indigo-50 border border-indigo-200 rounded-3xl p-6 animate-in slide-in-from-top duration-500">
            <h3 className="text-indigo-900 font-bold flex items-center gap-2 mb-2">
              <span className="text-xl">📥</span> 发现分享给您的 {sharedDishes.length} 道菜谱
            </h3>
            <div className="flex flex-wrap gap-2 mb-4">
              {sharedDishes.map(d => <span key={d.id} className="text-xs bg-white px-2 py-1 rounded-lg border border-indigo-100">{d.name}</span>)}
            </div>
            <div className="flex gap-2">
              <button onClick={handleImportShared} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-100">导入到我的库</button>
              <button onClick={() => {setSharedDishes(null); window.history.replaceState({}, document.title, window.location.pathname);}} className="px-4 py-2 bg-gray-200 text-gray-600 rounded-xl text-sm font-bold">忽略</button>
            </div>
          </div>
        )}
        {renderView()}
      </main>

      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm">{toast.message}</span>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="text-xs font-medium">
          {syncStatus === 'syncing' ? '同步中...' : '已保存到本地'}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat</div>
      </footer>
      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

