  });

  const handleManualSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!manualForm.name.trim()) return;
    const newDish: Dish = {
      ...manualForm,
      id: `manual-${Date.now()}`,
      createdAt: Date.now()
    };
    onManualAdd(newDish);
    setIsAdding(false);
