        </h2>
        {!isRemote && (
          <div className="flex gap-2">
            <button onClick={() => setIsSettingsOpen(!isSettingsOpen)} className={`w-10 h-10 rounded-full flex items-center justify-center border transition ${isSettingsOpen ? 'bg-indigo-500 text-white border-indigo-500' : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'}`}>⚙️</button>
            <button onClick={() => setIsAdding(true)} className="bg-orange-500 text-white px-6 py-2 rounded-full font-bold shadow-lg shadow-orange-100 hover:bg-orange-600 transition">➕ 添加菜肴</button>
          </div>
        )}
