                onKeyDown={(e) => { if(e.key === 'Enter') { const v = (e.target as any).value.trim(); if(v) { onUpdatePreferences({...preferences, flavors: [...preferences.flavors, v]}); (e.target as any).value = ''; } } }}
              />
           </div>

           <div className="pt-4 border-t border-indigo-100">
              <h3 className="text-sm font-black text-indigo-900 mb-3">实时云共享 (Firebase)</h3>
              <p className="text-[10px] text-indigo-400 mb-4 font-medium italic">开启云端同步后，您可以生成一个专属链接给家人朋友，您的任何修改都会实时同步给他们。</p>

