                         <div><label className="text-[10px] font-black uppercase text-gray-400 mb-1 block">分类</label><select value={manualForm.category} onChange={e => setManualForm({...manualForm, category: e.target.value as Category})} className="w-full px-4 py-3 bg-gray-50 rounded-xl outline-none border border-gray-100 focus:ring-1 focus:ring-orange-400">{Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                         <div><label className="text-[10px] font-black uppercase text-gray-400 mb-1 block">类型</label><select value={manualForm.dishType} onChange={e => setManualForm({...manualForm, dishType: e.target.value as DishType})} className="w-full px-4 py-3 bg-gray-50 rounded-xl outline-none border border-gray-100 focus:ring-1 focus:ring-orange-400">{Object.values(DishType).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
                      </div>

                      <div><label className="text-[10px] font-black uppercase text-gray-400 mb-1 block">一句话简介</label><input value={manualForm.description} onChange={e => setManualForm({...manualForm, description: e.target.value})} className="w-full px-4 py-3 bg-gray-50 rounded-xl outline-none" /></div>

                      <div>
                        <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black uppercase text-gray-400">所需食材</label><button type="button" onClick={addIngredient} className="text-[10px] font-black text-orange-500">+ 添加行</button></div>
                        <div className="space-y-2">
                           {manualForm.ingredients.map((ing, i) => (
                             <div key={i} className="flex gap-2">
                                <input placeholder="名称" value={ing.name} onChange={e => { const ni = [...manualForm.ingredients]; ni[i].name = e.target.value; setManualForm({...manualForm, ingredients: ni}) }} className="flex-1 px-3 py-2 bg-gray-50 rounded-lg text-xs" />
                                <input placeholder="分量" value={ing.amount} onChange={e => { const ni = [...manualForm.ingredients]; ni[i].amount = e.target.value; setManualForm({...manualForm, ingredients: ni}) }} className="w-24 px-3 py-2 bg-gray-50 rounded-lg text-xs" />
                                <button type="button" onClick={() => setManualForm({...manualForm, ingredients: manualForm.ingredients.filter((_, idx) => idx !== i)})} className="text-gray-300 hover:text-red-400">✕</button>
                             </div>
                           ))}
                        </div>
                      </div>

                      <div>
                        <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black uppercase text-gray-400">制作步骤</label><button type="button" onClick={addStep} className="text-[10px] font-black text-orange-500">+ 添加步骤</button></div>
                        <div className="space-y-3">
                           {manualForm.instructions.map((step, i) => (
                             <div key={i} className="flex gap-2 items-start">
                                <span className="bg-gray-100 text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 mt-1">{i+1}</span>
                                <textarea placeholder="描述操作内容..." value={step.text} onChange={e => { const ni = [...manualForm.instructions]; ni[i].text = e.target.value; setManualForm({...manualForm, instructions: ni}) }} className="flex-1 px-3 py-2 bg-gray-50 rounded-lg text-xs min-h-[60px]" />
                                <input type="number" placeholder="min" value={step.timeMinutes} onChange={e => { const ni = [...manualForm.instructions]; ni[i].timeMinutes = parseInt(e.target.value); setManualForm({...manualForm, instructions: ni}) }} className="w-16 px-3 py-2 bg-gray-50 rounded-lg text-xs" />
                                <button type="button" onClick={() => setManualForm({...manualForm, instructions: manualForm.instructions.filter((_, idx) => idx !== i)})} className="text-gray-300 hover:text-red-400">✕</button>
                             </div>
                           ))}
                        </div>
                      </div>

                      <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-2xl shadow-xl hover:bg-orange-600 transition">💾 保存到我的库</button>
                   </form>
                 )}
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, InstructionStep, DishType, Category, Nutrition } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
  readOnly?: boolean;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish, readOnly }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  useEffect(() => { setTempName(dish.name); }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) onUpdateDish({ ...dish, name: trimmed });
    else setTempName(dish.name);
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;
    setLoading(true);
    setLoadingStatus('正在重构菜谱细节与营养分析...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);
      onUpdateDish({ ...dish, ...updatedDetails });
      setIsModifying(false);
      setInstruction('');
