import { Dish, UserPreferences, FirebaseConfig } from "../types";

declare var firebase: any;

const DB_NAME = "WhatToEatDB";
const STORE_NAME = "dishes";
const DB_VERSION = 1;
const RECENTLY_VIEWED_KEY = "recently-viewed-ids";
const PREFERENCES_KEY = "user-preferences";
const MAX_RECENT = 5;

export class StorageService {
  private db: IDBDatabase | null = null;
  private initPromise: Promise<void> | null = null;
  private firestore: any = null;

  async init(): Promise<void> {
    if (this.db) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      const prefs = this.getUserPreferences();
      if (prefs.firebaseConfig && !this.firestore) {
        this.initFirebase(prefs.firebaseConfig);
      }

      return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onerror = () => reject("IndexedDB failed");
        request.onsuccess = (event) => {
          this.db = (event.target as IDBOpenDBRequest).result;
          resolve();
        };
        request.onupgradeneeded = (event) => {
          const db = (event.target as IDBOpenDBRequest).result;
          if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: "id" });
          }
        };
      });
    })();
    return this.initPromise;
  }

  initFirebase(config: FirebaseConfig) {
    try {
      if (!firebase.apps.length) {
        firebase.initializeApp(config);
      }
      this.firestore = firebase.firestore();
    } catch (e) {
      console.error("Firebase init failed", e);
    }
  }

  async getAllDishes(): Promise<Dish[]> {
    await this.init();
    return new Promise((resolve) => {
      const transaction = this.db!.transaction([STORE_NAME], "readonly");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result);
    });
  }

  async saveDish(dish: Dish, syncToCloud: boolean = true): Promise<void> {
    await this.init();
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(dish);

      request.onsuccess = async () => {
        if (syncToCloud && this.firestore) {
          const prefs = this.getUserPreferences();
          if (prefs.libraryId) {
            try {
              await this.firestore.collection("libraries")
                .doc(prefs.libraryId)
                .collection("dishes")
                .doc(dish.id)
                .set(dish);
            } catch (e) {
              console.warn("Cloud sync failed", e);
            }
          }
        }
        resolve();
      };
      request.onerror = () => reject("Save failed");
    });
  }

  async deleteDish(id: string): Promise<void> {
    await this.init();
    return new Promise((resolve) => {
      const transaction = this.db!.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);
      request.onsuccess = async () => {
        if (this.firestore) {
          const prefs = this.getUserPreferences();
          if (prefs.libraryId) {
            await this.firestore.collection("libraries")
              .doc(prefs.libraryId)
              .collection("dishes")
              .doc(id)
              .delete();
          }
        }
        resolve();
      };
    });
  }

  /**
   * 实时订阅他人的共享库
   */
  subscribeToRemoteLibrary(libId: string, onUpdate: (dishes: Dish[]) => void) {
    if (!this.firestore) return () => {};
    return this.firestore.collection("libraries")
      .doc(libId)
      .collection("dishes")
      .onSnapshot((snapshot: any) => {
        const dishes: Dish[] = [];
        snapshot.forEach((doc: any) => {
          dishes.push({ ...doc.data(), remoteOwnerId: libId });
        });
        onUpdate(dishes);
      });
  }

  async uploadFullLibrary(): Promise<void> {
    if (!this.firestore) throw new Error("Firebase not initialized");
    const prefs = this.getUserPreferences();
    if (!prefs.libraryId) throw new Error("No Library ID");

    const dishes = await this.getAllDishes();
    const batch = this.firestore.batch();
    const libRef = this.firestore.collection("libraries").doc(prefs.libraryId).collection("dishes");

    dishes.forEach(dish => {
      const docRef = libRef.doc(dish.id);
      batch.set(docRef, dish);
    });

    return batch.commit();
  }

  getUserPreferences(): UserPreferences {
    const saved = localStorage.getItem(PREFERENCES_KEY);
    return saved ? JSON.parse(saved) : { flavors: [] };
  }

  saveUserPreferences(prefs: UserPreferences): void {
    localStorage.setItem(PREFERENCES_KEY, JSON.stringify(prefs));
    if (prefs.firebaseConfig && !this.firestore) {
      this.initFirebase(prefs.firebaseConfig);
    }
  }

  recordView(id: string): string[] {
    let ids = this.getRecentlyViewedIds();
    ids = Array.from(new Set([id, ...ids])).slice(0, MAX_RECENT);
    localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(ids));
    return ids;
  }

  getRecentlyViewedIds(): string[] {
    const saved = localStorage.getItem(RECENTLY_VIEWED_KEY);
    return saved ? JSON.parse(saved) : [];
  }

  async migrateFromLocalStorage(): Promise<void> {
    const saved = localStorage.getItem("my-dishes") || localStorage.getItem("delicious-secrets-dishes");
    if (!saved) return;
    try {
      const dishes = JSON.parse(saved);
      if (Array.isArray(dishes)) {
        for (const dish of dishes) await this.saveDish(dish, false);
      }
      localStorage.removeItem("my-dishes");
      localStorage.removeItem("delicious-secrets-dishes");
    } catch (e) {}
  }
}

export const storageService = new StorageService();

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error' | 'live'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });
  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // 共享库数据
  const [remoteLibId, setRemoteLibId] = useState<string | null>(null);
  const [remoteDishes, setRemoteDishes] = useState<Dish[]>([]);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');

        // 检测 URL 分享库 ?lib=LIBRARY_ID
        const params = new URLSearchParams(window.location.search);
        const libId = params.get('lib');
        if (libId) {
          setRemoteLibId(libId);
          setSyncStatus('live');
          storageService.subscribeToRemoteLibrary(libId, (newRemoteDishes) => {
            setRemoteDishes(newRemoteDishes);
            showToast("已连接到实时共享库", "success");
          });
        }
      } catch (e) {
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };
    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev.filter(d => d.id !== dish.id)]);
      setSyncStatus('saved');
      showToast(`已成功保存 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败", 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;
    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);
    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));
      let coverUrl: string | undefined = undefined;
      try { coverUrl = await geminiService.generateDishImage(dishName); } catch (imgErr) {}
      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: details.instructions.map(step => ({ ...step, imageUrl: undefined })),
        imageUrl: coverUrl,
        createdAt: Date.now()
      };
      await addDish(newDish);
    } catch (err) {
      showToast(`${dishName} 生成失败`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
    } catch (e) {
      setSyncStatus('error');
    }
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
      } catch (e) {
        setSyncStatus('error');
      }
    }
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) return (
      <div className="flex flex-col items-center justify-center py-40">
        <div className="loader-ring"></div>
        <p className="mt-12 text-orange-500 font-bold">正在加载您的私人菜谱库...</p>
      </div>
    );

    const activeDishes = remoteLibId ? remoteDishes : dishes;

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds.map(id => activeDishes.find(d => d.id === id)).filter((d): d is Dish => !!d);
        return (
          <CollectionView 
            dishes={activeDishes} 
            pendingDishes={remoteLibId ? [] : pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onManualAdd={addDish}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={(newD) => setDishes(newD)}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={(p) => { setPreferences(p); storageService.saveUserPreferences(p); }}
            onShowToast={showToast}
            isRemote={!!remoteLibId}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} cache={discoveryCache} onUpdateCache={setDiscoveryCache} />;
      case 'recipe':
        const dish = activeDishes.find(d => d.id === selectedDishId);
        return dish ? <RecipeView dish={dish} onBack={() => setCurrentView('collection')} onUpdateDish={updateDish} readOnly={!!remoteLibId} /> : null;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-50 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <div className="flex items-center gap-3">
           <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => { window.location.search = ''; setCurrentView('collection'); }}>
             <span className="text-3xl">🍴</span> WhatToEat
           </h1>
           {remoteLibId && <span className="bg-white/20 px-2 py-0.5 rounded text-[10px] font-bold animate-pulse">LIVE 共享库</span>}
        </div>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button onClick={() => setCurrentView('collection')} className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}>我的菜谱</button>
          <button onClick={() => setCurrentView('discovery')} className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}>发现灵感</button>
          <button onClick={() => setCurrentView('suggest')} className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}>今天做什么？</button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24 relative">{renderView()}</main>

      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && <span className="text-orange-500 animate-pulse">● 同步中...</span>}
          {syncStatus === 'saved' && <span className="text-green-600">✓ 已保存到本地</span>}
          {syncStatus === 'live' && <span className="text-indigo-600 font-bold tracking-tight">● 正在实时浏览</span>}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>
      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

