import React, { useState, useEffect } from 'react';
import { Dish, InstructionStep, DishType, Category, Nutrition } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
  readOnly?: boolean;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish, readOnly }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  useEffect(() => { setTempName(dish.name); }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) onUpdateDish({ ...dish, name: trimmed });
    else setTempName(dish.name);
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;
    setLoading(true);
    setLoadingStatus('正在重构菜谱细节...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);
      onUpdateDish({ ...dish, ...updatedDetails });
      setIsModifying(false);
      setInstruction('');
    } catch (err) { alert("调整失败"); }
    finally { setLoading(false); setLoadingStatus(''); }
  };

  const totalTime = (dish.instructions || []).reduce((acc, step) => acc + (step.timeMinutes || 0), 0);

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in duration-500 pb-20">
      <div className="flex justify-between items-center mb-6">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-500 hover:text-orange-500 font-bold transition">
          <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          返回
        </button>
        {!readOnly && (
          <button onClick={() => setIsModifying(!isModifying)} className={`px-4 py-2 rounded-full font-bold text-sm transition ${isModifying ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-indigo-600 border border-indigo-100'}`}>
            {isModifying ? '取消调整' : '✨ 调整/重写此菜谱'}
          </button>
        )}
      </div>

      {isModifying && (
        <div className="mb-8 bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
          <h4 className="text-indigo-900 font-bold mb-3 text-sm">你想如何调整这道菜？</h4>
          <div className="flex flex-wrap gap-2 mb-4">
            {["精简食材", "低卡健康", "少油少盐", "让口味更辣"].map(s => <button key={s} onClick={() => handleModify(s)} className="px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 font-bold rounded-full text-xs hover:bg-indigo-600 hover:text-white transition-colors">{s}</button>)}
          </div>
          <div className="flex gap-2">
            <input placeholder="输入您的修改想法..." className="flex-1 px-4 py-3 rounded-xl border border-indigo-200 outline-none text-sm" value={instruction} onChange={e => setInstruction(e.target.value)} disabled={loading} />
            <button onClick={() => handleModify()} disabled={loading || !instruction.trim()} className="px-6 bg-indigo-600 text-white font-bold rounded-xl text-sm">{loading ? '...' : '确认'}</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-sm border border-gray-100">
        <div className="aspect-video w-full bg-orange-100 relative overflow-hidden flex items-center justify-center">
           {dish.imageUrl ? <img src={dish.imageUrl} className="absolute inset-0 w-full h-full object-cover" /> : <span className="text-8xl">🍲</span>}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
           <div className="absolute bottom-6 left-8 right-8 text-white">
             <div className="flex gap-2 mb-2">
               <span className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-black uppercase">{dish.category}</span>
               <span className="px-3 py-1 bg-emerald-600 rounded-full text-[10px] font-black uppercase tracking-widest">{totalTime}min</span>
             </div>
             {isEditingName && !readOnly ? (
               <input autoFocus className="bg-transparent border-b-2 border-white text-4xl font-black outline-none w-full" value={tempName} onChange={e => setTempName(e.target.value)} onBlur={handleSaveName} onKeyDown={e => e.key === 'Enter' && handleSaveName()} />
             ) : (
               <h2 className="text-4xl font-black" onClick={() => !readOnly && setIsEditingName(true)}>{dish.name} {!readOnly && <span className="text-xs opacity-50 ml-2">✎</span>}</h2>
             )}
           </div>
        </div>

        <div className="p-8">
          <p className="text-gray-500 italic text-lg mb-10 leading-relaxed border-l-4 border-orange-200 pl-4">“{dish.description}”</p>

          <div className="mb-10">
            <h3 className="text-xl font-black text-gray-800 mb-6 flex items-center gap-2">🛒 所需食材</h3>
            <div className="grid grid-cols-2 gap-3">
              {(dish.ingredients || []).map((ing, i) => (
                <div key={i} className="flex justify-between items-center p-4 bg-gray-50 rounded-2xl border border-gray-100">
                  <span className="font-bold text-gray-700 text-sm">{ing.name}</span>
                  <span className="text-orange-600 text-xs font-black">{ing.amount}</span>
                </div>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-xl font-black text-gray-800 mb-8 flex items-center gap-2">👨‍🍳 烹饪步骤</h3>
            <div className="space-y-10">
              {(dish.instructions || []).map((step, i) => (
                <div key={i} className="flex gap-6">
                  <div className="flex-shrink-0 w-8 h-8 rounded-full bg-orange-500 text-white flex items-center justify-center font-black shadow-lg text-xs">{i+1}</div>
                  <div className="flex-1">
                    <p className="text-gray-700 leading-relaxed text-lg font-medium">{step.text}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      {loadingStatus && (
        <div className="fixed bottom-12 right-8 z-[200] bg-white/90 backdrop-blur px-4 py-3 rounded-2xl shadow-xl flex items-center gap-3">
           <div className="animate-spin h-4 w-4 border-2 border-orange-500 border-t-transparent rounded-full"></div>
           <span className="text-orange-600 text-xs font-black">{loadingStatus}</span>
        </div>
      )}
    </div>
  );
};

