              {addMode === 'ai' ? (
                <form onSubmit={(e) => { e.preventDefault(); const n = (e.target as any).name.value.trim(); if(n) { onGenerateInBackground(n); setIsAdding(false); } }} className="space-y-6">
                  <input name="name" autoFocus placeholder="输入菜名，AI 为你构思细节..." className="w-full px-6 py-5 bg-gray-50 border border-gray-100 rounded-2xl text-xl outline-none focus:ring-2 focus:ring-orange-400" />
                  <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-2xl shadow-xl">✨ 开始构思</button>
                </form>
              ) : (
                <form onSubmit={handleManualSubmit} className="space-y-6">
                  <div>
                    <label className="text-xs font-black text-gray-400 mb-2 block uppercase tracking-wider">菜名</label>
                    <input required value={manualName} onChange={e => setManualName(e.target.value)} className="w-full px-4 py-3 bg-gray-50 rounded-xl outline-none border border-gray-100 focus:ring-1 focus:ring-orange-400" />
                  </div>
                  <div>
                    <label className="text-xs font-black text-gray-400 mb-2 block uppercase tracking-wider">配料清单</label>
                    <div className="space-y-2">
                      {manualIngredients.map((ing, i) => (
                        <div key={i} className="flex gap-2">
                          <input placeholder="配料" value={ing.name} onChange={e => { const n = [...manualIngredients]; n[i].name = e.target.value; setManualIngredients(n); }} className="flex-1 px-3 py-2 bg-gray-50 rounded-lg text-sm" />
                          <input placeholder="用量" value={ing.amount} onChange={e => { const n = [...manualIngredients]; n[i].amount = e.target.value; setManualIngredients(n); }} className="w-24 px-3 py-2 bg-gray-50 rounded-lg text-sm" />
                        </div>
                      ))}
                      <button type="button" onClick={() => setManualIngredients([...manualIngredients, {name:'', amount:''}])} className="text-xs font-bold text-orange-500">+ 添加配料</button>
                    </div>
                  </div>
                  <div>
                    <label className="text-xs font-black text-gray-400 mb-2 block uppercase tracking-wider">制作步骤</label>
                    <div className="space-y-3">
                      {manualSteps.map((step, i) => (
                        <div key={i} className="flex gap-2 items-start">
                          <span className="bg-gray-100 text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 mt-1">{i+1}</span>
                          <textarea placeholder="步骤描述..." value={step.text} onChange={e => { const n = [...manualSteps]; n[i].text = e.target.value; setManualSteps(n); }} className="flex-1 px-3 py-2 bg-gray-50 rounded-lg text-sm min-h-[60px]" />
                        </div>
                      ))}
                      <button type="button" onClick={() => setManualSteps([...manualSteps, {text:'', timeMinutes: 5}])} className="text-xs font-bold text-orange-500">+ 添加步骤</button>
                    </div>
                  </div>
                  <button type="submit" className="w-full py-5 bg-orange-500 text-white font-black rounded-2xl shadow-xl">💾 保存菜谱</button>
                </form>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, InstructionStep, DishType, Category, Nutrition } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
  readOnly?: boolean;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish, readOnly }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  useEffect(() => { setTempName(dish.name); }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) onUpdateDish({ ...dish, name: trimmed });
    else setTempName(dish.name);
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;
    setLoading(true);
    setLoadingStatus('正在重构菜谱细节...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);
      onUpdateDish({ ...dish, ...updatedDetails });
      setIsModifying(false);
      setInstruction('');
    } catch (err) { alert("调整失败"); }
    finally { setLoading(false); setLoadingStatus(''); }
  };

  const totalTime = (dish.instructions || []).reduce((acc, step) => acc + (step.timeMinutes || 0), 0);

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in duration-500 pb-20 relative">
      <div className="flex justify-between items-center mb-6">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-500 hover:text-orange-500 font-medium transition">
          <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          返回
        </button>
        {!readOnly && (
          <button onClick={() => setIsModifying(!isModifying)} className={`px-4 py-2 rounded-full font-bold text-sm transition ${isModifying ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-indigo-600 border border-indigo-100'}`}>
            {isModifying ? '取消调整' : '✨ 调整/重写'}
          </button>
        )}
      </div>

      {isModifying && (
        <div className="mb-8 bg-indigo-50 rounded-3xl p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
          <h4 className="text-indigo-900 font-bold mb-3 text-sm">你想如何调整这道菜？</h4>
          <div className="flex flex-wrap gap-2 mb-4">
            {["精简食材", "低卡健康", "少油少盐", "让口味更辣"].map(s => <button key={s} onClick={() => handleModify(s)} className="px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 font-bold rounded-full text-xs hover:bg-indigo-600 hover:text-white transition-colors">{s}</button>)}
          </div>
          <div className="flex gap-2">
            <input placeholder="输入您的想法..." className="flex-1 px-4 py-3 rounded-xl border border-indigo-200 outline-none text-sm" value={instruction} onChange={e => setInstruction(e.target.value)} disabled={loading} />
            <button onClick={() => handleModify()} disabled={loading || !instruction.trim()} className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl text-sm transition active:scale-95">{loading ? '...' : '确认'}</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-100">
        <div className="aspect-video w-full bg-orange-100 relative flex items-center justify-center overflow-hidden">
           {dish.imageUrl ? <img src={dish.imageUrl} className="absolute inset-0 w-full h-full object-cover" /> : <span className="text-8xl">🍲</span>}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
           <div className="absolute bottom-6 left-8 right-8 text-white">
             <div className="flex gap-2 mb-2">
               <span className="px-3 py-1 bg-orange-500 rounded-full text-[10px] font-black uppercase">{dish.category}</span>
               <span className="px-3 py-1 bg-emerald-600 rounded-full text-[10px] font-black uppercase tracking-widest">{totalTime}min</span>
             </div>
             {isEditingName && !readOnly ? (
               <input autoFocus className="bg-transparent border-b-2 border-white text-4xl font-black outline-none w-full px-2" value={tempName} onChange={e => setTempName(e.target.value)} onBlur={handleSaveName} onKeyDown={e => e.key === 'Enter' && handleSaveName()} />
             ) : (
               <h2 className="text-4xl font-black" onClick={() => !readOnly && setIsEditingName(true)}>{dish.name} {!readOnly && <span className="text-xs opacity-50 ml-2">✎</span>}</h2>
             )}
           </div>
        </div>

        <div className="p-8">
          <p className="text-gray-500 italic text-lg mb-10 leading-relaxed border-l-4 border-orange-200 pl-4">“{dish.description}”</p>

          <div className="mb-10">
            <h3 className="text-xl font-black text-gray-800 mb-6 flex items-center gap-2">🛒 所需食材</h3>
            <div className="grid grid-cols-2 gap-3">
              {(dish.ingredients || []).map((ing, i) => (
                <div key={i} className="flex justify-between items-center p-4 bg-gray-50 rounded-2xl border border-gray-100">
                  <span className="font-bold text-gray-700 text-sm">{ing.name}</span>
                  <span className="text-orange-600 text-xs font-black">{ing.amount}</span>
                </div>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-xl font-black text-gray-800 mb-8 flex items-center gap-2">👨‍🍳 烹饪步骤</h3>
            <div className="space-y-10">
              {(dish.instructions || []).map((step, i) => (
                <div key={i} className="flex gap-6">
                  <div className="flex-shrink-0 w-8 h-8 rounded-full bg-orange-500 text-white flex items-center justify-center font-black text-xs">{i+1}</div>
                  <div className="flex-1 text-gray-700 leading-relaxed text-lg font-medium">{step.text}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      {loadingStatus && (
        <div className="fixed bottom-12 right-8 z-[200] bg-white/90 backdrop-blur px-4 py-3 rounded-2xl shadow-xl flex items-center gap-3 border border-orange-100">
           <div className="animate-spin h-4 w-4 border-2 border-orange-500 border-t-transparent rounded-full"></div>
           <span className="text-orange-600 text-xs font-black">{loadingStatus}</span>
        </div>
      )}
    </div>
  );
};

export default RecipeView;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error' | 'live'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });
  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // 共享库相关的状态
  const [remoteLibraryId, setRemoteLibraryId] = useState<string | null>(null);
  const [remoteDishes, setRemoteDishes] = useState<Dish[]>([]);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');

        // 检测 URL 分享参数 ?lib=USER_ID
        const params = new URLSearchParams(window.location.search);
        const libId = params.get('lib');
        if (libId) {
          setRemoteLibraryId(libId);
          setSyncStatus('live');
          storageService.subscribeToRemoteLibrary(libId, (newRemoteDishes) => {
            setRemoteDishes(newRemoteDishes.sort((a, b) => b.createdAt - a.createdAt));
            showToast("已连接到实时共享库", "success");
          });
        }
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };
    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev.filter(d => d.id !== dish.id)]);
      setSyncStatus('saved');
      showToast(`已成功保存 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("保存失败", 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;
    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("图片已刷新", "success");
    } catch (err) {
      setSyncStatus('error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);
    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));
      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {}
      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: details.instructions.map(step => ({ ...step, imageUrl: undefined })),
        imageUrl: coverUrl,
        createdAt: Date.now()
      };
      await addDish(newDish);
    } catch (err) {
      showToast(`${dishName} 生成失败`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", "success");
    } catch (e) {
      setSyncStatus('error');
    }
  };

  const removeDish = async (id: string) => {
    if (window.confirm("确定要删除这道菜谱吗？")) {
      try {
        setSyncStatus('syncing');
        await storageService.deleteDish(id);
        setDishes(prev => prev.filter(d => d.id !== id));
        setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
        setSyncStatus('saved');
        showToast("菜谱已删除", "success");
      } catch (e) {
        setSyncStatus('error');
      }
    }
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  // Move activeDishes definition here so it's accessible in both renderView and the return block
  const activeDishes = remoteLibraryId ? remoteDishes : dishes;

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="loader-ring"></div>
          <p className="mt-12 text-orange-500 font-bold">正在加载您的私人菜谱库...</p>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => activeDishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);
        return (
          <CollectionView 
            dishes={activeDishes} 
            pendingDishes={remoteLibraryId ? [] : pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onManualAdd={addDish}
            onDeleteDish={removeDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={(d) => setDishes(d)}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={(p) => { setPreferences(p); storageService.saveUserPreferences(p); }}
            onShowToast={showToast}
            isRemote={!!remoteLibraryId}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return <DiscoveryView onAddDish={addDish} onViewRecipe={viewRecipe} preferences={preferences} cache={discoveryCache} onUpdateCache={setDiscoveryCache} />;
      case 'recipe':
        const dish = activeDishes.find(d => d.id === selectedDishId);
        return dish ? <RecipeView dish={dish} onBack={() => setCurrentView('collection')} onUpdateDish={updateDish} readOnly={!!remoteLibraryId} /> : null;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-50 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <div className="flex items-center gap-3">
           <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => { window.location.search = ''; setCurrentView('collection'); }}>
             <span className="text-3xl">🍴</span> WhatToEat
           </h1>
           {remoteLibraryId && <span className="bg-white/20 px-2 py-0.5 rounded text-[10px] font-bold animate-pulse">LIVE 正在浏览</span>}
        </div>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button onClick={() => setCurrentView('collection')} className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}>我的菜谱</button>
          <button onClick={() => setCurrentView('discovery')} className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}>发现灵感</button>
          <button onClick={() => setCurrentView('suggest')} className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}>今天做什么？</button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24 relative">{renderView()}</main>

      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-400 text-xs border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2">
          {syncStatus === 'syncing' && <span className="flex items-center gap-1 text-orange-400 font-bold tracking-tight"><span className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-ping"></span>同步中</span>}
          {syncStatus === 'saved' && <span className="text-green-500 font-bold tracking-tight">✓ 已保存到本地</span>}
          {syncStatus === 'live' && <span className="text-indigo-500 font-bold tracking-tight">● 已实时连接共享库</span>}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>
      {/* Fix: Access activeDishes which is now in scope */}
      <GlobalChatBot currentDish={activeDishes.find(d => d.id === selectedDishId)} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Dish } from '../types';

interface DishCardProps {
  dish: Dish;
  onView: (id: string) => void;
  onDelete: (id: string) => void;
  onRefreshImage?: (id: string) => void;
}

const COMMON_INGREDIENTS = [
  '盐', '油', '醋', '糖', '酱油', '生抽', '老抽', '料酒', '葱', '姜', '蒜', '水', 
  '淀粉', '味精', '鸡精', '胡椒粉', '八角', '桂皮', '花椒', '芝麻油', '蚝油'
];

const DishCard: React.FC<DishCardProps> = ({ dish, onView, onDelete, onRefreshImage }) => {
  const [isRefreshing, setIsRefreshing] = useState(false);

  const handleRefresh = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!onRefreshImage || isRefreshing) return;
    setIsRefreshing(true);
    await onRefreshImage(dish.id);
    setIsRefreshing(false);
  };

  const mainIngredientTags = dish.ingredients
    ? dish.ingredients
        .filter(ing => !COMMON_INGREDIENTS.some(common => ing.name.includes(common)))
        .slice(0, 3)
    : [];

  const calculateTotalTime = () => {
    if (!Array.isArray(dish.instructions)) return 0;
    return dish.instructions.reduce((acc, step) => {
      if (typeof step === 'object' && step !== null && 'timeMinutes' in step) {
        return acc + (Number(step.timeMinutes) || 0);
      }
      if (typeof step === 'string') {
        return acc + 3;
      }
      return acc;
    }, 0);
  };

  const totalTime = calculateTotalTime();

  return (
    <div className="bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-500 flex flex-col group overflow-hidden relative">
      <div className="absolute top-0 left-0 w-1 group-hover:w-2 h-full bg-orange-500 opacity-70 group-hover:opacity-100 transition-all duration-500 z-10"></div>

      {/* 封面展示区 */}
      {dish.imageUrl && (
        <div className="relative h-40 overflow-hidden">
          <img 
            src={dish.imageUrl} 
            alt={dish.name} 
            className="w-full h-full object-cover group-hover:scale-110 transition duration-700"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent"></div>

          {/* 刷新小图标 */}
          <button 
            onClick={handleRefresh}
            className={`absolute top-3 right-3 p-2 rounded-full bg-white/20 backdrop-blur-md border border-white/30 text-white hover:bg-white/40 transition-all z-20 ${isRefreshing ? 'animate-spin' : ''}`}
            title="重新生成封面照"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            </svg>
          </button>
        </div>
      )}

      {/* Content area with z-20 to ensure it sits above the decorative strip */}
      <div className="p-5 pl-7 flex-1 flex flex-col relative z-20">
        <div className="flex justify-between items-start mb-3">
          <div className="flex flex-wrap gap-1.5">
            <span className="px-2.5 py-1 bg-orange-50 text-orange-600 text-[10px] font-black rounded-lg uppercase tracking-wider border border-orange-100">
              {dish.category}
            </span>
            {dish.dishType && (
              <span className="px-2.5 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black rounded-lg uppercase tracking-wider border border-emerald-100">
                {dish.dishType}
              </span>
            )}
          </div>
          <button 
            type="button"
            onClick={(e) => { e.stopPropagation(); onDelete(dish.id); }}
            className="text-gray-400 hover:text-red-500 hover:bg-red-100 transition-all p-3 rounded-full -mr-2 -mt-2"
            title="删除菜谱"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
          </button>
        </div>

        <div className="flex justify-between items-end mb-2">
          <h3 className="text-xl font-black text-gray-800 truncate pr-2 group-hover:text-orange-600 transition-colors">{dish.name}</h3>
          {totalTime > 0 && (
            <span className="flex-shrink-0 text-[11px] font-bold text-gray-400 bg-gray-50 px-2 py-1 rounded-lg border border-gray-100 flex items-center gap-1">
              <span className="text-orange-400 opacity-70">⏱</span> {totalTime}min
            </span>
          )}
        </div>

        <div className="flex flex-wrap gap-1.5 mb-4">
          {mainIngredientTags.map((ing, idx) => (
            <span key={idx} className="text-[10px] px-2 py-1 bg-blue-50/50 text-blue-500 rounded-md border border-blue-100 font-medium">
              {ing.name}
            </span>
          ))}
          {mainIngredientTags.length === 0 && (
             <span className="text-[10px] px-2 py-1 bg-gray-50 text-gray-400 rounded-md italic">经典风味</span>
          )}
        </div>

        <p className="text-gray-500 text-sm line-clamp-2 mb-5 leading-relaxed h-10 overflow-hidden">
          {dish.description}
        </p>

        <button 
          onClick={() => onView(dish.id)}
          className="mt-auto w-full py-3 bg-gray-50 text-orange-600 font-black rounded-2xl border border-orange-100 hover:bg-orange-500 hover:text-white hover:shadow-lg hover:shadow-orange-200 transition-all duration-300 transform active:scale-[0.98]"
        >
          查看制作秘籍
        </button>
      </div>
    </div>
  );
};

export default DishCard;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Custom Delete Modal State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "保存失败，请检查浏览器存储设置。";
      showToast(errorMsg, 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;

    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "更新失败，存储空间可能已满。";
      showToast(errorMsg, 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const requestDeleteDish = (id: string) => {
    setConfirmDeleteId(id);
  };

  const executeDeleteDish = async () => {
    if (!confirmDeleteId) return;
    const id = confirmDeleteId;

    try {
      setSyncStatus('syncing');
      await storageService.deleteDish(id);
      setDishes(prev => prev.filter(d => d.id !== id));
      setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
      setSyncStatus('saved');
      showToast("菜谱已删除", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("删除失败", 'error');
    } finally {
      setConfirmDeleteId(null);
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return (
          <DiscoveryView 
            onAddDish={addDish} 
            onViewRecipe={viewRecipe} 
            preferences={preferences} 
            cache={discoveryCache}
            onUpdateCache={setDiscoveryCache}
          />
        );
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-6 sticky top-0 z-30 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`px-4 py-2 rounded-full transition whitespace-nowrap text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 pb-24 relative z-0">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[80] animate-bounce-in">
           <div className={`px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {confirmDeleteId && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-sm shadow-2xl animate-in zoom-in duration-300">
            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center text-2xl mb-4 mx-auto">🗑️</div>
            <h3 className="text-xl font-bold text-center text-gray-800 mb-2">确认删除？</h3>
            <p className="text-gray-500 text-center text-sm mb-6">删除后将无法恢复该菜谱。</p>
            <div className="flex gap-3">
              <button onClick={() => setConfirmDeleteId(null)} className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition">取消</button>
              <button onClick={executeDeleteDish} className="flex-1 py-3 bg-red-500 text-white font-bold rounded-xl hover:bg-red-600 transition shadow-lg shadow-red-200">确认删除</button>
            </div>
          </div>
        </div>
      )}

      <footer className="p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Dish, InstructionStep, DishType, Category, Nutrition } from '../types';
import { geminiService } from '../services/geminiService';

interface RecipeViewProps {
  dish: Dish;
  onBack: () => void;
  onUpdateDish: (updatedDish: Dish) => void;
}

const RecipeView: React.FC<RecipeViewProps> = ({ dish, onBack, onUpdateDish }) => {
  const [isModifying, setIsModifying] = useState(false);
  const [instruction, setInstruction] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');

  const [isEditingName, setIsEditingName] = useState(false);
  const [tempName, setTempName] = useState(dish.name);

  const [isEditingType, setIsEditingType] = useState(false);
  const [isEditingCategory, setIsEditingCategory] = useState(false);

  useEffect(() => {
    setTempName(dish.name);
  }, [dish.name]);

  const handleSaveName = () => {
    const trimmed = tempName.trim();
    if (trimmed && trimmed !== dish.name) {
      onUpdateDish({ ...dish, name: trimmed });
    } else {
      setTempName(dish.name);
    }
    setIsEditingName(false);
  };

  const handleModify = async (customInstruction?: string) => {
    const finalInstruction = customInstruction || instruction;
    if (!finalInstruction.trim()) return;

    setLoading(true);
    setLoadingStatus('正在重构菜谱细节与营养分析...');
    try {
      const updatedDetails = await geminiService.modifyRecipe(dish, finalInstruction);

      const updatedDish: Dish = {
        ...dish,
        ...updatedDetails,
        instructions: updatedDetails.instructions.map((newStep, idx) => {
          const oldStep = dish.instructions[idx];
          return {
            ...newStep,
            imageUrl: oldStep && oldStep.text === newStep.text ? oldStep.imageUrl : undefined
          };
        })
      };
      onUpdateDish(updatedDish);
      setIsModifying(false);
      setInstruction('');
    } catch (err) {
      alert("调整失败，请重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const generateStepImage = async (index: number) => {
    const step = dish.instructions[index];
    setLoading(true);
    setLoadingStatus(`正在绘制步骤 ${index + 1} 的配图...`);
    try {
      const imageUrl = await geminiService.generateStepImage(step.text, dish.name);
      const newInstructions = [...dish.instructions];
      newInstructions[index] = { ...step, imageUrl };
      onUpdateDish({ ...dish, instructions: newInstructions });
    } catch (err) {
      alert("生成图片失败，请稍后重试。");
    } finally {
      setLoading(false);
      setLoadingStatus('');
    }
  };

  const instructions = Array.isArray(dish.instructions) ? dish.instructions : [];
  const totalTime = instructions.reduce((acc, step) => {
    if (typeof step === 'string') return acc + 5;
    return acc + (step.timeMinutes || 0);
  }, 0);

  return (
    <div className="max-w-3xl mx-auto animate-in fade-in duration-500 pb-20 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 sm:mb-6 gap-3 sm:gap-0">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 text-gray-500 hover:text-orange-500 font-medium transition text-sm sm:text-base"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
          </svg>
          返回收藏夹
        </button>

        <div className="flex gap-2 self-end sm:self-auto">
          <button 
            onClick={() => setIsModifying(!isModifying)}
            className={`px-4 py-2 rounded-full font-bold transition flex items-center gap-2 shadow-sm text-xs sm:text-sm ${isModifying ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600 border border-indigo-100 hover:bg-indigo-50'}`}
          >
            <span>✨</span> {isModifying ? '取消调整' : '调整菜谱'}
          </button>
        </div>
      </div>

      {isModifying && (
        <div className="mb-8 bg-indigo-50 rounded-3xl p-4 sm:p-6 border border-indigo-100 animate-in slide-in-from-top duration-300">
          <h4 className="text-indigo-900 font-bold mb-3 flex items-center gap-2 text-sm">
            你想如何调整这道菜？
          </h4>
          <div className="flex flex-wrap gap-2 mb-4 text-xs">
            {["精简食材", "低卡健康", "少油少盐", "让口味更辣", "增加蛋白质"].map((suggest) => (
              <button
                key={suggest}
                onClick={() => handleModify(suggest)}
                className="px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 font-bold rounded-full hover:bg-indigo-600 hover:text-white transition-colors"
              >
                {suggest}
              </button>
            ))}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="输入您的修改想法..."
              className="flex-1 px-4 py-3 rounded-xl border border-indigo-200 outline-none focus:ring-2 focus:ring-indigo-400 text-sm w-full"
              value={instruction}
              onChange={(e) => setInstruction(e.target.value)}
              disabled={loading}
            />
            <button 
              onClick={() => handleModify()}
              disabled={loading || !instruction.trim()}
              className="px-4 sm:px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition disabled:opacity-50 min-w-[60px] sm:min-w-[80px] text-sm whitespace-nowrap"
            >
              {loading ? '...' : '确认'}
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-100">
        <div className="aspect-video w-full bg-orange-100 relative flex items-center justify-center overflow-hidden">
           {dish.imageUrl ? (
             <img 
               src={dish.imageUrl} 
               alt={dish.name} 
               className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 hover:scale-110"
             />
           ) : (
             <span className="text-8xl filter drop-shadow-lg select-none">🍲</span>
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"></div>
           <div className="absolute bottom-4 sm:bottom-6 left-4 sm:left-8 text-white right-4 sm:right-8">
