               )}

               <span className="px-3 py-1 bg-gray-800/80 rounded-full text-[10px] font-bold shadow-lg flex items-center gap-1">
                 🕒 约 {totalTime} 分钟
               </span>
             </div>

             {isEditingName ? (
               <input 
                 autoFocus
