               >
                 {dish.name}
                 <span className="text-lg sm:text-xl opacity-0 group-hover:opacity-60 transition-opacity">✎</span>
               </h2>
             )}
           </div>
        </div>

        <div className="p-4 sm:p-6 md:p-8">
          <div className="mb-8 sm:mb-10">
            <h3 className="text-lg sm:text-xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3 mb-4">菜肴简介</h3>
