export default RecipeView;

import React, { useState, useEffect } from 'react';
import { geminiService } from '../services/geminiService';
import { Dish, SuggestedDish, UserPreferences } from '../types';

interface SuggestViewProps {
  onAddDish: (dish: Dish) => void;
  preferences: UserPreferences;
  onShowToast: (msg: string, type?: 'success' | 'error') => void;
}

const STORAGE_KEY = 'delicious-secrets-last-ingredients';
const STAPLES_KEY = 'delicious-secrets-staples';
const CUSTOM_STAPLES_KEY = 'delicious-secrets-custom-staples';

const DEFAULT_STAPLES = [
  '盐', '糖', '胡椒粉', '生抽', '老抽', '醋', '料酒', '蚝油', 
  '油', '淀粉', '葱', '姜', '蒜', '花椒', '八角', '辣椒粉'
];

const SuggestView: React.FC<SuggestViewProps> = ({ onAddDish, preferences, onShowToast }) => {
  const [inputValue, setInputValue] = useState('');
  const [newStapleInput, setNewStapleInput] = useState('');
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [staples, setStaples] = useState<string[]>([]);
  const [customStaples, setCustomStaples] = useState<string[]>([]);
  const [showPantry, setShowPantry] = useState(false);
  const [suggestions, setSuggestions] = useState<SuggestedDish[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingDish, setSavingDish] = useState<string | null>(null);

  useEffect(() => {
    const savedIngs = localStorage.getItem(STORAGE_KEY);
    if (savedIngs) { try { const parsed = JSON.parse(savedIngs); if (Array.isArray(parsed)) setIngredients(parsed); } catch (e) {} }
    const savedCustom = localStorage.getItem(CUSTOM_STAPLES_KEY);
    if (savedCustom) { try { const parsed = JSON.parse(savedCustom); if (Array.isArray(parsed)) setCustomStaples(parsed); } catch (e) {} }
    const savedStaples = localStorage.getItem(STAPLES_KEY);
    if (savedStaples) { try { const parsed = JSON.parse(savedStaples); if (Array.isArray(parsed)) setStaples(parsed); } catch (e) {} } else { setStaples(DEFAULT_STAPLES); }
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem(STAPLES_KEY, JSON.stringify(staples)); }, [staples]);
  useEffect(() => { localStorage.setItem(CUSTOM_STAPLES_KEY, JSON.stringify(customStaples)); }, [customStaples]);

  const toggleStaple = (item: string) => { setStaples(prev => prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]); };
  const handleAddCustomStaple = (e: React.FormEvent) => { e.preventDefault(); const val = newStapleInput.trim(); if (val && !DEFAULT_STAPLES.includes(val) && !customStaples.includes(val)) { setCustomStaples([...customStaples, val]); setStaples([...staples, val]); setNewStapleInput(''); } };
  const removeCustomStaple = (val: string) => { setCustomStaples(prev => prev.filter(i => i !== val)); setStaples(prev => prev.filter(i => i !== val)); };
  const handleAddIngredient = (e: React.FormEvent) => { e.preventDefault(); if (inputValue.trim() && !ingredients.includes(inputValue.trim())) { setIngredients([...ingredients, inputValue.trim()]); setInputValue(''); } };

  const fetchSuggestions = async () => {
    if (ingredients.length === 0) return;
    setLoading(true);
    try {
      const res = await geminiService.suggestDishes(ingredients, staples, preferences);
      setSuggestions(res);
    } catch (err) {
      onShowToast("推荐失败，请重试。", 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveToCollection = async (suggested: SuggestedDish) => {
    setSavingDish(suggested.name);
    try {
      const details = await geminiService.getRecipeDetails(suggested.name, preferences);
      let imageUrl = '';
      try { imageUrl = await geminiService.generateDishImage(suggested.name); } catch (e) {}
      const newDish: Dish = { id: Date.now().toString(), name: suggested.name, ...details, instructions: details.instructions.map(s => ({ ...s, imageUrl: undefined })), imageUrl, createdAt: Date.now() };
      onAddDish(newDish);
    } catch (err) {
      onShowToast("保存失败", 'error');
    } finally {
      setSavingDish(null);
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-in slide-in-from-bottom duration-500 pb-12">
      <div className="bg-gradient-to-br from-orange-400 to-red-500 rounded-[2rem] sm:rounded-[2.5rem] p-6 sm:p-8 text-white mb-6 shadow-2xl relative overflow-hidden">
        <h2 className="text-2xl sm:text-3xl font-black mb-3 sm:mb-4">今天做什么？</h2>
        <p className="opacity-90 mb-6 sm:mb-8 text-sm md:text-base">告诉我你手头的关键食材，AI 将为您量身定制大餐。</p>
        <form onSubmit={handleAddIngredient} className="relative mb-6 sm:mb-8">
          <input 
            type="text" 
            placeholder="输入主要食材（如：鸡蛋、牛肉）" 
            className="w-full px-4 sm:px-6 py-4 sm:py-5 rounded-2xl text-gray-800 outline-none pr-24 text-base sm:text-lg shadow-inner" 
            value={inputValue} 
            onChange={(e) => setInputValue(e.target.value)} 
          />
          <button type="submit" className="absolute right-2 top-2 bottom-2 px-4 sm:px-6 bg-orange-600 hover:bg-orange-700 rounded-xl font-bold transition-all shadow-md active:scale-95 text-sm sm:text-base">添加</button>
        </form>
        <div className="flex flex-wrap gap-2 items-center min-h-[40px]">
          {ingredients.map(ing => (
            <span key={ing} className="bg-white/20 backdrop-blur-md px-3 sm:px-4 py-2 rounded-full flex items-center gap-2 border border-white/30 text-xs font-bold transition-all hover:bg-white/40 group">
              {ing}
              <button onClick={() => setIngredients(ingredients.filter(i => i !== ing))} className="hover:text-red-200 opacity-50 group-hover:opacity-100">✕</button>
            </span>
          ))}
        </div>
      </div>

      <div className="mb-8 sm:mb-10 bg-white border border-gray-100 rounded-3xl p-5 sm:p-6 shadow-sm">
        <button onClick={() => setShowPantry(!showPantry)} className="w-full flex justify-between items-center text-gray-700 hover:text-orange-500 transition-colors">
          <div className="flex items-center gap-3">🧂<span className="font-black text-sm uppercase tracking-widest">我的厨房常备库</span></div>
          <svg className={`w-5 h-5 transition-transform ${showPantry ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
        </button>
        {showPantry && (
          <div className="mt-6 animate-in slide-in-from-top duration-300">
            <div className="flex flex-wrap gap-2 mb-6">
              {DEFAULT_STAPLES.concat(customStaples).map(item => (
                <button key={item} onClick={() => toggleStaple(item)} className={`px-3 py-2 rounded-xl text-[11px] font-bold transition-all border ${staples.includes(item) ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-gray-50 border-gray-100 text-gray-400'}`}>{item}</button>
              ))}
            </div>
            <form onSubmit={handleAddCustomStaple} className="flex gap-2 max-w-sm">
              <input type="text" placeholder="添加自定义食材..." className="flex-1 bg-gray-50 border border-gray-100 px-4 py-2 rounded-xl text-[11px] outline-none w-full" value={newStapleInput} onChange={(e) => setNewStapleInput(e.target.value)} />
              <button type="submit" disabled={!newStapleInput.trim()} className="bg-indigo-500 text-white px-4 py-2 rounded-xl text-[11px] font-bold whitespace-nowrap">添加</button>
            </form>
          </div>
        )}
      </div>

      <div className="text-center mb-10 sm:mb-12">
        <button onClick={fetchSuggestions} disabled={ingredients.length === 0 || loading} className="w-full sm:w-auto bg-orange-600 hover:bg-orange-700 text-white text-lg sm:text-xl font-black px-8 sm:px-12 py-4 sm:py-5 rounded-2xl shadow-xl transition transform hover:scale-105 active:scale-95 disabled:opacity-50">
          {loading ? '构思中...' : '💡 看看能做什么？'}
        </button>
      </div>

      {suggestions.length > 0 && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="flex items-center gap-3 mb-6"><h3 className="text-xl font-black text-gray-800">推荐方案</h3><div className="h-px flex-1 bg-gray-100"></div></div>
          {suggestions.map((s, idx) => (
            <div key={idx} className="bg-white border border-gray-100 rounded-[2rem] p-6 sm:p-8 shadow-sm hover:shadow-xl transition-all flex flex-col md:flex-row justify-between items-start md:items-center gap-6 group">
              <div className="flex-1">
                <div className="flex flex-wrap items-center gap-2 mb-3"><h4 className="text-2xl font-black text-gray-800 group-hover:text-orange-600">{s.name}</h4><span className="px-3 py-1 bg-orange-50 text-orange-600 text-[10px] rounded-lg font-black">{s.category}</span></div>
                <p className="text-gray-500 italic text-sm mb-4">"{s.reason}"</p>
              </div>
              <button onClick={() => handleSaveToCollection(s)} disabled={savingDish === s.name} className="w-full md:w-auto whitespace-nowrap bg-gray-50 text-orange-600 font-black px-6 sm:px-8 py-3 sm:py-4 rounded-2xl hover:bg-orange-500 hover:text-white transition-all shadow-sm">
                {savingDish === s.name ? '正在收藏...' : '⭐ 立即收藏'}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SuggestView;

import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, UserPreferences } from '../types';
import DishCard from '../components/DishCard';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  pendingDishes: {id: string, name: string, status: string}[];
  recentlyViewedDishes: Dish[];
  onGenerateInBackground: (name: string) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
  onRefreshImage?: (id: string) => void;
  preferences: UserPreferences;
  onUpdatePreferences: (prefs: UserPreferences) => void;
  onShowToast: (msg: string, type?: 'success' | 'error') => void;
}

const FLAVORS = ['辣', '甜', '咸', '淡', '酸', '苦', '麻', '鲜', '脆', '香'];

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  pendingDishes,
  recentlyViewedDishes,
  onGenerateInBackground, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate,
  onRefreshImage,
  preferences,
  onUpdatePreferences,
  onShowToast
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchByIngredients, setSearchByIngredients] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [customPrefInput, setCustomPrefInput] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const name = newDishName.trim();
    if (!name) return;

    onGenerateInBackground(name);
    setNewDishName('');
    setIsAdding(false);
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleAddCustomPref = (e: React.FormEvent) => {
    e.preventDefault();
    const val = customPrefInput.trim();
    if (val && !preferences.flavors.includes(val)) {
      onUpdatePreferences({ ...preferences, flavors: [...preferences.flavors, val] });
      setCustomPrefInput('');
    }
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      onShowToast("菜谱备份已导出", 'success');
    } catch (e) {
      onShowToast("导出失败", 'error');
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
        onShowToast("导入成功！已同步您的菜谱库。", 'success');
      } catch (err) {
        onShowToast(err instanceof Error ? err.message : "导入失败", 'error');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 - 隐藏在超小屏幕上或调整位置 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-4 sm:left-6 bottom-6 sm:bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-60 sm:w-64 animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               </div>
               <div className="space-y-2 max-h-60 sm:max-h-80 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div key={dish.id} onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }} className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group">
                     <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" /> : <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>}
                     </div>
                     <div className="flex-1 min-w-0">
                       <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                       <p className="text-[10px] text-gray-400">{dish.category}</p>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button onClick={() => setIsRecentOpen(!isRecentOpen)} className={`w-12 h-12 sm:w-14 sm:h-14 rounded-full shadow-2xl flex items-center justify-center text-xl sm:text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}>
            {isRecentOpen ? <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg> : <span className="relative">🕒</span>}
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800 border-l-4 border-orange-500 pl-3">我的菜谱库</h2>
        <div className="flex gap-2 w-full md:w-auto">
          <button onClick={() => setIsPrefsOpen(!isPrefsOpen)} className={`w-10 h-10 rounded-full font-bold transition flex items-center justify-center border shadow-sm flex-shrink-0 ${isPrefsOpen ? 'bg-indigo-500 text-white border-indigo-200 shadow-lg' : 'bg-white text-indigo-600 border-indigo-100 hover:bg-indigo-50'}`} title="偏好设置"><span>⚙️</span></button>
          <div className="flex bg-gray-100 p-1 rounded-full border border-gray-200 shadow-sm">
             <button onClick={handleExport} title="导出备份" className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg></button>
             <button onClick={() => fileInputRef.current?.click()} title="导入备份" className="p-2 hover:bg-white rounded-full transition text-gray-600 hover:text-orange-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg></button>
             <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </div>
          <button onClick={() => setIsAdding(true)} className="flex-1 md:flex-none bg-orange-500 hover:bg-orange-600 text-white px-4 md:px-6 py-2 rounded-full font-bold transition flex items-center justify-center gap-2 shadow-lg shadow-orange-100 whitespace-nowrap"><span>➕</span> <span className="hidden sm:inline">添加新菜肴</span><span className="sm:hidden">添加</span></button>
        </div>
      </div>

      {isPrefsOpen && (
        <div className="bg-indigo-50 rounded-3xl p-4 sm:p-6 border border-indigo-100 animate-in slide-in-from-top duration-300 space-y-4">
           <div>
              <h3 className="text-sm font-black text-indigo-900 mb-3 flex items-center gap-2">常用口味</h3>
              <div className="flex flex-wrap gap-2">
                {FLAVORS.map(flavor => (
                  <button key={flavor} onClick={() => toggleFlavor(flavor)} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${preferences.flavors.includes(flavor) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-indigo-400 border-indigo-100'}`}>
                    {flavor}
                  </button>
                ))}
              </div>
           </div>

           <div>
              <h3 className="text-sm font-black text-indigo-900 mb-3 flex items-center gap-2">自定义偏好 / 忌口</h3>
              <div className="flex flex-wrap gap-2 mb-3">
                {preferences.flavors.filter(f => !FLAVORS.includes(f)).map(custom => (
                  <span key={custom} className="px-3 py-1.5 rounded-xl text-xs font-bold bg-white text-indigo-600 border border-indigo-200 flex items-center gap-2 shadow-sm">
                    {custom}
                    <button onClick={() => toggleFlavor(custom)} className="hover:text-red-500 transition-colors">
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </span>
                ))}
              </div>
              <form onSubmit={handleAddCustomPref} className="flex gap-2">
                <input 
                  type="text" 
                  placeholder="例如：忌口洋葱、少油、低脂..." 
                  className="flex-1 px-4 py-2 rounded-xl border border-indigo-100 outline-none focus:ring-2 focus:ring-indigo-400 text-sm bg-white/50 w-full"
                  value={customPrefInput}
                  onChange={(e) => setCustomPrefInput(e.target.value)}
                />
                <button type="submit" disabled={!customPrefInput.trim()} className="px-4 py-2 bg-indigo-500 text-white text-sm font-bold rounded-xl hover:bg-indigo-600 disabled:opacity-50 transition-colors whitespace-nowrap">
                  添加
                </button>
              </form>
           </div>
        </div>
      )}

      <div className="space-y-4">
        {/* 搜索栏 */}
        <div className="relative">
          <input type="text" placeholder={searchByIngredients ? "输入食材名进行搜索..." : "输入菜名进行搜索..."} className="w-full pl-10 pr-4 py-3 rounded-2xl border border-gray-200 focus:ring-2 focus:ring-orange-400 outline-none transition shadow-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* 筛选标签栏 */}
        <div className="space-y-3">
          <div className="flex overflow-x-auto scrollbar-hide gap-2 pb-1">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`flex-shrink-0 px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-400' : 'bg-white text-gray-500 border-gray-100 hover:border-orange-200'}`}
              >
                {cat}
              </button>
            ))}
          </div>
          <div className="flex overflow-x-auto scrollbar-hide gap-2 pb-1">
            {dishTypes.map(type => (
              <button
                key={type}
                onClick={() => setSelectedDishType(type)}
                className={`flex-shrink-0 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all border ${selectedDishType === type ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-white text-gray-400 border-gray-100 hover:border-emerald-200'}`}
              >
                {type}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-4 px-1">
          <label className="flex items-center gap-2 cursor-pointer group">
            <input type="checkbox" className="hidden peer" checked={searchByIngredients} onChange={() => setSearchByIngredients(!searchByIngredients)} />
            <div className="w-4 h-4 rounded border-2 border-gray-300 peer-checked:bg-orange-500 peer-checked:border-orange-500 transition-all flex items-center justify-center"><svg className="w-3 h-3 text-white opacity-0 peer-checked:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg></div>
            <span className="text-xs font-bold text-gray-500 group-hover:text-orange-500 transition-colors">🥕 同时搜索食材</span>
          </label>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 sm:p-8 w-full max-w-md shadow-2xl animate-in zoom-in duration-300">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">告诉我你想吃的菜</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input autoFocus type="text" placeholder="例如：红烧肉、麻辣香锅..." className="w-full px-4 py-4 rounded-xl border border-gray-200 text-lg outline-none focus:ring-2 focus:ring-orange-400" value={newDishName} onChange={(e) => setNewDishName(e.target.value)} />
              <p className="text-sm text-gray-500">点击添加后，AI 将在后台为您制定配方。</p>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsAdding(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-100 rounded-xl transition">取消</button>
                <button type="submit" disabled={!newDishName.trim()} className="flex-1 py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 transition shadow-lg disabled:opacity-50">立即添加</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {pendingDishes.map(pending => (
          <div key={pending.id} className="bg-white border-2 border-dashed border-orange-100 rounded-3xl p-6 flex flex-col justify-between h-[210px] animate-pulse-soft">
             <div>
               <div className="flex justify-between items-start mb-4">
                 <div className="w-16 h-6 skeleton rounded-lg"></div>
                 <div className="w-5 h-5 rounded-full border-2 border-orange-400 border-t-transparent animate-spin"></div>
               </div>
               <h3 className="text-xl font-black text-gray-300 mb-2 truncate">{pending.name}</h3>
               <p className="text-orange-400 text-xs font-bold italic">{pending.status}</p>
             </div>
             <div className="w-full h-11 skeleton rounded-2xl opacity-40"></div>
          </div>
        ))}

        {filteredDishes.length > 0 ? (
          filteredDishes.map(dish => <DishCard key={dish.id} dish={dish} onView={onViewRecipe} onDelete={onDeleteDish} onRefreshImage={onRefreshImage} />)
        ) : pendingDishes.length === 0 ? (
          <div className="col-span-full text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            <p className="text-gray-400 text-lg">暂无匹配的菜谱</p>
          </div>
        ) : null}
      </div>
    </div>
  );
};

export default CollectionView;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Custom Delete Modal State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "保存失败，请检查浏览器存储设置。";
      showToast(errorMsg, 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;

    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "更新失败，存储空间可能已满。";
      showToast(errorMsg, 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const requestDeleteDish = (id: string) => {
    setConfirmDeleteId(id);
  };

  const executeDeleteDish = async () => {
    if (!confirmDeleteId) return;
    const id = confirmDeleteId;

    try {
      setSyncStatus('syncing');
      await storageService.deleteDish(id);
      setDishes(prev => prev.filter(d => d.id !== id));
      setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
      setSyncStatus('saved');
      showToast("菜谱已删除", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("删除失败", 'error');
    } finally {
      setConfirmDeleteId(null);
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return (
          <DiscoveryView 
            onAddDish={addDish} 
            onViewRecipe={viewRecipe} 
            preferences={preferences} 
            cache={discoveryCache}
            onUpdateCache={setDiscoveryCache}
          />
        );
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col max-w-4xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-4 sm:p-6 sticky top-0 z-30 flex flex-col md:flex-row gap-4 justify-between items-center shadow-md">
        <h1 className="text-xl sm:text-2xl font-bold flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView('collection')}>
          <span className="text-2xl sm:text-3xl">🍴</span>
          WhatToEat｜吃了么
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide w-full md:w-auto pb-1 md:pb-0">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 sm:p-6 md:p-8 pb-24 relative z-0">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[80] animate-bounce-in w-max max-w-[90vw]">
           <div className={`px-4 sm:px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-xs sm:text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {confirmDeleteId && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 sm:p-8 w-full max-w-sm shadow-2xl animate-in zoom-in duration-300">
            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center text-2xl mb-4 mx-auto">🗑️</div>
            <h3 className="text-xl font-bold text-center text-gray-800 mb-2">确认删除？</h3>
            <p className="text-gray-500 text-center text-sm mb-6">删除后将无法恢复该菜谱。</p>
            <div className="flex gap-3">
              <button onClick={() => setConfirmDeleteId(null)} className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition">取消</button>
              <button onClick={executeDeleteDish} className="flex-1 py-3 bg-red-500 text-white font-bold rounded-xl hover:bg-red-600 transition shadow-lg shadow-red-200">确认删除</button>
            </div>
          </div>
        </div>
      )}

      <footer className="p-4 sm:p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex flex-col sm:flex-row items-center justify-between gap-2">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Custom Delete Modal State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();
        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "保存失败，请检查浏览器存储设置。";
      showToast(errorMsg, 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;

    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "更新失败，存储空间可能已满。";
      showToast(errorMsg, 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const requestDeleteDish = (id: string) => {
    setConfirmDeleteId(id);
  };

  const executeDeleteDish = async () => {
    if (!confirmDeleteId) return;
    const id = confirmDeleteId;

    try {
      setSyncStatus('syncing');
      await storageService.deleteDish(id);
      setDishes(prev => prev.filter(d => d.id !== id));
      setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
      setSyncStatus('saved');
      showToast("菜谱已删除", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("删除失败", 'error');
    } finally {
      setConfirmDeleteId(null);
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return (
          <DiscoveryView 
            onAddDish={addDish} 
            onViewRecipe={viewRecipe} 
            preferences={preferences} 
            cache={discoveryCache}
            onUpdateCache={setDiscoveryCache}
          />
        );
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col w-full max-w-7xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-4 sm:p-6 sticky top-0 z-30 flex flex-wrap gap-4 justify-between items-center shadow-md">
        <h1 className="text-xl sm:text-2xl font-bold flex items-center gap-2 cursor-pointer whitespace-nowrap" onClick={() => setCurrentView('collection')}>
          <span className="text-2xl sm:text-3xl">🍴</span>
          WhatToEat
        </h1>
        <div className="flex gap-2 overflow-x-auto max-w-full scrollbar-hide pb-1 sm:pb-0">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            我的菜谱
          </button>
          <button 
            onClick={() => setCurrentView('discovery')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            发现灵感
          </button>
          <button 
            onClick={() => setCurrentView('suggest')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
            今天做什么？
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 sm:p-6 md:p-8 pb-24 relative z-0 w-full">
        {renderView()}
      </main>

      {/* Global Toast */}
      {toast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[80] animate-bounce-in w-max max-w-[90vw]">
           <div className={`px-4 sm:px-6 py-3 rounded-2xl shadow-xl flex items-center gap-3 border ${toast.type === 'success' ? 'toast-success' : 'bg-red-600 border-red-500 text-white'}`}>
              <span className="text-lg">{toast.type === 'success' ? '✨' : '❌'}</span>
              <span className="font-bold text-xs sm:text-sm whitespace-nowrap">{toast.message}</span>
           </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {confirmDeleteId && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 sm:p-8 w-full max-w-sm shadow-2xl animate-in zoom-in duration-300">
            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center text-2xl mb-4 mx-auto">🗑️</div>
            <h3 className="text-xl font-bold text-center text-gray-800 mb-2">确认删除？</h3>
            <p className="text-gray-500 text-center text-sm mb-6">删除后将无法恢复该菜谱。</p>
            <div className="flex gap-3">
              <button onClick={() => setConfirmDeleteId(null)} className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition">取消</button>
              <button onClick={executeDeleteDish} className="flex-1 py-3 bg-red-500 text-white font-bold rounded-xl hover:bg-red-600 transition shadow-lg shadow-red-200">确认删除</button>
            </div>
          </div>
        </div>
      )}

      <footer className="p-4 sm:p-6 text-center text-gray-500 text-sm border-t border-gray-100 bg-gray-50 flex flex-col sm:flex-row items-center justify-between gap-2">
        <div className="flex items-center gap-2 text-xs font-medium">
          {syncStatus === 'syncing' && (
            <span className="flex items-center gap-1 text-orange-500">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></span>
              同步中...
            </span>
          )}
          {syncStatus === 'saved' && (
            <span className="flex items-center gap-1 text-green-600">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
              已保存到本地
            </span>
          )}
        </div>
        <div>© {new Date().getFullYear()} WhatToEat｜吃了么</div>
      </footer>

      <GlobalChatBot currentDish={currentView === 'recipe' ? dishes.find(d => d.id === selectedDishId) : undefined} preferences={preferences} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Category, Dish, DishType, UserPreferences } from '../types';
import DishCard from '../components/DishCard';
import { storageService } from '../services/storageService';

interface CollectionViewProps {
  dishes: Dish[];
  pendingDishes: {id: string, name: string, status: string}[];
  recentlyViewedDishes: Dish[];
  onGenerateInBackground: (name: string) => void;
  onDeleteDish: (id: string) => void;
  onViewRecipe: (id: string) => void;
  onBulkUpdate: (dishes: Dish[]) => void;
  onRefreshImage?: (id: string) => void;
  preferences: UserPreferences;
  onUpdatePreferences: (prefs: UserPreferences) => void;
  onShowToast: (msg: string, type?: 'success' | 'error') => void;
}

const FLAVORS = ['辣', '甜', '咸', '淡', '酸', '苦', '麻', '鲜', '脆', '香'];

const CollectionView: React.FC<CollectionViewProps> = ({ 
  dishes, 
  pendingDishes,
  recentlyViewedDishes,
  onGenerateInBackground, 
  onDeleteDish, 
  onViewRecipe, 
  onBulkUpdate,
  onRefreshImage,
  preferences,
  onUpdatePreferences,
  onShowToast
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchByIngredients, setSearchByIngredients] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [selectedDishType, setSelectedDishType] = useState<string>('全部');
  const [newDishName, setNewDishName] = useState('');
  const [customPrefInput, setCustomPrefInput] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isRecentOpen, setIsRecentOpen] = useState(false);
  const [isPrefsOpen, setIsPrefsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const categories = ['全部', ...Object.values(Category)];
  const dishTypes = ['全部', ...Object.values(DishType)];

  const filteredDishes = dishes.filter(dish => {
    const searchLower = searchTerm.toLowerCase();
    const matchesName = dish.name.toLowerCase().includes(searchLower);
    const matchesIngredients = searchByIngredients && dish.ingredients?.some(ing => 
      ing.name.toLowerCase().includes(searchLower)
    );

    const matchesSearch = matchesName || matchesIngredients;
    const matchesCategory = selectedCategory === '全部' || dish.category === selectedCategory;
    const matchesType = selectedDishType === '全部' || dish.dishType === selectedDishType;
    return matchesSearch && matchesCategory && matchesType;
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const name = newDishName.trim();
    if (!name) return;

    onGenerateInBackground(name);
    setNewDishName('');
    setIsAdding(false);
  };

  const toggleFlavor = (flavor: string) => {
    const newFlavors = preferences.flavors.includes(flavor)
      ? preferences.flavors.filter(f => f !== flavor)
      : [...preferences.flavors, flavor];
    onUpdatePreferences({ ...preferences, flavors: newFlavors });
  };

  const handleAddCustomPref = (e: React.FormEvent) => {
    e.preventDefault();
    const val = customPrefInput.trim();
    if (val && !preferences.flavors.includes(val)) {
      onUpdatePreferences({ ...preferences, flavors: [...preferences.flavors, val] });
      setCustomPrefInput('');
    }
  };

  const handleExport = async () => {
    try {
      const data = await storageService.exportData();
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `WhatToEat备份_${new Date().toLocaleDateString()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      onShowToast("菜谱备份已导出", 'success');
    } catch (e) {
      onShowToast("导出失败", 'error');
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = event.target?.result as string;
        const updatedDishes = await storageService.importData(json);
        onBulkUpdate(updatedDishes);
        onShowToast("导入成功！已同步您的菜谱库。", 'success');
      } catch (err) {
        onShowToast(err instanceof Error ? err.message : "导入失败", 'error');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 relative">

      {/* 悬浮最近查看入口 */}
      {recentlyViewedDishes.length > 0 && (
        <div className="fixed left-4 sm:left-6 bottom-6 sm:bottom-8 z-40 flex flex-col items-start">
          {isRecentOpen && (
            <div className="mb-4 bg-white/95 backdrop-blur-md rounded-3xl shadow-2xl border border-gray-100 p-4 w-[calc(100vw-2rem)] max-w-xs animate-in slide-in-from-bottom duration-300">
               <div className="flex justify-between items-center mb-4 px-2">
                 <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                    最近查看
                 </h3>
                 <button onClick={() => setIsRecentOpen(false)} className="text-gray-400 hover:text-orange-500">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               </div>
               <div className="space-y-2 max-h-60 overflow-y-auto scrollbar-hide">
                 {recentlyViewedDishes.map(dish => (
                   <div key={dish.id} onClick={() => { onViewRecipe(dish.id); setIsRecentOpen(false); }} className="flex items-center gap-3 p-2 hover:bg-orange-50 rounded-xl transition cursor-pointer group">
                     <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                        {dish.imageUrl ? <img src={dish.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition duration-300" alt="" /> : <div className="w-full h-full flex items-center justify-center text-lg bg-orange-50">🍲</div>}
                     </div>
                     <div className="flex-1 min-w-0">
                       <p className="text-xs font-bold text-gray-800 truncate">{dish.name}</p>
                       <p className="text-[10px] text-gray-400">{dish.category}</p>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
          <button onClick={() => setIsRecentOpen(!isRecentOpen)} className={`w-12 h-12 sm:w-14 sm:h-14 rounded-full shadow-2xl flex items-center justify-center text-xl sm:text-2xl transition-all transform hover:scale-110 active:scale-95 border-4 ${isRecentOpen ? 'bg-orange-500 text-white border-orange-100' : 'bg-white text-orange-500 border-orange-50'}`}>
            {isRecentOpen ? <svg className="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg> : <span className="relative">🕒</span>}
          </button>
        </div>
      )}

