import { Dish, UserPreferences } from "../types";

const DB_NAME = "WhatToEatDB";
const OLD_DB_NAME = "DeliciousSecretsDB";
const STORE_NAME = "dishes";
const DB_VERSION = 1;
const RECENTLY_VIEWED_KEY = "recently-viewed-ids";
const PREFERENCES_KEY = "user-preferences";
const MAX_RECENT = 5;

// Cloud Sync Configuration
const CLOUD_API_BASE = "https://jsonblob.com/api/jsonBlob";
const CLOUD_ID_KEY = "whattoeat-cloud-id";

export class StorageService {
  private db: IDBDatabase | null = null;
  private initPromise: Promise<void> | null = null;
  private cloudKitchenId: string | null = null;

  constructor() {
    this.cloudKitchenId = localStorage.getItem(CLOUD_ID_KEY);
  }

  /**
   * Cloud Sync Methods
   */
  getCloudId(): string | null {
    return this.cloudKitchenId;
  }

  async createCloudKitchen(initialDishes: Dish[]): Promise<string> {
    try {
      const response = await fetch(CLOUD_API_BASE, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(initialDishes)
      });

      if (!response.ok) throw new Error("无法连接到云端服务器");

      const location = response.headers.get('Location');
      if (!location) throw new Error("创建失败：无法获取云端ID");

      const id = location.split('/').pop();
      if (!id) throw new Error("ID 解析失败");

      this.setCloudId(id);
      return id;
    } catch (e) {
      console.error(e);
      throw e;
    }
  }

  async joinCloudKitchen(id: string): Promise<void> {
    try {
      const response = await fetch(`${CLOUD_API_BASE}/${id}`);
      if (!response.ok) throw new Error("无效的厨房ID或网络错误");
      // Validate data structure lightly
      const data = await response.json();
      if (!Array.isArray(data)) throw new Error("该ID对应的数据不是有效的菜谱库");

      this.setCloudId(id);
    } catch (e) {
      throw e;
    }
  }

  leaveCloudKitchen() {
    this.cloudKitchenId = null;
    localStorage.removeItem(CLOUD_ID_KEY);
  }

  private setCloudId(id: string) {
    this.cloudKitchenId = id;
    localStorage.setItem(CLOUD_ID_KEY, id);
  }

  /**
   * 初始化数据库 - 采用单例 Promise 模式，防止并发冲突
   */
  async init(): Promise<void> {
    if (this.db) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      // 尝试静默迁移旧数据（不阻塞主逻辑）
      try {
        await this.tryMigrateFromOldDB();
      } catch (e) {
        console.warn("旧数据库迁移失败，跳过...", e);
      }

      return new Promise((resolve, reject) => {
        if (!window.indexedDB) {
          return reject("您的浏览器不支持本地数据库，请更换现代浏览器。");
        }

        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
          console.error("IndexedDB 开启失败:", event);
          this.initPromise = null; // 允许下次重试
          reject("无法打开本地存储。如果是无痕模式，请尝试正常模式访问。");
        };

        request.onsuccess = (event) => {
          this.db = (event.target as IDBOpenDBRequest).result;

          this.db.onversionchange = () => {
            this.db?.close();
            window.location.reload();
          };

          resolve();
        };

        request.onupgradeneeded = (event) => {
          const db = (event.target as IDBOpenDBRequest).result;
          if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: "id" });
          }
        };
      });
    })();

    return this.initPromise;
  }

  private async tryMigrateFromOldDB(): Promise<void> {
    return new Promise((resolve) => {
      // 仅仅是尝试开启，如果不成功或不存在则直接 resolve
      const request = indexedDB.open(OLD_DB_NAME);
      request.onsuccess = (event) => {
        const oldDb = (event.target as IDBOpenDBRequest).result;
        if (oldDb.objectStoreNames.contains(STORE_NAME)) {
          const transaction = oldDb.transaction([STORE_NAME], "readonly");
          const store = transaction.objectStore(STORE_NAME);
          const allDataRequest = store.getAll();

          allDataRequest.onsuccess = () => {
            // 这里只是检测，真正的迁移目前在 initApp 逻辑中处理
            oldDb.close();
            resolve();
          };
          allDataRequest.onerror = () => {
            oldDb.close();
            resolve();
          };
        } else {
          oldDb.close();
          resolve();
        }
      };
      request.onerror = () => resolve();
    });
  }

  async getAllDishes(): Promise<Dish[]> {
    // Mode Check: Cloud
    if (this.cloudKitchenId) {
      try {
        const response = await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`);
        if (!response.ok) {
           if (response.status === 404) {
             // ID失效
             this.leaveCloudKitchen();
             throw new Error("云端厨房ID已失效，已切换回本地模式。");
           }
           throw new Error("网络连接失败");
        }
        const data = await response.json();
        return Array.isArray(data) ? data : [];
      } catch (e) {
        throw e;
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readonly");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject("读取数据失败");
      } catch (e) {
        reject(e);
      }
    });
  }

  async saveDish(dish: Dish): Promise<void> {
    // Mode Check: Cloud
    if (this.cloudKitchenId) {
      const currentDishes = await this.getAllDishes();
      const index = currentDishes.findIndex(d => d.id === dish.id);
      if (index >= 0) {
        currentDishes[index] = dish;
      } else {
        currentDishes.push(dish);
      }

      await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(currentDishes)
      });
      return;
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readwrite");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.put(dish);

        request.onsuccess = () => resolve();
        request.onerror = (event) => {
          const error = (event.target as any).error;
          if (error && error.name === 'QuotaExceededError') {
            reject("存储空间已满。请删除一些不需要的菜谱或清理浏览器缓存。");
          } else {
            reject("保存失败，请稍后重试。");
          }
        };
      } catch (e) {
        reject(e);
      }
    });
  }

  async deleteDish(id: string): Promise<void> {
    // Mode Check: Cloud
    if (this.cloudKitchenId) {
      const currentDishes = await this.getAllDishes();
      const updatedDishes = currentDishes.filter(d => d.id !== id);

      await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(updatedDishes)
      });

      this.updateRecentlyViewedOnDelete(id);
      return;
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readwrite");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.delete(id);

        request.onsuccess = () => {
          this.updateRecentlyViewedOnDelete(id);
          resolve();
        };
        request.onerror = () => reject("删除数据失败");
      } catch (e) {
        reject(e);
      }
    });
  }

  private updateRecentlyViewedOnDelete(id: string) {
    const recentlyViewed = this.getRecentlyViewedIds();
    const updated = recentlyViewed.filter(viewedId => viewedId !== id);
    localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(updated));
  }

  async exportData(): Promise<string> {
    const dishes = await this.getAllDishes();
    return JSON.stringify(dishes, null, 2);
  }

  async importData(json: string): Promise<Dish[]> {
    try {
      const dishes = JSON.parse(json);
      if (!Array.isArray(dishes)) throw new Error("数据格式无效。");

      // For import, we process sequentially to ensure safety
      if (this.cloudKitchenId) {
         // Batch update for cloud
         const current = await this.getAllDishes();
         const merged = [...current];
         for (const d of dishes) {
           const idx = merged.findIndex(m => m.id === d.id);
           if (idx >= 0) merged[idx] = d;
           else merged.push(d);
         }
         await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(merged)
         });
         return merged;
      } else {
        // Local import
        for (const dish of dishes) {
          if (dish.id && dish.name) {
            await this.saveDish(dish);
          }
        }
        return await this.getAllDishes();
      }
    } catch (e) {
      throw e;
    }
  }

  getRecentlyViewedIds(): string[] {
    try {
      const saved = localStorage.getItem(RECENTLY_VIEWED_KEY);
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  }

  recordView(id: string): string[] {
    let ids = this.getRecentlyViewedIds();
    ids = ids.filter(viewedId => viewedId !== id);
    ids.unshift(id);
    ids = ids.slice(0, MAX_RECENT);
    try {
      localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(ids));
    } catch (e) {}
    return ids;
  }

  async migrateFromLocalStorage(): Promise<void> {
    const saved = localStorage.getItem("my-dishes") || localStorage.getItem("delicious-secrets-dishes");
    if (!saved) return;

    try {
      const dishes = JSON.parse(saved);
      if (Array.isArray(dishes)) {
        for (const dish of dishes) {
          await this.saveDish(dish);
        }
        localStorage.removeItem("my-dishes");
        localStorage.removeItem("delicious-secrets-dishes");
      }
    } catch (e) {
      console.error("LocalStorage 迁移失败", e);
    }
  }

  getUserPreferences(): UserPreferences {
    try {
      const saved = localStorage.getItem(PREFERENCES_KEY);
      return saved ? JSON.parse(saved) : { flavors: [] };
    } catch (e) {
      return { flavors: [] };
    }
  }

  saveUserPreferences(prefs: UserPreferences): void {
    try {
      localStorage.setItem(PREFERENCES_KEY, JSON.stringify(prefs));
    } catch (e) {}
  }
}

export const storageService = new StorageService();

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Custom Delete Modal State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  // Cloud Sync State
  const [cloudKitchenId, setCloudKitchenId] = useState<string | null>(storageService.getCloudId());
  const [isCloudModalOpen, setIsCloudModalOpen] = useState(false);
  const [joinKitchenInput, setJoinKitchenInput] = useState('');
  const [isProcessingCloud, setIsProcessingCloud] = useState(false);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  const loadData = async () => {
    try {
      setSyncStatus('syncing');
      const loadedDishes = await storageService.getAllDishes();
      const recentIds = storageService.getRecentlyViewedIds();

      setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
      setRecentlyViewedIds(recentIds);
      setSyncStatus('saved');
    } catch (e) {
      console.error("加载失败", e);
      setSyncStatus('error');
      showToast("数据加载失败", 'error');
    }
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();

        // Check for Shared Kitchen Link
        const urlParams = new URLSearchParams(window.location.search);
        const sharedId = urlParams.get('kitchen');
        if (sharedId) {
          try {
            await storageService.joinCloudKitchen(sharedId);
            setCloudKitchenId(sharedId);
            showToast("已成功加入共享厨房！", 'success');
            // Clean URL
            window.history.replaceState({}, document.title, window.location.pathname);
          } catch (e) {
            showToast("加入共享厨房失败，链接可能已失效", 'error');
          }
        }

        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "保存失败，请检查浏览器存储设置。";
      showToast(errorMsg, 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;

    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "更新失败，存储空间可能已满。";
      showToast(errorMsg, 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const requestDeleteDish = (id: string) => {
    setConfirmDeleteId(id);
  };

  const executeDeleteDish = async () => {
    if (!confirmDeleteId) return;
    const id = confirmDeleteId;

    try {
      setSyncStatus('syncing');
      await storageService.deleteDish(id);
      setDishes(prev => prev.filter(d => d.id !== id));
      setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
      setSyncStatus('saved');
      showToast("菜谱已删除", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("删除失败", 'error');
    } finally {
      setConfirmDeleteId(null);
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  // Cloud Sync Handlers
  const handleCreateCloudKitchen = async () => {
    setIsProcessingCloud(true);
    try {
      const id = await storageService.createCloudKitchen(dishes);
      setCloudKitchenId(id);
      showToast("云端厨房创建成功！", 'success');
    } catch (e) {
      showToast("创建失败，请稍后重试", 'error');
    } finally {
      setIsProcessingCloud(false);
    }
  };

  const handleJoinCloudKitchen = async () => {
    if (!joinKitchenInput.trim()) return;
    setIsProcessingCloud(true);
    try {
      await storageService.joinCloudKitchen(joinKitchenInput.trim());
      setCloudKitchenId(joinKitchenInput.trim());
      await loadData();
      showToast("成功加入厨房！", 'success');
      setJoinKitchenInput('');
    } catch (e) {
      showToast("加入失败：ID 无效或网络错误", 'error');
    } finally {
      setIsProcessingCloud(false);
    }
  };

  const handleLeaveCloudKitchen = async () => {
    storageService.leaveCloudKitchen();
    setCloudKitchenId(null);
    await loadData();
    showToast("已断开连接，回到本地模式", 'success');
    setIsCloudModalOpen(false);
  };

  const handleCopyLink = () => {
    if (!cloudKitchenId) return;
    const url = `${window.location.origin}${window.location.pathname}?kitchen=${cloudKitchenId}`;
    navigator.clipboard.writeText(url).then(() => {
      showToast("链接已复制，快发给朋友吧！", 'success');
    });
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={recentlyViewedDishes}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      case 'suggest':
        return <SuggestView onAddDish={addDish} preferences={preferences} onShowToast={showToast} />;
      case 'discovery':
        return (
          <DiscoveryView 
            onAddDish={addDish} 
            onViewRecipe={viewRecipe} 
            preferences={preferences} 
            cache={discoveryCache}
            onUpdateCache={setDiscoveryCache}
          />
        );
      case 'recipe':
        const dish = dishes.find(d => d.id === selectedDishId);
        return dish ? (
          <RecipeView 
            dish={dish} 
            onBack={() => setCurrentView('collection')} 
            onUpdateDish={updateDish}
          />
        ) : (
          <CollectionView 
            dishes={dishes} 
            pendingDishes={pendingDishes}
            recentlyViewedDishes={[]}
            onGenerateInBackground={startBackgroundGeneration}
            onDeleteDish={requestDeleteDish} 
            onViewRecipe={viewRecipe} 
            onBulkUpdate={bulkUpdateDishes}
            onRefreshImage={regenerateDishImage}
            preferences={preferences}
            onUpdatePreferences={updatePreferences}
            onShowToast={showToast}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col w-full max-w-7xl mx-auto bg-white shadow-xl relative">
      <header className="bg-orange-500 text-white p-4 sm:p-6 sticky top-0 z-30 flex flex-wrap gap-4 justify-between items-center shadow-md">
        <h1 className="text-xl sm:text-2xl font-bold flex items-center gap-2 cursor-pointer whitespace-nowrap" onClick={() => setCurrentView('collection')}>
          <span className="text-2xl sm:text-3xl">🍴</span>
          WhatToEat
        </h1>

        <div className="flex flex-1 justify-end md:justify-between items-center gap-4">
          <div className="hidden md:flex gap-2 overflow-x-auto max-w-full scrollbar-hide pb-1 sm:pb-0">
            <button 
              onClick={() => setCurrentView('collection')}
              className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
            >
              我的菜谱
            </button>
            <button 
              onClick={() => setCurrentView('discovery')}
              className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'discovery' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
            >
              发现灵感
            </button>
            <button 
              onClick={() => setCurrentView('suggest')}
              className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'suggest' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
            >
              今天做什么？
            </button>
          </div>

          <button 
            onClick={() => setIsCloudModalOpen(true)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold transition border ${cloudKitchenId ? 'bg-green-500 border-green-400 text-white shadow-inner' : 'bg-orange-400 border-orange-300 text-white hover:bg-orange-300'}`}
          >
            <span className="text-sm">{cloudKitchenId ? '☁️' : '🌩️'}</span>
            <span className="hidden sm:inline">{cloudKitchenId ? '已同步' : '云同步'}</span>
          </button>
        </div>

        {/* Mobile Nav */}
        <div className="flex md:hidden w-full gap-2 overflow-x-auto scrollbar-hide pb-1">
          <button 
            onClick={() => setCurrentView('collection')}
            className={`flex-shrink-0 px-4 py-2 rounded-full transition whitespace-nowrap text-xs sm:text-sm ${currentView === 'collection' ? 'bg-white text-orange-600 font-bold' : 'hover:bg-orange-600'}`}
          >
