      if (!location) throw new Error("创建失败：无法获取云端ID。请检查网络或稍后重试。");

      const id = location.split('/').pop();
      if (!id) throw new Error("ID 解析失败");

      this.setCloudId(id);
      return id;
    } catch (e) {
      console.error("Create Cloud Kitchen Error:", e);
      if (e instanceof TypeError && e.message === "Failed to fetch") {
        throw new Error("网络请求失败。请检查您的网络连接或 AdBlock 设置。");
      }
      throw e;
    }
  }

  async joinCloudKitchen(id: string): Promise<void> {
    try {
      const response = await fetch(`${CLOUD_API_BASE}/${id}`, {
        headers: { 'Accept': 'application/json' }
      });
      if (!response.ok) {
        if (response.status === 404) throw new Error("未找到该厨房ID");
        throw new Error("无效的厨房ID或网络错误");
      }
      // Validate data structure lightly
      const data = await response.json();
      if (!Array.isArray(data)) throw new Error("该ID对应的数据不是有效的菜谱库");

      this.setCloudId(id);
    } catch (e) {
      console.error("Join Cloud Kitchen Error:", e);
      if (e instanceof TypeError && e.message === "Failed to fetch") {
        throw new Error("网络请求失败。请检查您的网络连接。");
      }
      throw e;
    }
  }

  leaveCloudKitchen() {
    this.cloudKitchenId = null;
    localStorage.removeItem(CLOUD_ID_KEY);
  }

  private setCloudId(id: string) {
    this.cloudKitchenId = id;
    localStorage.setItem(CLOUD_ID_KEY, id);
  }

  /**
   * 初始化数据库 - 采用单例 Promise 模式，防止并发冲突
   */
  async init(): Promise<void> {
    if (this.db) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      // 尝试静默迁移旧数据（不阻塞主逻辑）
      try {
        await this.tryMigrateFromOldDB();
      } catch (e) {
        console.warn("旧数据库迁移失败，跳过...", e);
      }

      return new Promise((resolve, reject) => {
        if (!window.indexedDB) {
          return reject("您的浏览器不支持本地数据库，请更换现代浏览器。");
        }

        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
          console.error("IndexedDB 开启失败:", event);
          this.initPromise = null; // 允许下次重试
          reject("无法打开本地存储。如果是无痕模式，请尝试正常模式访问。");
        };

        request.onsuccess = (event) => {
          this.db = (event.target as IDBOpenDBRequest).result;

          this.db.onversionchange = () => {
            this.db?.close();
            window.location.reload();
          };

          resolve();
        };

        request.onupgradeneeded = (event) => {
          const db = (event.target as IDBOpenDBRequest).result;
          if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: "id" });
          }
        };
      });
    })();

    return this.initPromise;
  }

  private async tryMigrateFromOldDB(): Promise<void> {
    return new Promise((resolve) => {
      // 仅仅是尝试开启，如果不成功或不存在则直接 resolve
      const request = indexedDB.open(OLD_DB_NAME);
      request.onsuccess = (event) => {
        const oldDb = (event.target as IDBOpenDBRequest).result;
        if (oldDb.objectStoreNames.contains(STORE_NAME)) {
          const transaction = oldDb.transaction([STORE_NAME], "readonly");
          const store = transaction.objectStore(STORE_NAME);
          const allDataRequest = store.getAll();

          allDataRequest.onsuccess = () => {
            // 这里只是检测，真正的迁移目前在 initApp 逻辑中处理
            oldDb.close();
            resolve();
          };
          allDataRequest.onerror = () => {
            oldDb.close();
            resolve();
          };
        } else {
          oldDb.close();
          resolve();
        }
      };
      request.onerror = () => resolve();
    });
  }

  async getAllDishes(): Promise<Dish[]> {
    // Mode Check: Cloud
    if (this.cloudKitchenId) {
      try {
        const response = await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
           headers: { 'Accept': 'application/json' }
        });
        if (!response.ok) {
           if (response.status === 404) {
             // ID失效
             this.leaveCloudKitchen();
             throw new Error("云端厨房ID已失效，已自动切换回本地模式。");
           }
           throw new Error(`云端同步失败 (${response.status})`);
        }
        const data = await response.json();
        return Array.isArray(data) ? data : [];
      } catch (e) {
        console.error("Get All Dishes Error:", e);
        if (e instanceof TypeError && e.message === "Failed to fetch") {
           throw new Error("网络连接失败，无法获取云端数据。");
        }
        throw e;
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readonly");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject("读取数据失败");
      } catch (e) {
        reject(e);
      }
    });
  }

  async saveDish(dish: Dish): Promise<void> {
    // Mode Check: Cloud
    if (this.cloudKitchenId) {
      try {
        const currentDishes = await this.getAllDishes();
        const index = currentDishes.findIndex(d => d.id === dish.id);
        if (index >= 0) {
          currentDishes[index] = dish;
        } else {
          currentDishes.push(dish);
        }

        const cleanDishes = this.prepareForCloud(currentDishes);

        const response = await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
          body: JSON.stringify(cleanDishes)
        });

        if (!response.ok) throw new Error("云端保存失败");
        return;
      } catch (e) {
        console.error("Save Dish Error:", e);
        if (e instanceof TypeError && e.message === "Failed to fetch") {
          throw new Error("网络请求失败，无法保存到云端。");
        }
        throw e;
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readwrite");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.put(dish);

        request.onsuccess = () => resolve();
        request.onerror = (event) => {
          const error = (event.target as any).error;
          if (error && error.name === 'QuotaExceededError') {
            reject("存储空间已满。请删除一些不需要的菜谱或清理浏览器缓存。");
          } else {
            reject("保存失败，请稍后重试。");
          }
        };
      } catch (e) {
        reject(e);
      }
    });
  }

  async deleteDish(id: string): Promise<void> {
    // Mode Check: Cloud
    if (this.cloudKitchenId) {
      try {
        const currentDishes = await this.getAllDishes();
        const updatedDishes = currentDishes.filter(d => d.id !== id);

        const cleanDishes = this.prepareForCloud(updatedDishes);

        const response = await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
          body: JSON.stringify(cleanDishes)
        });

        if (!response.ok) throw new Error("云端删除失败");
        this.updateRecentlyViewedOnDelete(id);
        return;
      } catch (e) {
         console.error("Delete Dish Error:", e);
         throw e;
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readwrite");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.delete(id);

        request.onsuccess = () => {
          this.updateRecentlyViewedOnDelete(id);
          resolve();
        };
        request.onerror = () => reject("删除数据失败");
      } catch (e) {
        reject(e);
      }
    });
  }

  private updateRecentlyViewedOnDelete(id: string) {
    const recentlyViewed = this.getRecentlyViewedIds();
    const updated = recentlyViewed.filter(viewedId => viewedId !== id);
    localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(updated));
  }

  async exportData(): Promise<string> {
    const dishes = await this.getAllDishes();
    return JSON.stringify(dishes, null, 2);
  }

  async importData(json: string): Promise<Dish[]> {
    try {
      const dishes = JSON.parse(json);
      if (!Array.isArray(dishes)) throw new Error("数据格式无效。");

      // For import, we process sequentially to ensure safety
      if (this.cloudKitchenId) {
         // Batch update for cloud
         const current = await this.getAllDishes();
         const merged = [...current];
         for (const d of dishes) {
           const idx = merged.findIndex(m => m.id === d.id);
           if (idx >= 0) merged[idx] = d;
           else merged.push(d);
         }

         const cleanDishes = this.prepareForCloud(merged);

         await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(cleanDishes)
         });
         return merged;
      } else {
        // Local import
        for (const dish of dishes) {
          if (dish.id && dish.name) {
            await this.saveDish(dish);
          }
        }
        return await this.getAllDishes();
      }
    } catch (e) {
      throw e;
    }
  }

  getRecentlyViewedIds(): string[] {
    try {
      const saved = localStorage.getItem(RECENTLY_VIEWED_KEY);
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  }

  recordView(id: string): string[] {
    let ids = this.getRecentlyViewedIds();
    ids = ids.filter(viewedId => viewedId !== id);
    ids.unshift(id);
    ids = ids.slice(0, MAX_RECENT);
    try {
      localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(ids));
    } catch (e) {}
    return ids;
  }

  async migrateFromLocalStorage(): Promise<void> {
    const saved = localStorage.getItem("my-dishes") || localStorage.getItem("delicious-secrets-dishes");
    if (!saved) return;

    try {
      const dishes = JSON.parse(saved);
      if (Array.isArray(dishes)) {
        for (const dish of dishes) {
          await this.saveDish(dish);
        }
        localStorage.removeItem("my-dishes");
        localStorage.removeItem("delicious-secrets-dishes");
      }
    } catch (e) {
      console.error("LocalStorage 迁移失败", e);
    }
  }

  getUserPreferences(): UserPreferences {
    try {
      const saved = localStorage.getItem(PREFERENCES_KEY);
      return saved ? JSON.parse(saved) : { flavors: [] };
    } catch (e) {
      return { flavors: [] };
    }
  }

  saveUserPreferences(prefs: UserPreferences): void {
    try {
      localStorage.setItem(PREFERENCES_KEY, JSON.stringify(prefs));
    } catch (e) {}
  }
}

