    const cleanDishes = this.prepareForCloud(initialDishes);
    try {
      const response = await fetch(CLOUD_API_BASE, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json', 
          'Accept': 'application/json' 
        },
        body: JSON.stringify(cleanDishes)
      });

      if (!response.ok) throw new Error(`连接云端失败: ${response.status} ${response.statusText}`);

      const location = response.headers.get('Location');
      if (!location) throw new Error("创建失败：无法获取云端ID。请检查网络或稍后重试。");

      const id = location.split('/').pop();
      if (!id) throw new Error("ID 解析失败");

      this.setCloudId(id);
      return id;
    } catch (e) {
      console.error("Create Cloud Kitchen Error:", e);
      if (e instanceof TypeError && e.message === "Failed to fetch") {
        throw new Error("无法连接服务器。请检查网络，或尝试关闭广告拦截插件。");
      }
      throw e;
    }
  }

