           const idx = merged.findIndex(m => m.id === d.id);
           if (idx >= 0) merged[idx] = d;
           else merged.push(d);
         }

         const cleanDishes = this.prepareForCloud(merged);

         await fetch(`${CLOUD_API_BASE}/${this.cloudKitchenId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(cleanDishes)
         });
         return merged;
      } else {
        // Local import
        for (const dish of dishes) {
          if (dish.id && dish.name) {
            await this.saveDish(dish);
          }
        }
        return await this.getAllDishes();
      }
    } catch (e) {
      throw e;
    }
  }

  getRecentlyViewedIds(): string[] {
    try {
      const saved = localStorage.getItem(RECENTLY_VIEWED_KEY);
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  }

  recordView(id: string): string[] {
    let ids = this.getRecentlyViewedIds();
    ids = ids.filter(viewedId => viewedId !== id);
    ids.unshift(id);
    ids = ids.slice(0, MAX_RECENT);
    try {
      localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(ids));
    } catch (e) {}
    return ids;
  }

  async migrateFromLocalStorage(): Promise<void> {
    const saved = localStorage.getItem("my-dishes") || localStorage.getItem("delicious-secrets-dishes");
    if (!saved) return;

    try {
      const dishes = JSON.parse(saved);
      if (Array.isArray(dishes)) {
        for (const dish of dishes) {
          await this.saveDish(dish);
        }
        localStorage.removeItem("my-dishes");
        localStorage.removeItem("delicious-secrets-dishes");
      }
    } catch (e) {
      console.error("LocalStorage 迁移失败", e);
    }
  }

  getUserPreferences(): UserPreferences {
    try {
      const saved = localStorage.getItem(PREFERENCES_KEY);
      return saved ? JSON.parse(saved) : { flavors: [] };
    } catch (e) {
      return { flavors: [] };
    }
  }

  saveUserPreferences(prefs: UserPreferences): void {
    try {
      localStorage.setItem(PREFERENCES_KEY, JSON.stringify(prefs));
    } catch (e) {}
  }
}

export const storageService = new StorageService();

import React, { useState, useEffect } from 'react';
import { Dish, UserPreferences, InstructionStep, SuggestedDish } from './types';
import CollectionView from './views/CollectionView';
import SuggestView from './views/SuggestView';
import RecipeView from './views/RecipeView';
import DiscoveryView from './views/DiscoveryView';
import GlobalChatBot from './components/GlobalChatBot';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';

interface PendingDish {
  id: string;
  name: string;
  status: string;
}

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'collection' | 'suggest' | 'recipe' | 'discovery'>('collection');
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [pendingDishes, setPendingDishes] = useState<PendingDish[]>([]);
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);
  const [selectedDishId, setSelectedDishId] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'syncing' | 'saved' | 'error'>('saved');
  const [preferences, setPreferences] = useState<UserPreferences>({ flavors: [] });

  const [discoveryCache, setDiscoveryCache] = useState<SuggestedDish[]>([]);
  const [toast, setToast] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  // Custom Delete Modal State
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  // Cloud Sync State
  const [cloudKitchenId, setCloudKitchenId] = useState<string | null>(storageService.getCloudId());
  const [isCloudModalOpen, setIsCloudModalOpen] = useState(false);
  const [joinKitchenInput, setJoinKitchenInput] = useState('');
  const [isProcessingCloud, setIsProcessingCloud] = useState(false);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 2000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
  };

  const loadData = async () => {
    try {
      setSyncStatus('syncing');
      const loadedDishes = await storageService.getAllDishes();
      const recentIds = storageService.getRecentlyViewedIds();

      setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
      setRecentlyViewedIds(recentIds);
      setSyncStatus('saved');
    } catch (e) {
      console.error("加载失败", e);
      setSyncStatus('error');
      showToast("数据加载失败", 'error');
    }
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        setSyncStatus('syncing');
        await storageService.init();
        await storageService.migrateFromLocalStorage();

        // Check for Shared Kitchen Link
        const urlParams = new URLSearchParams(window.location.search);
        const sharedId = urlParams.get('kitchen');
        if (sharedId) {
          try {
            await storageService.joinCloudKitchen(sharedId);
            setCloudKitchenId(sharedId);
            showToast("已成功加入共享厨房！", 'success');
            // Clean URL
            window.history.replaceState({}, document.title, window.location.pathname);
          } catch (e) {
            showToast("加入共享厨房失败，链接可能已失效", 'error');
          }
        }

        const loadedDishes = await storageService.getAllDishes();
        const recentIds = storageService.getRecentlyViewedIds();
        const savedPrefs = storageService.getUserPreferences();

        setDishes(loadedDishes.sort((a, b) => b.createdAt - a.createdAt));
        setRecentlyViewedIds(recentIds);
        setPreferences(savedPrefs);
        setSyncStatus('saved');
      } catch (e) {
        console.error("初始化失败", e);
        setSyncStatus('error');
      } finally {
        setTimeout(() => setIsInitializing(false), 800);
      }
    };

    initApp();
  }, []);

  const addDish = async (dish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(dish);
      setDishes(prev => [dish, ...prev]);
      setSyncStatus('saved');
      showToast(`已成功收藏 ${dish.name}！`, 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "保存失败，请检查浏览器存储设置。";
      showToast(errorMsg, 'error');
    }
  };

  const regenerateDishImage = async (id: string) => {
    const dish = dishes.find(d => d.id === id);
    if (!dish) return;

    try {
      setSyncStatus('syncing');
      const newUrl = await geminiService.generateDishImage(dish.name);
      const updatedDish = { ...dish, imageUrl: newUrl };
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("封面图已重新生成", 'success');
    } catch (err) {
      setSyncStatus('error');
      showToast("生成封面失败，请重试", 'error');
    }
  };

  const startBackgroundGeneration = async (dishName: string) => {
    const tempId = Date.now().toString();
    setPendingDishes(prev => [...prev, { id: tempId, name: dishName, status: '构思中...' }]);

    try {
      const details = await geminiService.getRecipeDetails(dishName, preferences);
      setPendingDishes(prev => prev.map(p => p.id === tempId ? { ...p, status: '绘图中...' } : p));

      let coverUrl: string | undefined = undefined;
      try {
        coverUrl = await geminiService.generateDishImage(dishName);
      } catch (imgErr) {
        console.warn("Cover image failed", imgErr);
      }

      const finalSteps: InstructionStep[] = details.instructions.map(step => ({
        ...step,
        imageUrl: undefined
      }));

      const newDish: Dish = {
        id: tempId,
        name: dishName,
        ...details,
        instructions: finalSteps,
        imageUrl: coverUrl,
        createdAt: Date.now()
      };

      await addDish(newDish);
    } catch (err) {
      console.error(err);
      showToast(`${dishName} 生成失败，请重试。`, 'error');
    } finally {
      setPendingDishes(prev => prev.filter(p => p.id !== tempId));
    }
  };

  const updateDish = async (updatedDish: Dish) => {
    try {
      setSyncStatus('syncing');
      await storageService.saveDish(updatedDish);
      setDishes(prev => prev.map(d => d.id === updatedDish.id ? updatedDish : d));
      setSyncStatus('saved');
      showToast("菜谱已更新", 'success');
    } catch (e) {
      setSyncStatus('error');
      const errorMsg = typeof e === 'string' ? e : "更新失败，存储空间可能已满。";
      showToast(errorMsg, 'error');
    }
  };

  const bulkUpdateDishes = (newDishes: Dish[]) => {
    setDishes(newDishes.sort((a, b) => b.createdAt - a.createdAt));
    setSyncStatus('saved');
  };

  const requestDeleteDish = (id: string) => {
    setConfirmDeleteId(id);
  };

  const executeDeleteDish = async () => {
    if (!confirmDeleteId) return;
    const id = confirmDeleteId;

    try {
      setSyncStatus('syncing');
      await storageService.deleteDish(id);
      setDishes(prev => prev.filter(d => d.id !== id));
      setRecentlyViewedIds(prev => prev.filter(rid => rid !== id));
      setSyncStatus('saved');
      showToast("菜谱已删除", 'success');
    } catch (e) {
      setSyncStatus('error');
      showToast("删除失败", 'error');
    } finally {
      setConfirmDeleteId(null);
    }
  };

  const updatePreferences = (newPrefs: UserPreferences) => {
    setPreferences(newPrefs);
    storageService.saveUserPreferences(newPrefs);
  };

  const viewRecipe = (id: string) => {
    const updatedRecentIds = storageService.recordView(id);
    setRecentlyViewedIds(updatedRecentIds);
    setSelectedDishId(id);
    setCurrentView('recipe');
  };

  // Cloud Sync Handlers
  const handleCreateCloudKitchen = async () => {
    setIsProcessingCloud(true);
    try {
      const id = await storageService.createCloudKitchen(dishes);
      setCloudKitchenId(id);
      showToast("云端厨房创建成功！", 'success');
    } catch (e) {
      const msg = e instanceof Error ? e.message : "创建失败，请稍后重试";
      showToast(msg, 'error');
    } finally {
      setIsProcessingCloud(false);
    }
  };

  const handleJoinCloudKitchen = async () => {
    if (!joinKitchenInput.trim()) return;
    setIsProcessingCloud(true);
    try {
      await storageService.joinCloudKitchen(joinKitchenInput.trim());
      setCloudKitchenId(joinKitchenInput.trim());
      await loadData();
      showToast("成功加入厨房！", 'success');
      setJoinKitchenInput('');
    } catch (e) {
      const msg = e instanceof Error ? e.message : "加入失败，请检查 ID 或网络";
      showToast(msg, 'error');
    } finally {
      setIsProcessingCloud(false);
    }
  };

  const handleLeaveCloudKitchen = async () => {
    storageService.leaveCloudKitchen();
    setCloudKitchenId(null);
    await loadData();
    showToast("已断开连接，回到本地模式", 'success');
    setIsCloudModalOpen(false);
  };

  const handleCopyLink = () => {
    if (!cloudKitchenId) return;
    const url = `${window.location.origin}${window.location.pathname}?kitchen=${cloudKitchenId}`;
    navigator.clipboard.writeText(url).then(() => {
      showToast("链接已复制，快发给朋友吧！", 'success');
    });
  };

  const renderView = () => {
    if (isInitializing) {
      return (
        <div className="flex flex-col items-center justify-center py-40 animate-in fade-in duration-700">
          <div className="relative w-20 h-20">
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="loader-ring"></div>
            <div className="absolute inset-0 flex items-center justify-center text-2xl">🍲</div>
          </div>
          <div className="mt-12 flex flex-col items-center">
            <p className="text-gray-400 font-black tracking-[0.2em] uppercase text-[10px] animate-pulse">Initializing Kitchen</p>
            <p className="mt-2 text-orange-500 font-bold text-sm">正在加载您的私人菜谱库...</p>
          </div>
        </div>
      );
    }

    switch (currentView) {
      case 'collection':
        const recentlyViewedDishes = recentlyViewedIds
          .map(id => dishes.find(d => d.id === id))
          .filter((d): d is Dish => !!d);

        return (
          <CollectionView 
