export { db };
export const isFirebaseConfigured = () => firebaseConfig.apiKey !== "YOUR_API_KEY_HERE";

import { Dish, UserPreferences } from "../types";
import { db, isFirebaseConfigured } from "./firebase";
import { ref, set, get, child, onValue, off } from "firebase/database";

const DB_NAME = "WhatToEatDB";
const OLD_DB_NAME = "DeliciousSecretsDB";
const STORE_NAME = "dishes";
const DB_VERSION = 1;
const RECENTLY_VIEWED_KEY = "recently-viewed-ids";
const PREFERENCES_KEY = "user-preferences";
const MAX_RECENT = 5;
const CLOUD_ID_KEY = "whattoeat-cloud-id";

// Limit for Firebase allows larger payloads than JSONBlob, but we still want to be efficient.
// Base64 images are fine in Firebase, but extremely large ones can slow down initial sync.
const MAX_IMAGE_SIZE_FOR_CLOUD = 500000; // ~500KB limit for images

export class StorageService {
  private db: IDBDatabase | null = null;
  private initPromise: Promise<void> | null = null;
  private cloudKitchenId: string | null = null;
  private dishesListener: ((dishes: Dish[]) => void) | null = null;
  private unsubscribeFirebase: (() => void) | null = null;

  constructor() {
    this.cloudKitchenId = localStorage.getItem(CLOUD_ID_KEY);
    // If we have a cloud ID on boot, try to reconnect the listener immediately if possible
    if (this.cloudKitchenId && isFirebaseConfigured()) {
       // Listener will be attached when `subscribe` is called by the App component
    }
  }

  /**
   * Helper: Prepare dishes for cloud storage
   */
  private prepareForCloud(dishes: Dish[]): Dish[] {
    return dishes.map(d => ({
      ...d,
      imageUrl: (d.imageUrl && d.imageUrl.length < MAX_IMAGE_SIZE_FOR_CLOUD) ? d.imageUrl : undefined,
      instructions: Array.isArray(d.instructions) ? d.instructions.map(step => {
        if (typeof step === 'string') return { text: step, timeMinutes: 0 };
        return {
          ...step,
          imageUrl: (step.imageUrl && step.imageUrl.length < MAX_IMAGE_SIZE_FOR_CLOUD) ? step.imageUrl : undefined
        };
      }) : []
    }));
  }

  /**
   * Subscribes to changes. 
   * If Cloud Mode is active, listens to Firebase.
   * If Local Mode, this is largely a no-op (react state updates handle local immediately), 
   * but provided for interface consistency.
   */
  subscribe(callback: (dishes: Dish[]) => void) {
    this.dishesListener = callback;
    if (this.cloudKitchenId && isFirebaseConfigured()) {
      this.attachFirebaseListener();
    }
  }

  unsubscribe() {
    this.dishesListener = null;
    if (this.unsubscribeFirebase) {
      this.unsubscribeFirebase();
      this.unsubscribeFirebase = null;
    }
  }

  private attachFirebaseListener() {
    if (!db || !this.cloudKitchenId) return;

    // Detach old listener if exists
    if (this.unsubscribeFirebase) this.unsubscribeFirebase();

    const dishesRef = ref(db, `kitchens/${this.cloudKitchenId}`);

    const handler = onValue(dishesRef, (snapshot) => {
      const data = snapshot.val();
      if (this.dishesListener) {
         const dishList = Array.isArray(data) ? data : [];
         this.dishesListener(dishList);
      }
    }, (error) => {
      console.error("Firebase Sync Error:", error);
    });

    this.unsubscribeFirebase = () => off(dishesRef, 'value', handler);
  }

  /**
   * Cloud Sync Methods
   */
  getCloudId(): string | null {
    return this.cloudKitchenId;
  }

  async createCloudKitchen(initialDishes: Dish[]): Promise<string> {
    if (!isFirebaseConfigured()) {
      throw new Error("请先在 services/firebase.ts 中配置您的 Firebase 信息。");
    }
    if (!db) throw new Error("Firebase 未初始化");

    // Generate a simple 6-char ID for easier sharing
    const newId = Math.random().toString(36).substring(2, 8).toUpperCase();

    const cleanDishes = this.prepareForCloud(initialDishes);

    try {
      await set(ref(db, `kitchens/${newId}`), cleanDishes);
      this.setCloudId(newId);
      this.attachFirebaseListener();
      return newId;
    } catch (e) {
      console.error("Firebase Create Error", e);
      throw new Error("创建云端厨房失败，请检查网络或 Firebase 配置。");
    }
  }

  async joinCloudKitchen(id: string): Promise<void> {
    if (!isFirebaseConfigured()) {
      throw new Error("请先在 services/firebase.ts 中配置您的 Firebase 信息。");
    }
    if (!db) throw new Error("Firebase 未初始化");

    try {
      const snapshot = await get(child(ref(db), `kitchens/${id}`));
      if (!snapshot.exists()) {
        throw new Error("未找到该 ID 的厨房，请确认 ID 是否正确。");
      }

      this.setCloudId(id);
      this.attachFirebaseListener();
    } catch (e) {
      console.error("Firebase Join Error", e);
      throw e;
    }
  }

  leaveCloudKitchen() {
    this.cloudKitchenId = null;
    localStorage.removeItem(CLOUD_ID_KEY);
    if (this.unsubscribeFirebase) {
      this.unsubscribeFirebase();
      this.unsubscribeFirebase = null;
    }
    // Re-trigger load from local DB if needed, handled by App logic usually
  }

  private setCloudId(id: string) {
    this.cloudKitchenId = id;
    localStorage.setItem(CLOUD_ID_KEY, id);
  }

  /**
   * Local Database Init
   */
  async init(): Promise<void> {
    if (this.db) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      try { await this.tryMigrateFromOldDB(); } catch (e) {}

      return new Promise((resolve, reject) => {
        if (!window.indexedDB) return reject("浏览器不支持 IndexedDB");
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onerror = () => reject("无法打开本地数据库");
        request.onsuccess = (event) => {
          this.db = (event.target as IDBOpenDBRequest).result;
          resolve();
        };
        request.onupgradeneeded = (event) => {
          const db = (event.target as IDBOpenDBRequest).result;
          if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: "id" });
          }
        };
      });
    })();
    return this.initPromise;
  }

  private async tryMigrateFromOldDB(): Promise<void> {
    return new Promise((resolve) => {
      const request = indexedDB.open(OLD_DB_NAME);
      request.onsuccess = (event) => {
        const oldDb = (event.target as IDBOpenDBRequest).result;
        if (oldDb.objectStoreNames.contains(STORE_NAME)) {
           // Migration logic skipped for brevity, assumed done
           oldDb.close();
        }
        resolve();
      };
      request.onerror = () => resolve();
    });
  }

  async getAllDishes(): Promise<Dish[]> {
    // Mode Check: Cloud
    if (this.cloudKitchenId && isFirebaseConfigured() && db) {
      try {
        const snapshot = await get(child(ref(db), `kitchens/${this.cloudKitchenId}`));
        if (snapshot.exists()) {
          const data = snapshot.val();
          return Array.isArray(data) ? data : [];
        } else {
          // ID might have expired or been deleted
          this.leaveCloudKitchen();
          throw new Error("云端厨房已不存在");
        }
      } catch (e) {
        console.error("Get All Dishes Error:", e);
        // Fallback to local if network fails? Or throw?
        // Throwing lets the UI show a specific error
        throw e;
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      try {
        const transaction = this.db.transaction([STORE_NAME], "readonly");
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject("读取数据失败");
      } catch (e) { reject(e); }
    });
  }

  async saveDish(dish: Dish): Promise<void> {
    // Mode Check: Cloud
    if (this.cloudKitchenId && isFirebaseConfigured() && db) {
      try {
        // Fetch current list to append/update
        // Note: Real apps might use object maps (key:value) instead of arrays to avoid race conditions,
        // but for this simple list, reading then writing array is okay for small groups.
        const currentDishes = await this.getAllDishes();
        const index = currentDishes.findIndex(d => d.id === dish.id);
        if (index >= 0) {
          currentDishes[index] = dish;
        } else {
          currentDishes.push(dish);
        }

        const cleanDishes = this.prepareForCloud(currentDishes);
        await set(ref(db, `kitchens/${this.cloudKitchenId}`), cleanDishes);
        return;
      } catch (e) {
        throw new Error("同步到云端失败");
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      const transaction = this.db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(dish);
      request.onsuccess = () => resolve();
      request.onerror = () => reject("保存失败");
    });
  }

  async deleteDish(id: string): Promise<void> {
    // Mode Check: Cloud
    if (this.cloudKitchenId && isFirebaseConfigured() && db) {
      try {
        const currentDishes = await this.getAllDishes();
        const updatedDishes = currentDishes.filter(d => d.id !== id);
        const cleanDishes = this.prepareForCloud(updatedDishes);

        await set(ref(db, `kitchens/${this.cloudKitchenId}`), cleanDishes);
        this.updateRecentlyViewedOnDelete(id);
        return;
      } catch (e) {
         throw new Error("云端删除失败");
      }
    }

    // Mode Check: Local
    await this.init();
    return new Promise((resolve, reject) => {
      if (!this.db) return reject("数据库未就绪");
      const transaction = this.db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);
      request.onsuccess = () => {
        this.updateRecentlyViewedOnDelete(id);
        resolve();
      };
      request.onerror = () => reject("删除失败");
    });
  }

  private updateRecentlyViewedOnDelete(id: string) {
    const recentlyViewed = this.getRecentlyViewedIds();
    const updated = recentlyViewed.filter(viewedId => viewedId !== id);
    localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(updated));
  }

  async exportData(): Promise<string> {
    const dishes = await this.getAllDishes();
    return JSON.stringify(dishes, null, 2);
  }

  async importData(json: string): Promise<Dish[]> {
    const dishes = JSON.parse(json);
    if (!Array.isArray(dishes)) throw new Error("无效数据");

    if (this.cloudKitchenId && isFirebaseConfigured() && db) {
       const current = await this.getAllDishes();
       const merged = [...current];
       for (const d of dishes) {
         const idx = merged.findIndex(m => m.id === d.id);
         if (idx >= 0) merged[idx] = d;
         else merged.push(d);
       }
       const cleanDishes = this.prepareForCloud(merged);
       await set(ref(db, `kitchens/${this.cloudKitchenId}`), cleanDishes);
       return merged;
    } else {
      for (const dish of dishes) {
        if (dish.id) await this.saveDish(dish);
      }
      return await this.getAllDishes();
    }
  }

  getRecentlyViewedIds(): string[] {
    try {
      const saved = localStorage.getItem(RECENTLY_VIEWED_KEY);
      return saved ? JSON.parse(saved) : [];
    } catch (e) { return []; }
  }

  recordView(id: string): string[] {
    let ids = this.getRecentlyViewedIds();
    ids = ids.filter(viewedId => viewedId !== id);
    ids.unshift(id);
    ids = ids.slice(0, MAX_RECENT);
    localStorage.setItem(RECENTLY_VIEWED_KEY, JSON.stringify(ids));
    return ids;
  }

  async migrateFromLocalStorage(): Promise<void> {
    // Migration logic
  }

  getUserPreferences(): UserPreferences {
    try {
      const saved = localStorage.getItem(PREFERENCES_KEY);
      return saved ? JSON.parse(saved) : { flavors: [] };
    } catch (e) { return { flavors: [] }; }
  }

  saveUserPreferences(prefs: UserPreferences): void {
    localStorage.setItem(PREFERENCES_KEY, JSON.stringify(prefs));
  }
}

export const storageService = new StorageService();
